@dataclass(frozen=True)
class FlightEsiSession:
    character_id: int
    character_name: str
    corporation_id: int
    corporation_name: str
    alliance_id: int | None
    alliance_name: str
    scopes: tuple[str, ...]
    access_token: str
    connected_at: str
    expires_at: float
    membership_ok: bool = True

    @property
    def expired(self) -> bool:
        return self.expires_at <= time.time()

    @property
    def expires_in_seconds(self) -> int:
        return max(0, int(self.expires_at - time.time()))

    def to_public_dict(self) -> dict[str, Any]:
        return {
            "character_id": self.character_id,
            "character_name": self.character_name,
            "corporation_id": self.corporation_id,
            "corporation_name": self.corporation_name,
            "alliance_id": self.alliance_id,
            "alliance_name": self.alliance_name,
            "scopes": list(self.scopes),
            "membership_ok": self.membership_ok,
            "connected_at": self.connected_at,
            "expires_in_seconds": self.expires_in_seconds,
        }


class FlightEsiSessionStore:
    def __init__(self) -> None:
        self._sessions: dict[str, FlightEsiSession] = {}
        self._lock = threading.Lock()

    def create(self, pilot: VerifiedPilot, *, access_token: str, expires_in: Any = None) -> str:
        ttl_seconds = clean_token_ttl_seconds(expires_in)
        session_id = secrets.token_urlsafe(32)
        session = FlightEsiSession(
            character_id=pilot.character_id,
            character_name=pilot.character_name,
            corporation_id=pilot.corporation_id,
            corporation_name=pilot.corporation_name,
            alliance_id=pilot.alliance_id,
            alliance_name=pilot.alliance_name,
            scopes=pilot.scopes,
            access_token=access_token,
            connected_at=now_iso(),
            expires_at=time.time() + ttl_seconds,
            membership_ok=pilot.membership_ok,
        )
        with self._lock:
            self._sessions[session_id] = session
            self._prune_locked()
        return session_id

    def get(self, session_id: str) -> FlightEsiSession | None:
        if not session_id:
            return None
        with self._lock:
            self._prune_locked()
            session = self._sessions.get(session_id)
        return session

    def delete(self, session_id: str) -> None:
        if not session_id:
            return
        with self._lock:
            self._sessions.pop(session_id, None)

    def _prune_locked(self) -> None:
        expired = [session_id for session_id, session in self._sessions.items() if session.expired]
        for session_id in expired:
            self._sessions.pop(session_id, None)


class UiPerformanceMonitor:
    def __init__(self, *, max_events: int = MAX_UI_PERFORMANCE_EVENTS) -> None:
        self._events: deque[dict[str, Any]] = deque(maxlen=max(1, max_events))
        self._lock = threading.Lock()

    def record(self, payload: Mapping[str, Any], *, client: str = "") -> dict[str, Any]:
        if not isinstance(payload, Mapping):
            raise ValueError("UI performance payload must be a JSON object.")
        event = {
            "received_at": now_iso(),
            "client": self._clean_text(client, max_length=80),
            "kind": self._clean_text(payload.get("kind"), max_length=48) or "unknown",
            "path": self._clean_path(payload.get("path")),
            "hash": self._clean_text(payload.get("hash"), max_length=80),
            "tab": self._clean_text(payload.get("tab"), max_length=48),
            "button_text": self._clean_text(payload.get("button_text"), max_length=80),
            "now_ms": self._clean_number(payload.get("now_ms")),
            "handler_ms": self._clean_number(payload.get("handler_ms")),
            "first_petal_ms": self._clean_number(payload.get("first_petal_ms")),
            "create_ms": self._clean_number(payload.get("create_ms")),
            "petal_count": self._clean_int(payload.get("petal_count")),
            "active_petals": self._clean_int(payload.get("active_petals")),
            "layer_created": bool(payload.get("layer_created")),
            "dom_content_loaded_ms": self._clean_number(payload.get("dom_content_loaded_ms")),
            "load_ms": self._clean_number(payload.get("load_ms")),
            "response_end_ms": self._clean_number(payload.get("response_end_ms")),
            "transfer_size_bytes": self._clean_int(payload.get("transfer_size_bytes")),
            "decoded_body_size_bytes": self._clean_int(payload.get("decoded_body_size_bytes")),
            "html_chars": self._clean_int(payload.get("html_chars")),
        }
        with self._lock:
            self._events.append(event)
        return event

    def snapshot(self) -> dict[str, Any]:
        with self._lock:
            events = list(self._events)
        plex_clicks = [event for event in events if event["kind"] == "plex-click"]
        page_loads = [event for event in events if event["kind"] == "page-load"]
        return {
            "ok": True,
            "generated_at": now_iso(),
            "event_count": len(events),
            "summary": {
                "plex_click_count": len(plex_clicks),
                "last_plex_click": plex_clicks[-1] if plex_clicks else None,
                "max_first_petal_ms": self._max_number(plex_clicks, "first_petal_ms"),
                "max_create_ms": self._max_number(plex_clicks, "create_ms"),
                "max_handler_ms": self._max_number(plex_clicks, "handler_ms"),
                "last_page_load": page_loads[-1] if page_loads else None,
                "max_load_ms": self._max_number(page_loads, "load_ms"),
                "max_html_chars": self._max_number(page_loads, "html_chars"),
            },
            "events": events[-80:],
        }

    @staticmethod
    def _clean_text(value: Any, *, max_length: int) -> str:
        text = str(value or "").replace("\r", " ").replace("\n", " ").strip()
        return text[:max_length]

    @staticmethod
    def _clean_path(value: Any) -> str:
        path = urlparse(str(value or "")).path or "/"
        if not path.startswith("/"):
            path = f"/{path}"
        return path[:120]

    @staticmethod
    def _clean_number(value: Any) -> float | None:
        try:
            number = float(value)
        except (TypeError, ValueError):
            return None
        if number != number or abs(number) == float("inf"):
            return None
        return round(number, 2)

    @classmethod
    def _clean_int(cls, value: Any) -> int | None:
        number = cls._clean_number(value)
        if number is None:
            return None
        return max(0, int(number))

    @staticmethod
    def _max_number(events: Iterable[dict[str, Any]], key: str) -> float | int | None:
        numbers = [event[key] for event in events if isinstance(event.get(key), (int, float))]
        return max(numbers) if numbers else None


@dataclass(frozen=True)
class IndustryMaterial:
    type_id: int
    name: str
    quantity: int
    volume_m3: float | None = None

    @classmethod
    def from_dict(cls, payload: dict[str, Any]) -> "IndustryMaterial | None":
        try:
            type_id = int(payload.get("type_id") or payload.get("typeID") or 0)
            quantity = int(payload.get("quantity") or 0)
        except (TypeError, ValueError):
            return None
        name = str(payload.get("name") or "").strip()
        if type_id <= 0 or quantity <= 0:
            return None
        volume_m3 = clean_optional_float(payload.get("volume_m3") or payload.get("volume"))
        if volume_m3 is not None and volume_m3 <= 0:
            volume_m3 = None
        return cls(type_id=type_id, name=name or f"Type {type_id}", quantity=quantity, volume_m3=volume_m3)

    def to_dict(self) -> dict[str, Any]:
        payload: dict[str, Any] = {"type_id": self.type_id, "name": self.name, "quantity": self.quantity}
        if self.volume_m3 is not None:
            payload["volume_m3"] = self.volume_m3
        return payload


@dataclass(frozen=True)
class IndustrySkill:
    type_id: int
    name: str
    level: int

    @classmethod
    def from_dict(cls, payload: dict[str, Any]) -> "IndustrySkill | None":
        try:
            type_id = int(payload.get("type_id") or payload.get("typeID") or 0)
            level = int(payload.get("level") or 0)
        except (TypeError, ValueError):
            return None
        name = str(payload.get("name") or "").strip()
        if type_id <= 0 or level <= 0:
            return None
        return cls(type_id=type_id, name=name or f"Skill {type_id}", level=level)

    def to_dict(self) -> dict[str, Any]:
        return {"type_id": self.type_id, "name": self.name, "level": self.level}


@dataclass(frozen=True)
class IndustryRecipe:
    blueprint_type_id: int
    blueprint_name: str
    product_type_id: int
    product_name: str
    product_quantity: int
    materials: tuple[IndustryMaterial, ...]
    manufacturing_time_seconds: int = 0
    max_production_limit: int = 0
    skills: tuple[IndustrySkill, ...] = ()

    @classmethod
    def from_dict(cls, payload: dict[str, Any]) -> "IndustryRecipe | None":
        try:
            blueprint_type_id = int(payload.get("blueprint_type_id") or payload.get("blueprintTypeID") or 0)
            product_type_id = int(payload.get("product_type_id") or payload.get("productTypeID") or 0)
            product_quantity = int(payload.get("product_quantity") or payload.get("quantity") or 0)
            manufacturing_time = int(payload.get("manufacturing_time_seconds") or payload.get("time") or 0)
            max_production_limit = int(payload.get("max_production_limit") or payload.get("maxProductionLimit") or 0)
        except (TypeError, ValueError):
            return None
        materials = tuple(
            material
            for item in payload.get("materials", [])
            if isinstance(item, dict)
            for material in [IndustryMaterial.from_dict(item)]
            if material is not None
        )
        skills = tuple(
            skill
            for item in payload.get("skills", [])
            if isinstance(item, dict)
            for skill in [IndustrySkill.from_dict(item)]
            if skill is not None
        )
        if blueprint_type_id <= 0 or product_type_id <= 0 or product_quantity <= 0 or not materials:
            return None
        blueprint_name = str(payload.get("blueprint_name") or "").strip() or f"Blueprint {blueprint_type_id}"
        product_name = str(payload.get("product_name") or "").strip() or f"Type {product_type_id}"
        return cls(
            blueprint_type_id=blueprint_type_id,
            blueprint_name=blueprint_name,
            product_type_id=product_type_id,
            product_name=product_name,
            product_quantity=product_quantity,
            materials=materials,
            manufacturing_time_seconds=max(0, manufacturing_time),
            max_production_limit=max(0, max_production_limit),
            skills=skills,
        )


@dataclass(frozen=True)
class OwnedBlueprint:
    type_id: int
    material_efficiency: int
    time_efficiency: int
    runs: int
    quantity: int

    @property
    def is_original(self) -> bool:
        return self.quantity == -1 or self.runs == -1

    @property
    def is_copy(self) -> bool:
        return self.quantity == -2

    @property
    def usable_for_one_run(self) -> bool:
        return self.is_original or self.runs > 0

    @property
    def kind(self) -> str:
        if self.is_original:
            return "Original"
        if self.is_copy:
            return "Copy"
        return "Blueprint"

    @property
    def limited_runs(self) -> int | None:
        return None if self.is_original else max(0, self.runs)


