def mining_ledger_cache_key(config: EveSsoConfig, session: FlightEsiSession) -> tuple[str, int]:
    return (config.esi_base_url.rstrip("/"), int(session.character_id))


def cached_mining_ledger_rows(rows: Iterable[dict[str, Any]]) -> list[dict[str, Any]]:
    return [dict(row) for row in rows if isinstance(row, dict)]


def fetch_cached_flight_mining_ledger(config: EveSsoConfig, session: FlightEsiSession) -> dict[str, Any]:
    require_flight_scopes(session, (FLIGHT_MINING_SCOPE,))
    cache_key = mining_ledger_cache_key(config, session)
    now = time.monotonic()
    with MINING_LEDGER_CACHE_LOCK:
        cached = MINING_LEDGER_CACHE.get(cache_key)
        if cached is not None:
            cached_at, fetched_at, cached_rows = cached
            age_seconds = now - cached_at
            if age_seconds < MINING_LEDGER_CACHE_TTL_SECONDS:
                expires_in = max(0, int(MINING_LEDGER_CACHE_TTL_SECONDS - age_seconds))
                return {
                    "rows": cached_mining_ledger_rows(cached_rows),
                    "cache_hit": True,
                    "fetched_at": fetched_at,
                    "expires_in_seconds": expires_in,
                }
            MINING_LEDGER_CACHE.pop(cache_key, None)
    rows = fetch_flight_mining_ledger(config, session)
    stored_rows = cached_mining_ledger_rows(rows)
    fetched_at = now_iso()
    with MINING_LEDGER_CACHE_LOCK:
        MINING_LEDGER_CACHE[cache_key] = (time.monotonic(), fetched_at, stored_rows)
    return {
        "rows": cached_mining_ledger_rows(stored_rows),
        "cache_hit": False,
        "fetched_at": fetched_at,
        "expires_in_seconds": int(MINING_LEDGER_CACHE_TTL_SECONDS),
    }


def clear_mining_ledger_cache() -> None:
    with MINING_LEDGER_CACHE_LOCK:
        MINING_LEDGER_CACHE.clear()


def clear_mining_ledger_cache_for_session(config: EveSsoConfig, session: FlightEsiSession | None) -> None:
    if session is None:
        return
    with MINING_LEDGER_CACHE_LOCK:
        MINING_LEDGER_CACHE.pop(mining_ledger_cache_key(config, session), None)


def mining_ledger_cache_status() -> dict[str, Any]:
    now = time.monotonic()
    with MINING_LEDGER_CACHE_LOCK:
        expired_keys = [
            cache_key
            for cache_key, (cached_at, _fetched_at, _rows) in MINING_LEDGER_CACHE.items()
            if now - cached_at >= MINING_LEDGER_CACHE_TTL_SECONDS
        ]
        for cache_key in expired_keys:
            MINING_LEDGER_CACHE.pop(cache_key, None)
        entry_count = len(MINING_LEDGER_CACHE)
    return {
        "ttl_seconds": int(MINING_LEDGER_CACHE_TTL_SECONDS),
        "entries": entry_count,
        "storage": "server-memory-only",
        "note": "Character mining ledger rows are cached in server memory for up to 600 seconds to avoid re-requesting before ESI's cache window.",
    }


def fetch_flight_wallet_transactions(
    config: EveSsoConfig,
    session: FlightEsiSession,
    *,
    max_pages: int = MAX_FLIGHT_TRADE_PNL_PAGES,
    max_transactions: int = MAX_FLIGHT_TRADE_PNL_TRANSACTIONS,
) -> list[dict[str, Any]]:
    require_flight_scopes(session, (FLIGHT_WALLET_SCOPE,))
    base_url = config.esi_base_url.rstrip("/")
    transactions: list[dict[str, Any]] = []
    seen_transaction_ids: set[int] = set()
    from_id: int | None = None
    clean_max_pages = max(1, int(max_pages))
    clean_max_transactions = max(1, int(max_transactions))
    for _page_index in range(clean_max_pages):
        params = {"datasource": "tranquility"}
        if from_id:
            params["from_id"] = str(from_id)
        request = Request(
            add_query_params(f"{base_url}/characters/{session.character_id}/wallet/transactions/", params),
            headers={"Accept": "application/json", **flight_esi_headers(session.access_token)},
            method="GET",
        )
        payload = read_json_http_request(
            request,
            timeout_seconds=45.0,
            label="ESI wallet transactions request",
        ).payload
        if not isinstance(payload, list):
            raise CorpMarketError("ESI wallet transactions returned unexpected data.")
        page_transactions = []
        for item in payload:
            if not isinstance(item, dict):
                continue
            transaction_id = clean_optional_int(item.get("transaction_id"))
            if transaction_id is None or transaction_id <= 0 or transaction_id in seen_transaction_ids:
                continue
            seen_transaction_ids.add(transaction_id)
            page_transactions.append(item)
            transactions.append(item)
            if len(transactions) >= clean_max_transactions:
                return transactions
        if not page_transactions or len(payload) < 2500:
            break
        next_from_id = clean_optional_int(page_transactions[-1].get("transaction_id"))
        if next_from_id is None or next_from_id <= 0 or next_from_id == from_id:
            break
        from_id = next_from_id
    return transactions


def fetch_flight_wallet_journal(
    config: EveSsoConfig,
    session: FlightEsiSession,
    *,
    max_pages: int = MAX_FLIGHT_TRADE_JOURNAL_PAGES,
) -> list[dict[str, Any]]:
    require_flight_scopes(session, (FLIGHT_WALLET_SCOPE,))
    base_url = config.esi_base_url.rstrip("/")
    entries: list[dict[str, Any]] = []
    page = 1
    page_count = 1
    clean_max_pages = max(1, int(max_pages))
    while page <= page_count and page <= clean_max_pages:
        request = Request(
            add_query_params(
                f"{base_url}/characters/{session.character_id}/wallet/journal/",
                {"datasource": "tranquility", "page": str(page)},
            ),
            headers={"Accept": "application/json", **flight_esi_headers(session.access_token)},
            method="GET",
        )
        result = read_json_http_request(
            request,
            timeout_seconds=45.0,
            label="ESI wallet journal request",
        )
        payload = result.payload
        page_count = max(1, int(result.header("X-Pages") or "1"))
        if not isinstance(payload, list):
            raise CorpMarketError("ESI wallet journal returned unexpected data.")
        entries.extend(item for item in payload if isinstance(item, dict))
        page += 1
    return entries


def build_flight_trade_pnl_payload(
    *,
    config: EveSsoConfig,
    session: FlightEsiSession,
    days: int = DEFAULT_FLIGHT_TRADE_PNL_DAYS,
    window_hours: Any = None,
    accounting_lens: str = "inventory",
    consideration_rule: Any = None,
    excluded_tokens: Iterable[str] = (),
    include_matches: bool = False,
    expectation_store: MarketStore | None = None,
    acquisition_expectations: Iterable[dict[str, Any]] = (),
    trade_ledger_store: MarketStore | None = None,
) -> dict[str, Any]:
    require_flight_scopes(session, (FLIGHT_WALLET_SCOPE,))
    clean_window_hours = clamp_trade_pnl_window_hours(
        window_hours if window_hours is not None and str(window_hours).strip() else clamp_trade_pnl_days(days) * 24
    )
    transactions = fetch_flight_wallet_transactions(config, session)
    journal_entries = fetch_flight_wallet_journal(config, session)
    clean_lens = normalize_trade_pnl_lens(accounting_lens)
    clean_consideration_rule = normalize_trade_pnl_consideration_rule(
        consideration_rule,
        excluded_tokens=excluded_tokens,
    )
    type_ids = {
        type_id
        for transaction in transactions
        for type_id in [clean_optional_int(transaction.get("type_id"))]
        if type_id is not None and type_id > 0
    }
    type_names = resolve_trade_type_names(config, type_ids)
    current_time = datetime.now(timezone.utc)
    ledger_store = trade_ledger_store or expectation_store
    historical_transactions: list[dict[str, Any]] = []
    ledger_status = {"saved": 0, "historical_transaction_count": 0}
    if ledger_store is not None:
        saved = ledger_store.save_trade_ledger_transactions(character_id=session.character_id, transactions=transactions)
        cutoff = current_time - timedelta(hours=clean_window_hours)
        historical_transactions = ledger_store.historical_trade_ledger_transactions(
            character_id=session.character_id,
            type_ids=type_ids,
            before=cutoff,
        )
        ledger_status = {
            "saved": int(saved.get("saved") or 0),
            "historical_transaction_count": len(historical_transactions),
            "source": "local-corp-market-sqlite",
        }
    provisional_pnl = analyze_trade_pnl_transactions(
        transactions,
        journal_entries=journal_entries,
        type_names=type_names,
        window_hours=clean_window_hours,
        accounting_lens=clean_lens,
        consideration_rule=clean_consideration_rule,
        excluded_tokens=excluded_tokens,
        include_matches=False,
        item_limit=MAX_FLIGHT_TRADE_PNL_TRANSACTIONS,
        now=current_time,
    )
    open_type_ids = [
        int(item["type_id"])
        for item in provisional_pnl.get("items") or []
        if int(item.get("open_quantity") or 0) > 0
    ]
    market_values: dict[int, dict[str, Any]] = {}
    market_valuation_error = ""
    market_valuation_requested = clean_lens == "inventory" and bool(open_type_ids)
    if market_valuation_requested:
        try:
            market_values = fetch_fuzzwork_market_aggregates(open_type_ids)
        except CorpMarketError as exc:
            market_valuation_error = str(exc)
    saved_expectations = list(acquisition_expectations or [])
    if expectation_store is not None:
        saved_expectations.extend(
            expectation_store.latest_acquisition_expectations(
                character_id=session.character_id,
                type_ids=type_ids,
                cutoff=current_time - timedelta(hours=clean_window_hours),
            )
        )
    trade_pnl = analyze_trade_pnl_transactions(
        transactions,
        journal_entries=journal_entries,
        type_names=type_names,
        market_values=market_values,
        market_valuation_requested=market_valuation_requested,
        market_valuation_source="Fuzzwork",
        market_valuation_location="Jita 4-4",
        market_valuation_error=market_valuation_error,
        window_hours=clean_window_hours,
        accounting_lens=clean_lens,
        consideration_rule=clean_consideration_rule,
        excluded_tokens=excluded_tokens,
        include_matches=include_matches,
        acquisition_expectations=saved_expectations,
        historical_transactions=historical_transactions,
        now=current_time,
    )
    generated_at = now_iso()
    learning_store = trade_ledger_store or expectation_store
    learning_signals: list[dict[str, Any]] = []
    learning_saved = 0
    if learning_store is not None:
        learning_evidence = build_trade_learning_signal_evidence(
            trade_pnl,
            updated_at=generated_at,
            now=current_time,
        )
        if learning_evidence:
            saved_learning = learning_store.save_trade_learning_signals(
                character_id=session.character_id,
                signals=learning_evidence,
            )
            learning_saved = int(saved_learning.get("saved") or 0)
            learning_signals = [signal for signal in saved_learning.get("signals") or [] if isinstance(signal, dict)]
        if not learning_signals:
            learning_signals = learning_store.latest_trade_learning_signals(
                character_id=session.character_id,
                type_ids=type_ids,
            )
        attach_trade_learning_signals(
            trade_pnl.get("items") or [],
            trade_learning_signals_by_type(learning_signals),
            include_empty=True,
        )
    trade_pnl["learning"] = trade_learning_summary(learning_signals, saved=learning_saved)
    fuzzwork_cache = fuzzwork_market_aggregate_cache_status()
    trade_pnl["market_valuation"]["cache"] = fuzzwork_cache
    trade_pnl["trade_ledger"] = ledger_status
    data_sources = [
        workflow_source_badge(
            key="wallet-esi",
            label="Wallet ESI",
            status="ready",
            posture="read-only ESI",
            freshness=generated_at,
            persistence="response summary; optional local ledger rows",
            scope=FLIGHT_WALLET_SCOPE,
            detail="Recent wallet transactions and market fee journal rows are read for P&L matching.",
        ),
        workflow_source_badge(
            key="trade-pnl-analyzer",
            label="Local P&L analyzer",
            status="ready",
            posture="local calculation",
            freshness="current request",
            persistence="not stored",
            detail="FIFO matching, fee allocation, open-stock accounting, and plan reconciliation run locally.",
        ),
        sqlite_source_badge(
            enabled=bool(ledger_store or expectation_store),
            detail="Stores acquisition expectations, wallet ledger rows, and repeated accuracy signals only when the local market store is available.",
        ),
    ]
    if market_valuation_requested:
        data_sources.append(
            market_cache_source_badge(
                key="fuzzwork-market-aggregates",
                label="Fuzzwork market aggregates",
                cache_status=fuzzwork_cache,
                detail="Open inventory value uses Fuzzwork aggregate prices for Jita 4-4 when inventory mode has open stock.",
            )
        )
    trade_pnl["data_sources"] = data_sources
    trade_pnl["discord_handoff"] = trade_pnl_discord_handoff(trade_pnl)
    return {
        "ok": True,
        "generated_at": generated_at,
        "character": session.to_public_dict(),
        "data_sources": data_sources,
        "trade_pnl": trade_pnl,
    }


def parse_esi_ledger_date(value: Any) -> date | None:
    try:
        return datetime.strptime(str(value or "").strip(), "%Y-%m-%d").date()
    except (TypeError, ValueError):
        return None


def resolve_mining_type_metadata(config: EveSsoConfig, type_ids: Iterable[int]) -> tuple[dict[int, dict[str, Any]], bool]:
    wanted = {int(type_id) for type_id in type_ids if int(type_id) > 0}
    if not wanted:
        return {}, bool(load_static_market_data())
    metadata: dict[int, dict[str, Any]] = {}
    static_data = load_static_market_data()
    if static_data is not None:
        for type_infos in static_data.types_by_group.values():
            for type_info in type_infos:
                type_id = clean_optional_int(type_info.get("type_id"))
                if type_id not in wanted or type_id in metadata:
                    continue
                metadata[type_id] = {
                    "type_id": type_id,
                    "name": str(type_info.get("name") or f"Type {type_id}"),
                    "volume_m3": clean_optional_float(type_info.get("volume_m3")),
                    "market_group_id": clean_optional_int(type_info.get("market_group_id")),
                    "market_group_name": str(type_info.get("market_group_name") or ""),
                    "source": "local-static-market-data",
                }
                if len(metadata) >= len(wanted):
                    return metadata, True
    missing_type_ids = sorted(wanted - set(metadata))
    try:
        names = fetch_universe_names(config, missing_type_ids)
    except (CorpIntelError, CorpMarketError, ValueError):
        names = {}
    for type_id in missing_type_ids:
        metadata[type_id] = {
            "type_id": type_id,
            "name": names.get(type_id) or f"Type {type_id}",
            "volume_m3": None,
            "market_group_id": None,
            "market_group_name": "",
            "source": "public-esi-names" if type_id in names else "type-id-only",
        }
    return metadata, static_data is not None


def build_flight_mining_yield_payload(
    *,
    config: EveSsoConfig,
    session: FlightEsiSession,
    days: Any = DEFAULT_FLIGHT_MINING_WINDOW_DAYS,
    session_hours: Any = DEFAULT_FLIGHT_MINING_SESSION_HOURS,
) -> dict[str, Any]:
    require_flight_scopes(session, (FLIGHT_MINING_SCOPE,))
    clean_days = clamp_mining_window_days(days)
    clean_session_hours = clamp_mining_session_hours(session_hours)
    ledger_cache = fetch_cached_flight_mining_ledger(config, session)
    ledger_rows = [row for row in ledger_cache.get("rows", []) if isinstance(row, dict)]
    today = datetime.now(timezone.utc).date()
    start_date = today - timedelta(days=clean_days - 1)
    filtered_rows: list[dict[str, Any]] = []
    for row in ledger_rows:
        if not isinstance(row, dict):
            continue
        ledger_date = parse_esi_ledger_date(row.get("date"))
        if ledger_date is None or ledger_date < start_date or ledger_date > today:
            continue
        type_id = clean_optional_int(row.get("type_id"))
        quantity = clean_optional_int(row.get("quantity")) or 0
        if type_id is None or type_id <= 0 or quantity <= 0:
            continue
        filtered_rows.append(
            {
                "date": ledger_date,
                "type_id": type_id,
                "quantity": quantity,
                "solar_system_id": clean_optional_int(row.get("solar_system_id")),
            }
        )
    type_ids = {int(row["type_id"]) for row in filtered_rows}
    type_metadata, static_cache_available = resolve_mining_type_metadata(config, type_ids)
    by_type: dict[int, dict[str, Any]] = {}
    by_date: dict[str, dict[str, Any]] = {}
    by_date_type: dict[tuple[str, int], dict[str, Any]] = {}
    total_quantity = 0
    total_volume_m3 = 0.0
    known_volume_quantity = 0
    system_ids: set[int] = set()
    active_dates: set[str] = set()
    for row in filtered_rows:
        type_id = int(row["type_id"])
        quantity = int(row["quantity"])
        date_key = row["date"].isoformat()
        metadata = type_metadata.get(type_id, {})
        unit_volume = clean_optional_float(metadata.get("volume_m3"))
        row_volume = (unit_volume * quantity) if unit_volume is not None and unit_volume > 0 else None
        total_quantity += quantity
        active_dates.add(date_key)
        if row_volume is not None:
            total_volume_m3 += row_volume
            known_volume_quantity += quantity
        system_id = clean_optional_int(row.get("solar_system_id"))
        if system_id:
            system_ids.add(system_id)
        item = by_type.setdefault(
            type_id,
            {
                "type_id": type_id,
                "type_name": metadata.get("name") or f"Type {type_id}",
                "quantity": 0,
                "unit_volume_m3": unit_volume,
                "total_volume_m3": 0.0,
                "volume_known": unit_volume is not None and unit_volume > 0,
                "dates": set(),
                "solar_system_ids": set(),
                "metadata_source": metadata.get("source") or "unknown",
                "market_group_name": metadata.get("market_group_name") or "",
            },
        )
        item["quantity"] = int(item["quantity"]) + quantity
        item["dates"].add(date_key)
        if system_id:
            item["solar_system_ids"].add(system_id)
        if row_volume is not None:
            item["total_volume_m3"] = float(item["total_volume_m3"]) + row_volume
        day = by_date.setdefault(date_key, {"date": date_key, "quantity": 0, "volume_m3": 0.0, "volume_partial": False})
        day["quantity"] = int(day["quantity"]) + quantity
        if row_volume is not None:
            day["volume_m3"] = float(day["volume_m3"]) + row_volume
        else:
            day["volume_partial"] = True
        date_type = by_date_type.setdefault(
            (date_key, type_id),
            {
                "date": date_key,
                "type_id": type_id,
                "type_name": metadata.get("name") or f"Type {type_id}",
                "quantity": 0,
                "volume_m3": 0.0,
                "volume_known": unit_volume is not None and unit_volume > 0,
            },
        )
        date_type["quantity"] = int(date_type["quantity"]) + quantity
        if row_volume is not None:
            date_type["volume_m3"] = float(date_type["volume_m3"]) + row_volume
        else:
            date_type["volume_known"] = False
    session_seconds = clean_session_hours * 3600.0
    items: list[dict[str, Any]] = []
    for item in by_type.values():
        date_values = sorted(str(value) for value in item.pop("dates"))
        item_system_ids = sorted(int(value) for value in item.pop("solar_system_ids"))
        volume_known = bool(item["volume_known"])
        raw_item_volume = float(item["total_volume_m3"]) if volume_known else None
        total_item_volume = round(raw_item_volume, 2) if raw_item_volume is not None else None
        items.append(
            {
                **item,
                "total_volume_m3": total_item_volume,
                "active_day_count": len(date_values),
                "first_date": date_values[0] if date_values else "",
                "last_date": date_values[-1] if date_values else "",
                "solar_system_count": len(item_system_ids),
                "quantity_per_day": round(int(item["quantity"]) / clean_days, 2),
                "quantity_per_second": int(item["quantity"]) / session_seconds if session_seconds > 0 else None,
                "volume_m3_per_day": round(float(total_item_volume) / clean_days, 2) if total_item_volume is not None else None,
                "volume_m3_per_second": raw_item_volume / session_seconds if raw_item_volume is not None and session_seconds > 0 else None,
            }
        )
    items.sort(key=lambda item: (-int(item["quantity"]), str(item["type_name"]).casefold(), int(item["type_id"])))
    truncated_item_count = max(0, len(items) - MAX_FLIGHT_MINING_ROWS)
    visible_items = items[:MAX_FLIGHT_MINING_ROWS]
    daily = []
    for date_key in sorted(by_date, reverse=True):
        row = by_date[date_key]
        volume = round(float(row["volume_m3"]), 2) if float(row["volume_m3"]) > 0 else None
        daily.append(
            {
                "date": date_key,
                "quantity": int(row["quantity"]),
                "volume_m3": volume,
                "volume_partial": bool(row["volume_partial"]),
            }
        )
    csv_rows = []
    for row in sorted(by_date_type.values(), key=lambda value: (str(value["date"]), str(value["type_name"]).casefold()), reverse=True):
        quantity = int(row["quantity"])
        raw_volume = float(row["volume_m3"]) if bool(row["volume_known"]) else None
        volume = round(raw_volume, 2) if raw_volume is not None else None
        csv_rows.append(
            {
                "date": row["date"],
                "type_id": row["type_id"],
                "type_name": row["type_name"],
                "quantity": quantity,
                "volume_m3": volume,
                "quantity_per_day": round(quantity / clean_days, 2),
                "quantity_per_second": quantity / session_seconds if session_seconds > 0 else None,
                "volume_m3_per_day": round(float(volume) / clean_days, 2) if volume is not None else None,
                "volume_m3_per_second": raw_volume / session_seconds if raw_volume is not None and session_seconds > 0 else None,
            }
        )
    volume_unknown_quantity = max(0, total_quantity - known_volume_quantity)
    generated_at = now_iso()
    data_sources = [
        workflow_source_badge(
            key="mining-ledger-esi",
            label="Mining ledger ESI",
            status="ready",
            posture="read-only ESI",
            freshness=str(ledger_cache.get("fetched_at") or generated_at),
            persistence="server-memory cache",
            scope=FLIGHT_MINING_SCOPE,
            detail="Daily character mining ledger rows are cached and never read from the EVE client.",
        ),
        workflow_source_badge(
            key="mining-ledger-cache",
            label="Mining ledger cache",
            status="ready" if ledger_cache.get("cache_hit") else "ready",
            posture="server-memory cache",
            freshness=f"{int(ledger_cache.get('expires_in_seconds') or 0)}s until refresh" if ledger_cache.get("cache_hit") else "fresh ESI read",
            persistence="server-memory only",
            detail="Ledger rows are reused during the ESI cache window and cleared when the pilot logs out.",
        ),
        workflow_source_badge(
            key="static-type-cache",
            label="Static type metadata",
            status="ready" if static_cache_available else "error",
            posture="local static cache",
            freshness="current host cache" if static_cache_available else "missing",
            persistence="local ignored cache file",
            detail="Local static market data supplies ore names, market groups, and volume where available.",
        ),
        workflow_source_badge(
            key="manual-session-hours",
            label="Manual session hours",
            status="manual",
            posture="browser input",
            freshness="current form value",
            persistence="browser localStorage only",
            detail="The session average uses the manually entered timer/hours value; it is not live mining telemetry.",
        ),
    ]
    return {
        "ok": True,
        "generated_at": generated_at,
        "character": session.to_public_dict(),
        "data_sources": data_sources,
        "mining_yield": {
            "data_sources": data_sources,
            "source": FLIGHT_MINING_SCOPE,
            "source_label": "ESI character mining ledger",
            "cache_seconds": int(MINING_LEDGER_CACHE_TTL_SECONDS),
            "cache_note": "ESI character mining ledger is cached for up to 600 seconds and reports daily ledger rows, not live mining-cycle telemetry.",
            "cache": {
                "ttl_seconds": int(MINING_LEDGER_CACHE_TTL_SECONDS),
                "reused": bool(ledger_cache.get("cache_hit")),
                "fetched_at": str(ledger_cache.get("fetched_at") or ""),
                "expires_in_seconds": clean_optional_int(ledger_cache.get("expires_in_seconds")) or 0,
                "storage": "server-memory-only",
                "note": "Ledger rows are held only in server memory during the cache window and are cleared when the pilot logs out.",
            },
            "window_days": clean_days,
            "session_hours": clean_session_hours,
            "start_date": start_date.isoformat(),
            "end_date": today.isoformat(),
            "ledger_row_count": len(filtered_rows),
            "raw_ledger_row_count": len([row for row in ledger_rows if isinstance(row, dict)]),
            "active_day_count": len(active_dates),
            "solar_system_count": len(system_ids),
            "static_type_cache_available": static_cache_available,
            "items_truncated": truncated_item_count > 0,
            "item_limit": MAX_FLIGHT_MINING_ROWS,
            "item_count": len(items),
            "totals": {
                "quantity": total_quantity,
                "volume_m3": round(total_volume_m3, 2) if total_volume_m3 > 0 else None,
                "volume_partial": volume_unknown_quantity > 0,
                "known_volume_quantity": known_volume_quantity,
                "unknown_volume_quantity": volume_unknown_quantity,
                "quantity_per_day": round(total_quantity / clean_days, 2),
                "volume_m3_per_day": round(total_volume_m3 / clean_days, 2) if total_volume_m3 > 0 else None,
                "quantity_per_second": total_quantity / session_seconds if session_seconds > 0 else None,
                "volume_m3_per_second": total_volume_m3 / session_seconds if total_volume_m3 > 0 and session_seconds > 0 else None,
            },
            "items": visible_items,
            "daily": daily,
            "csv_rows": csv_rows,
            "csv_columns": [
                "Date",
                "Ore Type",
                "Type ID",
                "Units",
                "m3",
                "Ore / Day",
                "Session Units / Sec",
                "Session m3 / Sec",
            ],
            "notes": [
                "Ore/day uses the selected calendar window, including days with no ledger rows.",
                "Session average divides the selected-window ledger total by the manual session-hours field.",
                "m3 values are partial when local static type volume is unavailable for any mined type.",
            ],
        },
    }


def resolve_trade_type_names(config: EveSsoConfig, type_ids: Iterable[int]) -> dict[int, str]:
    clean_type_ids = sorted({int(type_id) for type_id in type_ids if int(type_id) > 0})
    if not clean_type_ids:
        return {}
    try:
        return fetch_universe_names(config, clean_type_ids)
    except CorpMarketError:
        return {}


def analyze_trade_pnl_transactions(
    transactions: Iterable[dict[str, Any]],
    *,
    journal_entries: Iterable[dict[str, Any]] = (),
    type_names: dict[int, str] | None = None,
    market_values: dict[int, dict[str, Any]] | None = None,
    market_valuation_requested: bool = False,
    market_valuation_source: str = "",
    market_valuation_location: str = "",
    market_valuation_error: str = "",
    acquisition_expectations: Iterable[dict[str, Any]] = (),
    historical_transactions: Iterable[dict[str, Any]] = (),
    days: int = DEFAULT_FLIGHT_TRADE_PNL_DAYS,
    window_hours: Any = None,
    accounting_lens: str = "inventory",
    consideration_rule: Any = None,
    excluded_tokens: Iterable[str] = (),
    include_matches: bool = False,
    now: datetime | None = None,
    item_limit: int = MAX_FLIGHT_TRADE_PNL_ITEMS,
) -> dict[str, Any]:
    clean_window_hours = clamp_trade_pnl_window_hours(
        window_hours if window_hours is not None and str(window_hours).strip() else clamp_trade_pnl_days(days) * 24
    )
    clean_lens = normalize_trade_pnl_lens(accounting_lens)
    clean_excluded_tokens = clean_trade_pnl_excluded_tokens(excluded_tokens)
    clean_consideration_rule = normalize_trade_pnl_consideration_rule(
        consideration_rule,
        excluded_tokens=clean_excluded_tokens,
    )
    material_type_ids = (
        trade_pnl_material_type_ids()
        if clean_consideration_rule in {"materials", "materials_custom"}
        else frozenset()
    )
    clean_market_values = normalize_trade_pnl_market_values(market_values or {})
    clean_expectations = normalize_trade_pnl_acquisition_expectations(acquisition_expectations)
    valuation_requested = bool(market_valuation_requested or clean_market_values)
    current_time = now or datetime.now(timezone.utc)
    cutoff = current_time - timedelta(hours=clean_window_hours)
    visible_transactions = [
        transaction
        for transaction in transactions
        if trade_record_datetime(transaction.get("date")) is not None
        and trade_record_datetime(transaction.get("date")) >= cutoff
    ]
    visible_journal_entries = [
        entry
        for entry in journal_entries
        if trade_record_datetime(entry.get("date")) is not None and trade_record_datetime(entry.get("date")) >= cutoff
    ]
    fee_by_transaction_id: dict[int, float] = {}
    market_fee_total = 0.0
    market_transaction_journal_total = 0.0
    fee_ref_counts: dict[str, int] = {}
    for entry in visible_journal_entries:
        ref_type = str(entry.get("ref_type") or "").strip()
        amount = clean_optional_float(entry.get("amount"))
        if amount is None:
            continue
        if ref_type == "market_transaction":
            market_transaction_journal_total += amount
        if ref_type not in TRADE_PNL_MARKET_FEE_REF_TYPES:
            continue
        market_fee_total += amount
        fee_ref_counts[ref_type] = fee_ref_counts.get(ref_type, 0) + 1
        context_id = clean_optional_int(entry.get("context_id"))
        context_type = str(entry.get("context_id_type") or "").strip()
        if context_id is not None and context_type == "market_transaction_id":
            fee_by_transaction_id[context_id] = fee_by_transaction_id.get(context_id, 0.0) + amount

    names = type_names or {}
    summaries: dict[int, dict[str, Any]] = {}
    open_lots: dict[int, list[dict[str, Any]]] = {}
    ignored_transactions = 0
    historical_transaction_count = 0
    historical_open_lot_count = 0
    historical_ignored_transactions = 0
    for transaction in sorted(
        historical_transactions or (),
        key=lambda item: (
            trade_record_datetime(item.get("date")) or datetime.min.replace(tzinfo=timezone.utc),
            clean_optional_int(item.get("transaction_id")) or 0,
        ),
    ):
        transaction_date = trade_record_datetime(transaction.get("date"))
        if transaction_date is None or transaction_date >= cutoff:
            continue
        type_id = clean_optional_int(transaction.get("type_id"))
        transaction_id = clean_optional_int(transaction.get("transaction_id"))
        quantity = clean_optional_int(transaction.get("quantity"))
        unit_price = clean_optional_float(transaction.get("unit_price"))
        if type_id is None or transaction_id is None or quantity is None or quantity <= 0 or unit_price is None or unit_price < 0:
            historical_ignored_transactions += 1
            continue
        historical_transaction_count += 1
        lots = open_lots.setdefault(type_id, [])
        if bool(transaction.get("is_buy")):
            lots.append(
                {
                    "quantity_remaining": quantity,
                    "unit_cost": float(unit_price),
                    "transaction_id": transaction_id,
                    "date": str(transaction.get("date") or ""),
                    "historical": True,
                }
            )
            continue
        remaining_historical_sell = quantity
        while remaining_historical_sell > 0 and lots:
            lot = lots[0]
            lot_quantity = int(lot.get("quantity_remaining") or 0)
            if lot_quantity <= 0:
                lots.pop(0)
                continue
            matched_quantity = min(remaining_historical_sell, lot_quantity)
            lot["quantity_remaining"] = lot_quantity - matched_quantity
            remaining_historical_sell -= matched_quantity
            if int(lot.get("quantity_remaining") or 0) <= 0:
                lots.pop(0)
    historical_open_lot_count = sum(
        1
        for lots in open_lots.values()
        for lot in lots
        if bool(lot.get("historical")) and int(lot.get("quantity_remaining") or 0) > 0
    )
    for transaction in sorted(
        visible_transactions,
        key=lambda item: (
            trade_record_datetime(item.get("date")) or datetime.min.replace(tzinfo=timezone.utc),
            clean_optional_int(item.get("transaction_id")) or 0,
        ),
    ):
        type_id = clean_optional_int(transaction.get("type_id"))
        transaction_id = clean_optional_int(transaction.get("transaction_id"))
        quantity = clean_optional_int(transaction.get("quantity"))
        unit_price = clean_optional_float(transaction.get("unit_price"))
        if type_id is None or transaction_id is None or quantity is None or quantity <= 0 or unit_price is None or unit_price < 0:
            ignored_transactions += 1
            continue
        summary = trade_pnl_summary_for_type(summaries, type_id=type_id, type_name=names.get(type_id) or f"Type {type_id}")
        transaction_date = str(transaction.get("date") or "")
        summary["transaction_count"] += 1
        summary["first_date"] = min_trade_date(summary.get("first_date"), transaction_date)
        summary["last_date"] = max_trade_date(summary.get("last_date"), transaction_date)
        transaction_total = float(quantity) * float(unit_price)
        transaction_fee = fee_by_transaction_id.get(transaction_id, 0.0)
        summary["allocated_fee_isk"] += transaction_fee
        if bool(transaction.get("is_buy")):
            summary["buy_quantity"] += quantity
            summary["buy_total_isk"] += transaction_total
            open_lots.setdefault(type_id, []).append(
                {
                    "quantity_remaining": quantity,
                    "unit_cost": float(unit_price),
                    "transaction_id": transaction_id,
                    "date": transaction_date,
                }
            )
            continue
        summary["sell_quantity"] += quantity
        summary["sell_total_isk"] += transaction_total
        remaining_to_match = quantity
        lots = open_lots.setdefault(type_id, [])
        while remaining_to_match > 0 and lots:
            lot = lots[0]
            lot_quantity = int(lot.get("quantity_remaining") or 0)
            if lot_quantity <= 0:
                lots.pop(0)
                continue
            matched_quantity = min(remaining_to_match, lot_quantity)
            buy_cost = float(lot.get("unit_cost") or 0.0) * matched_quantity
            sell_revenue = float(unit_price) * matched_quantity
            match_fee = transaction_fee * (matched_quantity / quantity) if quantity > 0 else 0.0
            summary["matched_quantity"] += matched_quantity
            summary["matched_buy_cost_isk"] += buy_cost
            summary["matched_sell_revenue_isk"] += sell_revenue
            if include_matches:
                summary["matches"].append(
                    {
                        "buy_transaction_id": lot.get("transaction_id"),
                        "buy_date": lot.get("date") or "",
                        "buy_source": "local-ledger" if bool(lot.get("historical")) else "wallet-window",
                        "sell_transaction_id": transaction_id,
                        "sell_date": transaction_date,
                        "quantity": matched_quantity,
                        "buy_unit_price": float(lot.get("unit_cost") or 0.0),
                        "sell_unit_price": float(unit_price),
                        "buy_cost_isk": buy_cost,
                        "sell_revenue_isk": sell_revenue,
                        "fee_isk": match_fee,
                        "expected_profit_isk": sell_revenue - buy_cost,
                        "actual_profit_isk": sell_revenue - buy_cost + match_fee,
                    }
                )
            lot["quantity_remaining"] = lot_quantity - matched_quantity
            if bool(lot.get("historical")):
                summary["historical_matched_quantity"] += matched_quantity
                summary["historical_matched_buy_cost_isk"] += buy_cost
            remaining_to_match -= matched_quantity
            if int(lot.get("quantity_remaining") or 0) <= 0:
                lots.pop(0)
        if remaining_to_match > 0:
            summary["unmatched_sell_quantity"] += remaining_to_match
            summary["unmatched_sell_revenue_isk"] += float(unit_price) * remaining_to_match

    for type_id, lots in open_lots.items():
        summary = summaries.get(type_id)
        if summary is None:
            continue
        for lot in lots:
            quantity_remaining = int(lot.get("quantity_remaining") or 0)
            if quantity_remaining <= 0:
                continue
            summary["open_quantity"] += quantity_remaining
            summary["open_inventory_cost_isk"] += quantity_remaining * float(lot.get("unit_cost") or 0.0)

    items = []
    totals = trade_pnl_empty_totals()
    for summary in summaries.values():
        excluded, excluded_reason = trade_pnl_item_excluded(
            summary,
            consideration_rule=clean_consideration_rule,
            excluded_tokens=clean_excluded_tokens,
            material_type_ids=material_type_ids,
        )
        summary["excluded"] = excluded
        summary["excluded_reason"] = excluded_reason
        summary["consideration_rule"] = clean_consideration_rule
        expected_profit = summary["matched_sell_revenue_isk"] - summary["matched_buy_cost_isk"]
        actual_profit = expected_profit + summary["allocated_fee_isk"]
        summary["expected_profit_isk"] = round(expected_profit, 2)
        summary["actual_profit_isk"] = round(actual_profit, 2)
        summary["fee_gap_isk"] = round(summary["allocated_fee_isk"], 2)
        summary["net_cashflow_isk"] = round(
            summary["sell_total_isk"] - summary["buy_total_isk"] + summary["allocated_fee_isk"],
            2,
        )
        trade_pnl_apply_market_valuation(
            summary,
            market_values=clean_market_values,
            actual_profit=actual_profit,
        )
        trade_pnl_apply_acquisition_expectation(summary, clean_expectations.get(int(summary["type_id"])))
        summary["margin_percent"] = profit_margin_percent(actual_profit, summary["matched_buy_cost_isk"])
        summary["status"] = trade_pnl_item_status(summary)
        summary["source_badges"] = trade_pnl_source_badges(summary)
        for key in totals:
            value = summary.get(key)
            if value is None:
                continue
            totals[key] += float(value or 0.0)
        items.append(summary)

    allocated_fee_total = sum(float(item.get("allocated_fee_isk") or 0.0) for item in items)
    unallocated_fee_total = market_fee_total - allocated_fee_total
    visible_actual_profit = totals["expected_profit_isk"] + allocated_fee_total
    wallet_fee_adjusted_profit = totals["expected_profit_isk"] + market_fee_total
    market_valued_open_item_count = sum(
        1 for item in items if int(item.get("open_quantity") or 0) > 0 and item.get("market_valuation_status") == "priced"
    )
    market_unvalued_open_item_count = sum(
        1 for item in items if int(item.get("open_quantity") or 0) > 0 and item.get("market_valuation_status") == "missing"
    )
    market_valuation_status = trade_pnl_market_valuation_status(
        valuation_requested=valuation_requested,
        market_valued_open_item_count=market_valued_open_item_count,
        market_unvalued_open_item_count=market_unvalued_open_item_count,
        market_valuation_error=market_valuation_error,
    )
    open_inventory_market_value_total = round_optional_float(totals["open_inventory_market_value_isk"])
    open_inventory_unrealized_total = round_optional_float(totals["open_inventory_unrealized_isk"])
    if market_valued_open_item_count <= 0 and market_unvalued_open_item_count > 0:
        open_inventory_market_value_total = None
        open_inventory_unrealized_total = None
    plan_reconciliations = [
        item.get("plan_reconciliation")
        for item in items
        if isinstance(item.get("plan_reconciliation"), dict) and item["plan_reconciliation"].get("available")
    ]
    plan_matched_reconciliations = [
        plan
        for plan in plan_reconciliations
        if clean_optional_float(plan.get("expected_profit_for_matched_isk")) is not None
        and clean_optional_float(plan.get("actual_vs_expected_profit_isk")) is not None
    ]
    expected_plan_profit_total = (
        sum(float(plan.get("expected_profit_for_matched_isk") or 0.0) for plan in plan_matched_reconciliations)
        if plan_matched_reconciliations
        else None
    )
    actual_vs_plan_profit_total = (
        sum(float(plan.get("actual_vs_expected_profit_isk") or 0.0) for plan in plan_matched_reconciliations)
        if plan_matched_reconciliations
        else None
    )
    considered = trade_pnl_considered_totals(items, lens=clean_lens, unallocated_fee_total=unallocated_fee_total)
    items.sort(key=lambda item: (-abs(float(item.get("actual_profit_isk") or item.get("expected_profit_isk") or 0.0)), str(item["item_name"])))
    limited_items = items[: max(1, int(item_limit))]
    return {
        "days": max(1, int(round(clean_window_hours / 24.0))),
        "window_hours": clean_window_hours,
        "window_label": trade_pnl_window_label(clean_window_hours),
        "accounting_lens": clean_lens,
        "accounting_lens_label": trade_pnl_lens_label(clean_lens),
        "consideration_rule": clean_consideration_rule,
        "consideration_rule_label": trade_pnl_consideration_rule_label(clean_consideration_rule),
        "excluded_tokens": list(clean_excluded_tokens),
        "custom_excluded_tokens": list(clean_excluded_tokens),
        "cutoff": cutoff.isoformat().replace("+00:00", "Z"),
        "transaction_count": len(visible_transactions),
        "ignored_transaction_count": ignored_transactions,
        "journal_entry_count": len(visible_journal_entries),
        "item_count": len(items),
        "item_limit": max(1, int(item_limit)),
        "items_truncated": len(items) > max(1, int(item_limit)),
        "items": [trade_pnl_public_item(item) for item in limited_items],
        "totals": {
            "buy_total_isk": round(totals["buy_total_isk"], 2),
            "sell_total_isk": round(totals["sell_total_isk"], 2),
            "matched_quantity": int(totals["matched_quantity"]),
            "historical_matched_quantity": int(totals["historical_matched_quantity"]),
            "matched_buy_cost_isk": round(totals["matched_buy_cost_isk"], 2),
            "historical_matched_buy_cost_isk": round(totals["historical_matched_buy_cost_isk"], 2),
            "matched_sell_revenue_isk": round(totals["matched_sell_revenue_isk"], 2),
            "expected_profit_isk": round(totals["expected_profit_isk"], 2),
            "allocated_fee_isk": round(allocated_fee_total, 2),
            "unallocated_fee_isk": round(unallocated_fee_total, 2),
            "market_fee_isk": round(market_fee_total, 2),
            "actual_profit_isk": round(visible_actual_profit, 2),
            "wallet_fee_adjusted_profit_isk": round(wallet_fee_adjusted_profit, 2),
            "inventory_result_isk": round(totals["inventory_result_isk"], 2),
            "net_cashflow_isk": round(totals["net_cashflow_isk"] + unallocated_fee_total, 2),
            "open_inventory_cost_isk": round(totals["open_inventory_cost_isk"], 2),
            "open_inventory_market_value_isk": open_inventory_market_value_total,
            "open_inventory_unrealized_isk": open_inventory_unrealized_total,
            "open_quantity": int(totals["open_quantity"]),
            "unmatched_sell_revenue_isk": round(totals["unmatched_sell_revenue_isk"], 2),
            "unmatched_sell_quantity": int(totals["unmatched_sell_quantity"]),
            "market_transaction_journal_total_isk": round(market_transaction_journal_total, 2),
            "considered_result_isk": round(considered["considered_result_isk"], 2),
            "excluded_actual_profit_isk": round(considered["excluded_actual_profit_isk"], 2),
            "excluded_cashflow_isk": round(considered["excluded_cashflow_isk"], 2),
            "excluded_item_count": int(considered["excluded_item_count"]),
            "considered_item_count": int(considered["considered_item_count"]),
            "loss_item_count": int(considered["loss_item_count"]),
            "market_valued_open_item_count": market_valued_open_item_count,
            "market_unvalued_open_item_count": market_unvalued_open_item_count,
            "planned_item_count": len(plan_reconciliations),
            "planned_matched_item_count": len(plan_matched_reconciliations),
            "expected_plan_profit_isk": round_optional_float(expected_plan_profit_total),
            "actual_vs_plan_profit_isk": round_optional_float(actual_vs_plan_profit_total),
            "historical_transaction_count": historical_transaction_count,
            "historical_open_lot_count": historical_open_lot_count,
            "historical_ignored_transaction_count": historical_ignored_transactions,
        },
        "market_valuation": {
            "requested": valuation_requested,
            "status": market_valuation_status,
            "source": market_valuation_source or ("Fuzzwork" if valuation_requested else ""),
            "location": market_valuation_location or ("Jita 4-4" if valuation_requested else ""),
            "error": market_valuation_error,
            "valued_open_item_count": market_valued_open_item_count,
            "unvalued_open_item_count": market_unvalued_open_item_count,
        },
        "fee_ref_counts": dict(sorted(fee_ref_counts.items())),
        "expectation_source": "FIFO buy-vs-sell spread before wallet fees. Inventory mode adds estimated open-stock market value when available. Saved planner expectation snapshots are compared when available.",
        "limits_note": (
            "Only wallet transactions visible through recent ESI history are matched. "
            "Sells without visible buy lots are excluded from realized P&L and shown as unmatched."
        ),
    }


