def localized_name(payload: Any, fallback: str = "") -> str:
    if isinstance(payload, dict):
        return str(payload.get("en") or payload.get("en-us") or next(iter(payload.values()), fallback) or fallback)
    if payload is None:
        return fallback
    return str(payload)


def clean_haul_market_group_ids(raw_values: Iterable[Any]) -> tuple[int, ...]:
    group_ids: list[int] = []
    for raw_value in raw_values:
        if raw_value is None:
            continue
        for part in re.split(r"[,|\s]+", str(raw_value)):
            if not part:
                continue
            try:
                group_id = int(part)
            except (TypeError, ValueError):
                continue
            if group_id > 0 and group_id not in group_ids:
                group_ids.append(group_id)
            if len(group_ids) >= MAX_HAUL_MARKET_GROUP_IDS:
                return tuple(group_ids)
    return tuple(group_ids)


def clean_haul_market_type_ids(
    raw_values: Iterable[Any],
    *,
    limit: int = MAX_HAUL_MARKET_TYPE_IDS,
) -> tuple[int, ...]:
    type_ids: list[int] = []
    clean_limit = max(0, int(limit))
    if clean_limit <= 0:
        return ()
    for raw_value in raw_values:
        if raw_value is None:
            continue
        for part in re.split(r"[,|\s]+", str(raw_value)):
            if not part:
                continue
            try:
                type_id = int(part)
            except (TypeError, ValueError):
                continue
            if type_id > 0 and type_id not in type_ids:
                type_ids.append(type_id)
            if len(type_ids) >= clean_limit:
                return tuple(type_ids)
    return tuple(type_ids)


def clean_haul_market_type_names(
    raw_values: Iterable[Any],
    *,
    limit: int = MAX_HAUL_MARKET_TYPE_IDS,
) -> tuple[str, ...]:
    names: list[str] = []
    seen: set[str] = set()
    clean_limit = max(0, int(limit))
    if clean_limit <= 0:
        return ()
    for raw_value in raw_values:
        if raw_value is None:
            continue
        text = str(raw_value)[:MAX_HAUL_PASTED_ITEM_NAME_CHARS]
        for part in re.split(r"[\r\n,;|]+", text):
            name = " ".join(str(part or "").strip().strip("\"'`").split())
            if not name or name.startswith("#"):
                continue
            key = normalize_market_type_name_key(name)
            if key and key not in seen:
                seen.add(key)
                names.append(name)
            if len(names) >= clean_limit:
                return tuple(names)
    return tuple(names)


def normalize_market_type_name_key(value: Any) -> str:
    return re.sub(r"\s+", " ", str(value or "").strip().casefold())


def clean_haul_compare_destinations(raw_values: Iterable[Any]) -> tuple[str, ...]:
    destinations: list[str] = []
    seen: set[str] = set()
    for raw_value in raw_values:
        if raw_value is None:
            continue
        for part in re.split(r"[,|]+", str(raw_value)):
            destination = " ".join(str(part or "").split())
            if not destination:
                continue
            key = normalize_system_name(destination)
            if key and key not in seen:
                seen.add(key)
                destinations.append(destination)
            if len(destinations) >= MAX_HAUL_COMPARE_DESTINATIONS:
                return tuple(destinations)
    return tuple(destinations)


def clean_acquisition_compare_source_hubs(
    raw_values: Iterable[Any],
    *,
    destination_name: str = DEFAULT_HAUL_DESTINATION_SYSTEM,
) -> tuple[str, ...]:
    source_hubs: list[str] = []
    seen: set[str] = set()
    destination_key = normalize_system_name(destination_name)
    for raw_value in raw_values:
        if raw_value is None:
            continue
        for part in re.split(r"[\r\n,;|]+", str(raw_value)):
            source_hub = " ".join(str(part or "").split())
            if not source_hub:
                continue
            key = normalize_system_name(source_hub)
            if not key or key == destination_key or key in seen:
                continue
            seen.add(key)
            source_hubs.append(source_hub)
            if len(source_hubs) >= MAX_ACQUISITION_COMPARE_SOURCE_HUBS:
                return tuple(source_hubs)
    return tuple(source_hubs)


def load_static_market_data(path: Path = DEFAULT_STATIC_DATA_ZIP_PATH) -> StaticMarketData | None:
    if not path.exists():
        return None
    try:
        stat = path.stat()
    except OSError:
        return None
    cache_key = (str(path.resolve()), stat.st_mtime, stat.st_size)
    with STATIC_MARKET_DATA_LOCK:
        cached = STATIC_MARKET_DATA_CACHE.get(cache_key)
        if cached is not None:
            return cached
    groups: dict[int, dict[str, Any]] = {}
    children: dict[int, list[int]] = {}
    types_by_group: dict[int, list[dict[str, Any]]] = {}
    try:
        with zipfile.ZipFile(path) as archive:
            with archive.open("marketGroups.jsonl") as market_groups:
                for raw_line in market_groups:
                    payload = json.loads(raw_line)
                    group_id = int(payload.get("_key") or 0)
                    if group_id <= 0:
                        continue
                    parent_id = clean_optional_int(payload.get("parentGroupID"))
                    groups[group_id] = {
                        "market_group_id": group_id,
                        "name": localized_name(payload.get("name"), f"Market Group {group_id}"),
                        "parent_group_id": parent_id,
                    }
                    if parent_id is not None and parent_id > 0:
                        children.setdefault(parent_id, []).append(group_id)
            with archive.open("types.jsonl") as types:
                for raw_line in types:
                    payload = json.loads(raw_line)
                    market_group_id = clean_optional_int(payload.get("marketGroupID"))
                    if market_group_id is None or market_group_id <= 0:
                        continue
                    if payload.get("published") is False:
                        continue
                    type_id = int(payload.get("_key") or 0)
                    if type_id <= 0:
                        continue
                    volume_m3 = clean_optional_float(payload.get("volume"))
                    if volume_m3 is not None and volume_m3 <= 0:
                        volume_m3 = None
                    types_by_group.setdefault(market_group_id, []).append(
                        {
                            "type_id": type_id,
                            "name": localized_name(payload.get("name"), f"Type {type_id}"),
                            "volume_m3": volume_m3,
                            "market_group_id": market_group_id,
                            "market_group_name": groups.get(market_group_id, {}).get(
                                "name",
                                f"Market Group {market_group_id}",
                            ),
                        }
                    )
    except (OSError, KeyError, ValueError, json.JSONDecodeError, zipfile.BadZipFile):
        return None
    static_data = StaticMarketData(
        path=path,
        groups=groups,
        children={group_id: tuple(sorted(child_ids)) for group_id, child_ids in children.items()},
        types_by_group={
            group_id: tuple(sorted(type_infos, key=lambda item: (str(item["name"]), int(item["type_id"]))))
            for group_id, type_infos in types_by_group.items()
        },
    )
    with STATIC_MARKET_DATA_LOCK:
        STATIC_MARKET_DATA_CACHE.clear()
        STATIC_MARKET_DATA_CACHE[cache_key] = static_data
    return static_data


def market_group_descendant_ids(static_data: StaticMarketData, group_ids: Iterable[int]) -> set[int]:
    selected: set[int] = set()
    stack = [int(group_id) for group_id in group_ids if int(group_id) > 0]
    while stack:
        group_id = stack.pop()
        if group_id in selected:
            continue
        selected.add(group_id)
        stack.extend(static_data.children.get(group_id, ()))
    return selected


def fetch_market_group_detail(config: EveSsoConfig, market_group_id: int) -> dict[str, Any]:
    base_url = config.esi_base_url.rstrip("/")
    cache_key = (base_url, int(market_group_id))
    with MARKET_GROUP_DETAIL_CACHE_LOCK:
        cached = MARKET_GROUP_DETAIL_CACHE.get(cache_key)
        if cached is not None:
            return dict(cached)
    url = add_query_params(f"{base_url}/markets/groups/{int(market_group_id)}/", {"datasource": "tranquility"})
    try:
        payload = get_json(url, timeout_seconds=30.0, headers=flight_esi_headers())
    except (CorpIntelError, ValueError) as exc:
        raise CorpMarketError(f"ESI market group {market_group_id} lookup failed: {exc}") from exc
    if not isinstance(payload, dict):
        raise CorpMarketError(f"ESI market group {market_group_id} returned unexpected data.")
    with MARKET_GROUP_DETAIL_CACHE_LOCK:
        MARKET_GROUP_DETAIL_CACHE[cache_key] = dict(payload)
    return payload


def fetch_universe_type_detail(config: EveSsoConfig, type_id: int) -> dict[str, Any]:
    base_url = config.esi_base_url.rstrip("/")
    cache_key = (base_url, int(type_id))
    with MARKET_TYPE_DETAIL_CACHE_LOCK:
        cached = MARKET_TYPE_DETAIL_CACHE.get(cache_key)
        if cached is not None:
            return dict(cached)
    url = add_query_params(f"{base_url}/universe/types/{int(type_id)}/", {"datasource": "tranquility"})
    try:
        payload = get_json(url, timeout_seconds=30.0, headers=flight_esi_headers())
    except (CorpIntelError, ValueError) as exc:
        raise CorpMarketError(f"ESI type {type_id} lookup failed: {exc}") from exc
    if not isinstance(payload, dict):
        raise CorpMarketError(f"ESI type {type_id} returned unexpected data.")
    with MARKET_TYPE_DETAIL_CACHE_LOCK:
        MARKET_TYPE_DETAIL_CACHE[cache_key] = dict(payload)
    return payload


def build_market_group_targets_from_static(group_ids: Iterable[int]) -> tuple[list[dict[str, Any]], dict[str, Any]] | None:
    static_data = load_static_market_data()
    if static_data is None:
        return None
    clean_group_ids = clean_haul_market_group_ids(group_ids)
    descendant_group_ids = market_group_descendant_ids(static_data, clean_group_ids)
    targets_by_type_id: dict[int, dict[str, Any]] = {}
    for group_id in sorted(descendant_group_ids):
        group_name = str(static_data.groups.get(group_id, {}).get("name") or f"Market Group {group_id}")
        for type_info in static_data.types_by_group.get(group_id, ()):
            type_id = int(type_info["type_id"])
            targets_by_type_id.setdefault(
                type_id,
                {
                    "type_id": type_id,
                    "name": str(type_info["name"]),
                    "recipe_count": 0,
                    "volume_m3": type_info.get("volume_m3"),
                    "source": "market_group",
                    "source_label": group_name,
                    "market_group_id": group_id,
                    "market_group_name": group_name,
                },
            )
    selected_groups = [
        {
            "market_group_id": group_id,
            "name": str(static_data.groups.get(group_id, {}).get("name") or f"Market Group {group_id}"),
        }
        for group_id in clean_group_ids
    ]
    return (
        sorted(targets_by_type_id.values(), key=lambda item: (str(item["name"]), int(item["type_id"]))),
        {
            "source": "static-sde",
            "selected_market_groups": selected_groups,
            "selected_market_group_ids": list(clean_group_ids),
            "selected_market_group_count": len(clean_group_ids),
            "market_group_item_types": len(targets_by_type_id),
        },
    )


def build_market_group_targets_from_esi(
    config: EveSsoConfig,
    group_ids: Iterable[int],
    *,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    clean_group_ids = clean_haul_market_group_ids(group_ids)
    visited_group_ids: set[int] = set()
    type_group_names: dict[int, str] = {}
    selected_groups = []
    stack = list(reversed(clean_group_ids))
    while stack:
        group_id = stack.pop()
        if group_id in visited_group_ids:
            continue
        detail = fetch_market_group_detail(config, group_id)
        visited_group_ids.add(group_id)
        group_name = str(detail.get("name") or f"Market Group {group_id}")
        if group_id in clean_group_ids:
            selected_groups.append({"market_group_id": group_id, "name": group_name})
        for raw_type_id in detail.get("types") or []:
            try:
                type_id = int(raw_type_id)
            except (TypeError, ValueError):
                continue
            if type_id > 0:
                type_group_names.setdefault(type_id, group_name)
        child_ids = []
        for raw_child_id in detail.get("child_market_group_ids") or []:
            try:
                child_id = int(raw_child_id)
            except (TypeError, ValueError):
                continue
            if child_id > 0 and child_id not in visited_group_ids:
                child_ids.append(child_id)
        stack.extend(reversed(sorted(child_ids)))
    targets = []
    for type_id in sorted(type_group_names)[: max(0, detail_limit)]:
        detail = fetch_universe_type_detail(config, type_id)
        volume_m3 = clean_optional_float(detail.get("volume"))
        if volume_m3 is not None and volume_m3 <= 0:
            volume_m3 = None
        targets.append(
            {
                "type_id": type_id,
                "name": str(detail.get("name") or f"Type {type_id}"),
                "recipe_count": 0,
                "volume_m3": volume_m3,
                "source": "market_group",
                "source_label": type_group_names[type_id],
                "market_group_id": None,
                "market_group_name": type_group_names[type_id],
            }
        )
    return (
        sorted(targets, key=lambda item: (str(item["name"]), int(item["type_id"]))),
        {
            "source": "esi-market-groups",
            "selected_market_groups": selected_groups,
            "selected_market_group_ids": list(clean_group_ids),
            "selected_market_group_count": len(clean_group_ids),
            "market_group_item_types": len(type_group_names),
        },
    )


def build_market_group_targets(config: EveSsoConfig, group_ids: Iterable[int]) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    static_result = build_market_group_targets_from_static(group_ids)
    if static_result is not None:
        return static_result
    return build_market_group_targets_from_esi(config, group_ids, detail_limit=MAX_FLIGHT_HAUL_SCAN_TYPES)


def static_market_type_infos_by_id(static_data: StaticMarketData) -> dict[int, dict[str, Any]]:
    type_infos_by_id: dict[int, dict[str, Any]] = {}
    for group_id, type_infos in static_data.types_by_group.items():
        group_name = market_group_display_name(static_data, group_id)
        for type_info in type_infos:
            try:
                type_id = int(type_info.get("type_id") or 0)
            except (TypeError, ValueError):
                continue
            if type_id <= 0 or type_id in type_infos_by_id:
                continue
            type_infos_by_id[type_id] = {
                **type_info,
                "market_group_id": group_id,
                "market_group_name": group_name,
            }
    return type_infos_by_id


def static_market_type_infos_by_name(static_data: StaticMarketData) -> dict[str, list[dict[str, Any]]]:
    type_infos_by_name: dict[str, list[dict[str, Any]]] = {}
    for type_info in static_market_type_infos_by_id(static_data).values():
        key = normalize_market_type_name_key(type_info.get("name"))
        if not key:
            continue
        type_infos_by_name.setdefault(key, []).append(type_info)
    return type_infos_by_name


def resolve_haul_market_type_names(
    raw_values: Iterable[Any],
    *,
    limit: int = MAX_HAUL_MARKET_TYPE_IDS,
) -> tuple[tuple[int, ...], dict[str, Any]]:
    clean_names = clean_haul_market_type_names(raw_values, limit=limit)
    if not clean_names:
        return (
            (),
            {
                "pasted_market_type_names": [],
                "resolved_pasted_market_types": [],
                "resolved_pasted_market_type_ids": [],
                "resolved_pasted_market_type_count": 0,
                "unresolved_pasted_market_type_names": [],
                "ambiguous_pasted_market_type_names": [],
                "pasted_market_type_count": 0,
                "pasted_market_type_source": "",
            },
        )
    static_data = load_static_market_data()
    if static_data is None:
        return (
            (),
            {
                "pasted_market_type_names": list(clean_names),
                "resolved_pasted_market_types": [],
                "resolved_pasted_market_type_ids": [],
                "resolved_pasted_market_type_count": 0,
                "unresolved_pasted_market_type_names": list(clean_names),
                "ambiguous_pasted_market_type_names": [],
                "pasted_market_type_count": len(clean_names),
                "pasted_market_type_source": "static-sde-missing",
            },
        )
    type_infos_by_name = static_market_type_infos_by_name(static_data)
    resolved_type_ids: list[int] = []
    resolved_types: list[dict[str, Any]] = []
    unresolved_names: list[str] = []
    ambiguous_names: list[str] = []
    for name in clean_names:
        matches = type_infos_by_name.get(normalize_market_type_name_key(name), [])
        if len(matches) != 1:
            if matches:
                ambiguous_names.append(name)
            else:
                unresolved_names.append(name)
            continue
        match = matches[0]
        type_id = int(match["type_id"])
        if type_id not in resolved_type_ids:
            resolved_type_ids.append(type_id)
            resolved_types.append(
                {
                    "type_id": type_id,
                    "name": str(match.get("name") or name),
                    "market_group_id": match.get("market_group_id"),
                    "market_group_name": match.get("market_group_name") or "",
                }
            )
        if len(resolved_type_ids) >= max(0, int(limit)):
            break
    return (
        tuple(resolved_type_ids),
        {
            "pasted_market_type_names": list(clean_names),
            "resolved_pasted_market_types": resolved_types,
            "resolved_pasted_market_type_ids": list(resolved_type_ids),
            "resolved_pasted_market_type_count": len(resolved_type_ids),
            "unresolved_pasted_market_type_names": unresolved_names,
            "ambiguous_pasted_market_type_names": ambiguous_names,
            "pasted_market_type_count": len(clean_names),
            "pasted_market_type_source": "static-sde",
        },
    )


def build_market_type_targets_from_static(type_ids: Iterable[int]) -> tuple[list[dict[str, Any]], dict[str, Any]] | None:
    static_data = load_static_market_data()
    if static_data is None:
        return None
    clean_type_ids = clean_haul_market_type_ids(type_ids)
    type_infos_by_id = static_market_type_infos_by_id(static_data)

    targets = []
    selected_types = []
    for type_id in clean_type_ids:
        type_info = type_infos_by_id.get(type_id)
        target = {
            "type_id": type_id,
            "name": str((type_info.get("name") if type_info else None) or f"Type {type_id}"),
            "recipe_count": 0,
            "volume_m3": type_info.get("volume_m3") if type_info else None,
            "source": "market_type",
            "source_label": "Selected items",
            "market_group_id": type_info.get("market_group_id") if type_info else None,
            "market_group_name": type_info.get("market_group_name") if type_info else "",
        }
        targets.append(target)
        selected_types.append(
            {
                "type_id": type_id,
                "name": target["name"],
                "market_group_id": target.get("market_group_id"),
                "market_group_name": target.get("market_group_name") or "",
            }
        )
    return (
        sorted(targets, key=lambda item: (str(item["name"]), int(item["type_id"]))),
        {
            "source": "static-sde",
            "selected_market_type_ids": list(clean_type_ids),
            "selected_market_types": selected_types,
            "selected_market_type_count": len(clean_type_ids),
            "market_type_item_types": len(targets),
        },
    )


def build_market_type_targets_from_esi(
    config: EveSsoConfig,
    type_ids: Iterable[int],
    *,
    detail_limit: int,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    clean_type_ids = clean_haul_market_type_ids(type_ids, limit=detail_limit)
    targets = []
    selected_types = []
    for type_id in clean_type_ids:
        detail = fetch_universe_type_detail(config, type_id)
        volume_m3 = clean_optional_float(detail.get("volume"))
        if volume_m3 is not None and volume_m3 <= 0:
            volume_m3 = None
        market_group_id = clean_optional_int(detail.get("market_group_id") or detail.get("marketGroupID"))
        target = {
            "type_id": type_id,
            "name": str(detail.get("name") or f"Type {type_id}"),
            "recipe_count": 0,
            "volume_m3": volume_m3,
            "source": "market_type",
            "source_label": "Selected items",
            "market_group_id": market_group_id,
            "market_group_name": "",
        }
        targets.append(target)
        selected_types.append(
            {
                "type_id": type_id,
                "name": target["name"],
                "market_group_id": market_group_id,
                "market_group_name": "",
            }
        )
    return (
        sorted(targets, key=lambda item: (str(item["name"]), int(item["type_id"]))),
        {
            "source": "esi-types",
            "selected_market_type_ids": list(clean_type_ids),
            "selected_market_types": selected_types,
            "selected_market_type_count": len(clean_type_ids),
            "market_type_item_types": len(targets),
        },
    )


def build_market_type_targets(config: EveSsoConfig, type_ids: Iterable[int]) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    static_result = build_market_type_targets_from_static(type_ids)
    if static_result is not None:
        return static_result
    return build_market_type_targets_from_esi(config, type_ids, detail_limit=MAX_HAUL_MARKET_TYPE_IDS)


