def build_flight_hauling_payload(
    *,
    config: EveSsoConfig,
    session: FlightEsiSession,
    origin_name: str = "",
    destination_name: str = DEFAULT_HAUL_DESTINATION_SYSTEM,
    detour_jumps: int = DEFAULT_HAUL_DETOUR_JUMPS,
    cargo_capacity_m3: float = DEFAULT_HAUL_CARGO_M3,
    purchase_budget_isk: float = DEFAULT_HAUL_PURCHASE_BUDGET_ISK,
    min_detour_margin_percent: float = DEFAULT_HAUL_MIN_DETOUR_MARGIN_PERCENT,
    route_preference: str = DEFAULT_HAUL_ROUTE_PREFERENCE,
    avoid_recent_pod_kills: bool = DEFAULT_HAUL_AVOID_RECENT_POD_KILLS,
    include_common_materials: bool = True,
    market_group_ids: Iterable[int] = (),
    market_type_ids: Iterable[int] = (),
    market_type_names: Iterable[Any] = (),
    sort_by: str = DEFAULT_HAUL_SORT_BY,
    min_profit_per_m3: float = 0.0,
    min_profit_per_extra_jump: float = 0.0,
    learning_store: MarketStore | None = None,
    progress: Callable[[str, dict[str, Any]], None] | None = None,
) -> dict[str, Any]:
    server_timer = StageTimer()
    require_flight_scopes(session, (FLIGHT_LOCATION_SCOPE, FLIGHT_SKILLS_SCOPE))
    location = fetch_flight_location(config, session)
    server_timer.mark("location", "Read ESI location")
    current_solar_system_id = int(location.get("solar_system_id") or 0)
    route_cache = load_route_graph_cache()
    if not route_cache.available:
        raise CorpMarketError(route_cache.error or "Route graph cache is not available.")
    recipe_cache = load_industry_recipe_cache()
    if not recipe_cache.available:
        raise CorpMarketError(recipe_cache.error or "Recipe cache is not available.")
    server_timer.mark("static_caches", "Load route and recipe caches")
    systems = route_cache.systems or {}
    adjacency = route_cache.adjacency or {}
    clean_origin_name = str(origin_name or "").strip()
    if clean_origin_name:
        origin = resolve_route_system(route_cache, clean_origin_name)
        if origin is None:
            raise CorpMarketError(f"Starting system {clean_origin_name!r} was not found in the route graph cache.")
        origin_source = "manual"
    else:
        origin = systems.get(current_solar_system_id)
        origin_source = "esi-location"
    if origin is None:
        raise CorpMarketError(f"Current system {current_solar_system_id} is not in the route graph cache.")
    destination = resolve_route_system(route_cache, destination_name)
    if destination is None:
        raise CorpMarketError(f"Destination system {destination_name!r} was not found in the route graph cache.")
    route_plan = build_haul_route_plan(
        config=config,
        origin_solar_system_id=origin.solar_system_id,
        destination_solar_system_id=destination.solar_system_id,
        route_preference=route_preference,
        avoid_recent_pod_kills=bool(avoid_recent_pod_kills),
        adjacency=adjacency,
    )
    route_path = route_plan["path"]
    if not route_path:
        raise CorpMarketError(f"No stargate route from {origin.name} to {destination.name} was found.")
    server_timer.mark("route_plan", "Build route plan", route_jumps=max(0, len(route_path) - 1))
    skills = fetch_flight_skills(config, session)
    sales_tax = build_sales_tax_profile(skills)
    server_timer.mark(
        "tax_profile",
        "Read skills and sales tax profile",
        accounting_level=sales_tax.get("accounting_level"),
    )
    opportunities = scan_route_hauling_opportunities(
        config=config,
        recipe_cache=recipe_cache,
        route_cache=route_cache,
        origin_solar_system_id=origin.solar_system_id,
        destination_solar_system_id=destination.solar_system_id,
        route_path=route_path,
        detour_jumps=detour_jumps,
        cargo_capacity_m3=cargo_capacity_m3,
        purchase_budget_isk=purchase_budget_isk,
        min_detour_margin_percent=min_detour_margin_percent,
        sales_tax=sales_tax,
        include_common_materials=include_common_materials,
        market_group_ids=market_group_ids,
        market_type_ids=market_type_ids,
        market_type_names=market_type_names,
        sort_by=sort_by,
        min_profit_per_m3=min_profit_per_m3,
        min_profit_per_extra_jump=min_profit_per_extra_jump,
        progress=progress,
    )
    server_timer.mark(
        "opportunity_scan",
        "Scan route hauling opportunities",
        scanned_item_types=opportunities.get("scanned_item_types"),
        profitable_opportunities=opportunities.get("profitable_opportunities"),
    )
    route_systems = [systems[system_id].to_dict(jumps=index) for index, system_id in enumerate(route_path) if system_id in systems]
    route_jumps = max(0, len(route_path) - 1)
    server_timing = server_timer.to_public_dict()
    generated_at = now_iso()
    route_payload = {
        "origin": origin.to_dict(jumps=0),
        "destination": destination.to_dict(jumps=max(0, len(route_path) - 1)),
        "origin_query": clean_origin_name,
        "origin_source": origin_source,
        "destination_query": destination_name,
        "route_jumps": route_jumps,
        "detour_jumps": clamp_haul_detour_jumps(detour_jumps),
        "cargo_capacity_m3": clamp_haul_cargo_m3(cargo_capacity_m3),
        "purchase_budget_isk": clamp_haul_purchase_budget_isk(purchase_budget_isk),
        "min_detour_margin_percent": clamp_haul_min_detour_margin_percent(min_detour_margin_percent),
        "route_preference": route_plan["preference"],
        "route_preference_label": route_plan["preference_label"],
        "route_source": route_plan["source"],
        "avoid_recent_pod_kills": route_plan["avoid_recent_pod_kills"],
        "recent_pod_kill_system_count": route_plan["recent_pod_kill_system_count"],
        "avoided_pod_kill_system_count": len(route_plan["avoided_pod_kill_system_ids"]),
        "route_pod_kill_system_count": len(route_plan["route_pod_kill_system_ids"]),
        "route_warning": route_plan["warning"],
        "diagnostics": build_haul_route_diagnostics(route_plan, route_jumps=route_jumps),
        "systems": route_systems,
    }
    load_plan = opportunities.get("load_plan") if isinstance(opportunities.get("load_plan"), Mapping) else {}
    opportunities["learning"] = attach_local_trade_learning_signals(
        learning_store=learning_store,
        character_id=session.character_id,
        item_groups=(
            [item for item in opportunities.get("opportunities") or [] if isinstance(item, dict)],
            [item for item in load_plan.get("lines") or [] if isinstance(item, dict)],
        ),
    )
    opportunities["report_rows"] = build_haul_expected_realized_report_rows(
        generated_at=generated_at,
        route=route_payload,
        hauling=opportunities,
    )
    data_sources = [
        workflow_source_badge(
            key="location-esi",
            label="Current location ESI",
            status="ready",
            posture="read-only ESI",
            freshness=generated_at,
            persistence="response summary only",
            scope=FLIGHT_LOCATION_SCOPE,
            detail="Used to anchor the route when no manual origin override is supplied.",
        ),
        workflow_source_badge(
            key="skills-esi",
            label="Skills ESI",
            status="ready",
            posture="read-only ESI",
            freshness=generated_at,
            persistence="response summary only",
            scope=FLIGHT_SKILLS_SCOPE,
            detail="Accounting skill is summarized for downstream sales-tax estimates.",
        ),
        cache_source_badge(
            key="route-cache",
            label="Route graph cache",
            cache=route_cache,
            detail="Local route graph supports route corridor, pickup radius, and fallback path calculations.",
        ),
        cache_source_badge(
            key="recipe-cache",
            label="Recipe cache",
            cache=recipe_cache,
            detail="Local recipe/material cache supplies common material and type candidates.",
        ),
        market_cache_source_badge(
            key="market-order-cache",
            label="Public market orders",
            cache_status=opportunities.get("market_cache") or {},
            detail="Pickup sell orders and destination buy orders come from public ESI market data.",
        ),
        market_cache_source_badge(
            key="market-history-cache",
            label="Public market history",
            cache_status=opportunities.get("history_cache") or {},
            detail="Market history labels possible traps, sparse volume, and price spikes.",
        ),
        workflow_source_badge(
            key="manual-route-settings",
            label="Manual route and cargo settings",
            status="manual",
            posture="browser input",
            freshness="current form value",
            persistence="browser localStorage only",
            detail="Destination, cargo capacity, purchase budget, filters, and pasted item scope are user-controlled.",
        ),
        sqlite_source_badge(
            enabled=learning_store is not None,
            detail="Local Trade P&L learning signals can annotate route candidates when previous evidence exists.",
        ),
    ]
    opportunities["data_sources"] = data_sources
    return {
        "ok": True,
        "generated_at": generated_at,
        "server_timing": server_timing,
        "character": session.to_public_dict(),
        "data_sources": data_sources,
        "location": location,
        "route": route_payload,
        "hauling": opportunities,
    }


def summarize_haul_payload_for_comparison(destination_name: str, payload: Mapping[str, Any]) -> dict[str, Any]:
    route = payload.get("route") if isinstance(payload.get("route"), dict) else {}
    hauling = payload.get("hauling") if isinstance(payload.get("hauling"), dict) else {}
    load_plan = hauling.get("load_plan") if isinstance(hauling.get("load_plan"), dict) else {}
    opportunities = hauling.get("opportunities") if isinstance(hauling.get("opportunities"), list) else []
    best_opportunity = opportunities[0] if opportunities and isinstance(opportunities[0], dict) else {}
    load_available = bool(load_plan.get("available"))
    net_profit = float(load_plan.get("net_profit") or 0.0) if load_available else 0.0
    return {
        "ok": True,
        "destination": destination_name,
        "destination_name": (route.get("destination") or {}).get("name") or destination_name,
        "route_jumps": int(route.get("route_jumps") or 0),
        "route_source": route.get("route_source") or "",
        "route_warning": route.get("route_warning") or "",
        "profitable_opportunities": int(hauling.get("profitable_opportunities") or 0),
        "total_profitable_opportunities": int(hauling.get("total_profitable_opportunities") or 0),
        "efficiency_filter_rejected_count": int(hauling.get("efficiency_filter_rejected_count") or 0),
        "possible_trap_count": int(hauling.get("possible_trap_count") or 0),
        "load_plan_available": load_available,
        "load_plan_net_profit": net_profit,
        "load_plan_pickup_cost": float(load_plan.get("pickup_cost") or 0.0) if load_available else 0.0,
        "load_plan_cargo_percent": float(load_plan.get("cargo_percent") or 0.0) if load_available else 0.0,
        "load_plan_stop_count": int(load_plan.get("stop_count") or 0) if load_available else 0,
        "best_item_name": best_opportunity.get("item_name") or "",
        "best_item_net_profit": float(best_opportunity.get("net_profit") or 0.0) if best_opportunity else 0.0,
        "best_item_margin_percent": best_opportunity.get("margin_percent"),
    }


def build_flight_hauling_comparison_payload(
    *,
    config: EveSsoConfig,
    session: FlightEsiSession,
    origin_name: str = "",
    destinations: Iterable[Any] = (),
    detour_jumps: int = DEFAULT_HAUL_DETOUR_JUMPS,
    cargo_capacity_m3: float = DEFAULT_HAUL_CARGO_M3,
    purchase_budget_isk: float = DEFAULT_HAUL_PURCHASE_BUDGET_ISK,
    min_detour_margin_percent: float = DEFAULT_HAUL_MIN_DETOUR_MARGIN_PERCENT,
    route_preference: str = DEFAULT_HAUL_ROUTE_PREFERENCE,
    avoid_recent_pod_kills: bool = DEFAULT_HAUL_AVOID_RECENT_POD_KILLS,
    include_common_materials: bool = True,
    market_group_ids: Iterable[int] = (),
    market_type_ids: Iterable[int] = (),
    market_type_names: Iterable[Any] = (),
    sort_by: str = DEFAULT_HAUL_SORT_BY,
    min_profit_per_m3: float = 0.0,
    min_profit_per_extra_jump: float = 0.0,
    learning_store: MarketStore | None = None,
) -> dict[str, Any]:
    destination_names = clean_haul_compare_destinations(destinations) or DEFAULT_HAUL_COMPARE_DESTINATIONS
    results: list[dict[str, Any]] = []
    for destination_name in destination_names:
        try:
            payload = build_flight_hauling_payload(
                config=config,
                session=session,
                origin_name=origin_name,
                destination_name=destination_name,
                detour_jumps=detour_jumps,
                cargo_capacity_m3=cargo_capacity_m3,
                purchase_budget_isk=purchase_budget_isk,
                min_detour_margin_percent=min_detour_margin_percent,
                route_preference=route_preference,
                avoid_recent_pod_kills=avoid_recent_pod_kills,
                include_common_materials=include_common_materials,
                market_group_ids=market_group_ids,
                market_type_ids=market_type_ids,
                market_type_names=market_type_names,
                sort_by=sort_by,
                min_profit_per_m3=min_profit_per_m3,
                min_profit_per_extra_jump=min_profit_per_extra_jump,
                learning_store=learning_store,
            )
        except CorpMarketError as exc:
            results.append({"ok": False, "destination": destination_name, "destination_name": destination_name, "error": str(exc)})
            continue
        results.append(summarize_haul_payload_for_comparison(destination_name, payload))
    ranked = sorted(
        [result for result in results if result.get("ok")],
        key=lambda result: (
            float(result.get("load_plan_net_profit") or 0.0),
            int(result.get("profitable_opportunities") or 0),
            -int(result.get("route_jumps") or 0),
        ),
        reverse=True,
    )
    best = ranked[0] if ranked else {}
    return {
        "ok": True,
        "generated_at": now_iso(),
        "character": session.to_public_dict(),
        "comparison": {
            "requested_destinations": list(destination_names),
            "destination_count": len(destination_names),
            "successful_count": len(ranked),
            "failed_count": len(results) - len(ranked),
            "best": best,
            "results": ranked + [result for result in results if not result.get("ok")],
            "manual_note": (
                "Compare hubs with the same item scope, cargo, budget, route rules, and detour settings. "
                "Pilot still verifies route, docking access, and prices in EVE."
            ),
        },
    }


def tag_acquisition_comparison_opportunity(opportunity: Mapping[str, Any], *, source_hub_name: str) -> dict[str, Any]:
    tagged = dict(opportunity)
    tagged["source_hub_name"] = source_hub_name
    tagged["comparison_source_hub"] = source_hub_name
    if not str(tagged.get("placement_system") or "").strip():
        tagged["placement_system"] = source_hub_name
    return tagged


def acquisition_comparison_opportunity_sort_key(opportunity: Mapping[str, Any]) -> tuple[Any, ...]:
    return (
        acquisition_risk_sort_rank(str(opportunity.get("risk_level") or "")),
        -float(opportunity.get("net_profit") or 0.0),
        -float(opportunity.get("margin_percent") or 0.0),
        str(opportunity.get("item_name") or ""),
        str(opportunity.get("source_hub_name") or opportunity.get("placement_system") or ""),
    )


def dedupe_acquisition_comparison_opportunities(opportunities: Iterable[dict[str, Any]]) -> list[dict[str, Any]]:
    selected: list[dict[str, Any]] = []
    seen: set[str] = set()
    for opportunity in sorted(opportunities, key=acquisition_comparison_opportunity_sort_key):
        type_id = clean_optional_int(opportunity.get("type_id"))
        key = f"type:{type_id}" if type_id is not None else f"name:{str(opportunity.get('item_name') or '').casefold()}"
        if not key or key in seen:
            continue
        seen.add(key)
        selected.append(opportunity)
    return selected


def summarize_acquisition_payload_for_comparison(source_hub_name: str, payload: Mapping[str, Any]) -> dict[str, Any]:
    route = payload.get("route") if isinstance(payload.get("route"), Mapping) else {}
    acquisition = payload.get("acquisition") if isinstance(payload.get("acquisition"), Mapping) else {}
    portfolio = acquisition.get("portfolio") if isinstance(acquisition.get("portfolio"), Mapping) else {}
    lines = list(portfolio.get("lines") or []) if isinstance(portfolio.get("lines"), list) else []
    opportunities = list(acquisition.get("opportunities") or []) if isinstance(acquisition.get("opportunities"), list) else []
    best_item = lines[0] if lines and isinstance(lines[0], Mapping) else (
        opportunities[0] if opportunities and isinstance(opportunities[0], Mapping) else {}
    )
    origin = route.get("origin") if isinstance(route.get("origin"), Mapping) else {}
    destination = route.get("destination") if isinstance(route.get("destination"), Mapping) else {}
    invested_isk = float(portfolio.get("invested_isk") or 0.0)
    estimated_net_profit = float(portfolio.get("estimated_net_profit") or 0.0)
    excluded_counts = portfolio.get("excluded_reason_counts") if isinstance(portfolio.get("excluded_reason_counts"), Mapping) else {}
    return {
        "ok": True,
        "source_hub": source_hub_name,
        "source_hub_name": str(origin.get("name") or source_hub_name),
        "destination_name": str(destination.get("name") or route.get("destination_query") or ""),
        "route_jumps": int(route.get("route_jumps") or 0),
        "route_source": route.get("route_source") or "",
        "route_warning": route.get("route_warning") or "",
        "portfolio_available": bool(portfolio.get("available")),
        "portfolio_line_count": int(portfolio.get("line_count") or 0),
        "opportunity_count": int(acquisition.get("opportunity_count") or len(opportunities)),
        "invested_isk": invested_isk,
        "budget_remaining_isk": float(portfolio.get("budget_remaining_isk") or 0.0),
        "estimated_net_profit": estimated_net_profit,
        "margin_percent": portfolio.get("margin_percent"),
        "used_jumps": int(portfolio.get("used_jumps") or 0),
        "max_portfolio_jumps": int(portfolio.get("max_portfolio_jumps") or acquisition.get("portfolio_jumps") or 0),
        "possible_trap_count": int(
            portfolio.get("possible_trap_excluded_count") or acquisition.get("possible_trap_count") or 0
        ),
        "caution_line_count": int(portfolio.get("caution_line_count") or 0),
        "excluded_reason_counts": dict(excluded_counts),
        "best_item_name": best_item.get("item_name") if isinstance(best_item, Mapping) else "",
        "best_item_net_profit": float(best_item.get("net_profit") or 0.0) if isinstance(best_item, Mapping) else 0.0,
        "best_item_margin_percent": best_item.get("margin_percent") if isinstance(best_item, Mapping) else None,
    }


def build_flight_acquisition_comparison_payload(
    *,
    config: EveSsoConfig,
    session: FlightEsiSession,
    source_hubs: Iterable[Any] = (),
    destination_name: str = DEFAULT_HAUL_DESTINATION_SYSTEM,
    budget_isk: float = DEFAULT_ACQUISITION_BUDGET_ISK,
    pickup_jumps: int = DEFAULT_ACQUISITION_PICKUP_JUMPS,
    portfolio_jumps: int = DEFAULT_ACQUISITION_PORTFOLIO_JUMPS,
    min_margin_percent: float = DEFAULT_HAUL_MIN_DETOUR_MARGIN_PERCENT,
    broker_fee_percent: float = DEFAULT_ACQUISITION_BROKER_FEE_PERCENT,
    target_days: int = DEFAULT_ACQUISITION_TARGET_DAYS,
    order_duration_days: int = DEFAULT_ACQUISITION_ORDER_DURATION_DAYS,
    history_analysis_mode: str = DEFAULT_ACQUISITION_HISTORY_ANALYSIS_MODE,
    route_preference: str = DEFAULT_HAUL_ROUTE_PREFERENCE,
    include_common_materials: bool = True,
    market_group_ids: Iterable[int] = (),
    market_type_ids: Iterable[int] = (),
    market_type_names: Iterable[Any] = (),
    item_workers: int = DEFAULT_FLIGHT_ACQUISITION_ITEM_WORKERS,
    learning_store: MarketStore | None = None,
    progress: Callable[[str, dict[str, Any]], None] | None = None,
) -> dict[str, Any]:
    clean_destination_name = str(destination_name or DEFAULT_HAUL_DESTINATION_SYSTEM).strip() or DEFAULT_HAUL_DESTINATION_SYSTEM
    clean_source_hubs = clean_acquisition_compare_source_hubs(source_hubs, destination_name=clean_destination_name)
    if not clean_source_hubs:
        clean_source_hubs = clean_acquisition_compare_source_hubs(
            DEFAULT_ACQUISITION_COMPARE_SOURCE_HUBS,
            destination_name=clean_destination_name,
        )
    if not clean_source_hubs:
        raise CorpMarketError("Choose at least one buy hub that is not the downstream destination.")

    generated_at = now_iso()
    results: list[dict[str, Any]] = []
    combined_opportunities: list[dict[str, Any]] = []
    successful_payloads: list[dict[str, Any]] = []
    source_count = len(clean_source_hubs)
    if progress is not None:
        progress(
            "comparison_start",
            {
                "message": (
                    f"Comparing {source_count} buy hub{'s' if source_count != 1 else ''} toward "
                    f"{clean_destination_name}."
                ),
                "percent": 1,
            },
        )

    def hub_percent(index: int, inner_percent: Any = 0) -> int:
        try:
            clean_inner = max(0.0, min(100.0, float(inner_percent)))
        except (TypeError, ValueError):
            clean_inner = 0.0
        return max(1, min(96, round(3 + (((index - 1) + (clean_inner / 100.0)) / source_count) * 92)))

    for index, source_hub in enumerate(clean_source_hubs, start=1):
        source_hub_name = str(source_hub)
        if progress is not None:
            progress(
                "hub_start",
                {
                    "source_hub": source_hub_name,
                    "hub_index": index,
                    "hub_count": source_count,
                    "message": f"{source_hub_name}: starting buy-hub portfolio comparison.",
                    "percent": hub_percent(index, 0),
                },
            )

        def hub_progress(event_name: str, payload: dict[str, Any], *, hub: str = source_hub_name, hub_index: int = index) -> None:
            if progress is None:
                return
            nested = dict(payload)
            nested["source_hub"] = hub
            nested["hub_index"] = hub_index
            nested["hub_count"] = source_count
            nested["stage"] = event_name
            nested["message"] = f"{hub}: {payload.get('message') or event_name}"
            nested["percent"] = hub_percent(hub_index, payload.get("percent", 0))
            progress("hub_progress", nested)

        try:
            payload = build_flight_acquisition_payload(
                config=config,
                session=session,
                origin_name=source_hub_name,
                destination_name=clean_destination_name,
                budget_isk=budget_isk,
                pickup_jumps=pickup_jumps,
                portfolio_jumps=portfolio_jumps,
                min_margin_percent=min_margin_percent,
                broker_fee_percent=broker_fee_percent,
                target_days=target_days,
                order_duration_days=order_duration_days,
                history_analysis_mode=history_analysis_mode,
                route_preference=route_preference,
                include_common_materials=include_common_materials,
                market_group_ids=market_group_ids,
                market_type_ids=market_type_ids,
                market_type_names=market_type_names,
                item_workers=item_workers,
                expectation_store=None,
                learning_store=learning_store,
                progress=hub_progress,
            )
        except CorpMarketError as exc:
            results.append(
                {
                    "ok": False,
                    "source_hub": source_hub_name,
                    "source_hub_name": source_hub_name,
                    "destination_name": clean_destination_name,
                    "error": str(exc),
                }
            )
            if progress is not None:
                progress(
                    "hub_failed",
                    {
                        "source_hub": source_hub_name,
                        "hub_index": index,
                        "hub_count": source_count,
                        "message": f"{source_hub_name}: {exc}",
                        "percent": hub_percent(index, 100),
                    },
                )
            continue

        successful_payloads.append(payload)
        summary = summarize_acquisition_payload_for_comparison(source_hub_name, payload)
        results.append(summary)
        acquisition = payload.get("acquisition") if isinstance(payload.get("acquisition"), Mapping) else {}
        for opportunity in acquisition.get("opportunities") or []:
            if isinstance(opportunity, Mapping):
                combined_opportunities.append(
                    tag_acquisition_comparison_opportunity(opportunity, source_hub_name=summary["source_hub_name"])
                )
        if progress is not None:
            progress(
                "hub_done",
                {
                    "source_hub": source_hub_name,
                    "hub_index": index,
                    "hub_count": source_count,
                    "message": (
                        f"{source_hub_name}: built {summary['portfolio_line_count']} funded line"
                        f"{'s' if summary['portfolio_line_count'] != 1 else ''}."
                    ),
                    "percent": hub_percent(index, 100),
                },
            )

    ranked_results = sorted(
        [result for result in results if result.get("ok")],
        key=lambda result: (
            float(result.get("estimated_net_profit") or 0.0),
            float(result.get("invested_isk") or 0.0),
            int(result.get("portfolio_line_count") or 0),
            -int(result.get("possible_trap_count") or 0),
        ),
        reverse=True,
    )
    if progress is not None:
        progress(
            "combined_portfolio",
            {
                "message": f"Building one shared-budget plan from {len(combined_opportunities)} hub candidate row(s).",
                "candidate_count": len(combined_opportunities),
                "percent": 98,
            },
        )
    combined_candidates = dedupe_acquisition_comparison_opportunities(combined_opportunities)
    combined_portfolio = build_acquisition_investment_portfolio(
        opportunities=combined_candidates,
        budget_isk=budget_isk,
        max_portfolio_jumps=portfolio_jumps,
        pickup_jumps=pickup_jumps,
    )
    first_payload = successful_payloads[0] if successful_payloads else {}
    first_route = first_payload.get("route") if isinstance(first_payload.get("route"), Mapping) else {}
    first_acquisition = first_payload.get("acquisition") if isinstance(first_payload.get("acquisition"), Mapping) else {}
    destination_payload = first_route.get("destination") if isinstance(first_route.get("destination"), Mapping) else {}
    if not destination_payload:
        destination_payload = first_acquisition.get("destination_system") if isinstance(first_acquisition.get("destination_system"), Mapping) else {}
    destination_payload = dict(destination_payload or {"name": clean_destination_name})
    combined_opportunity_rows = combined_candidates[:MAX_FLIGHT_ACQUISITION_OPPORTUNITIES]
    combined_acquisition = {
        "origin_system": {"name": "Multiple buy hubs"},
        "destination_system": destination_payload,
        "budget_isk": clamp_acquisition_budget_isk(budget_isk),
        "pickup_jumps": clamp_acquisition_pickup_jumps(pickup_jumps),
        "portfolio_jumps": clamp_acquisition_portfolio_jumps(portfolio_jumps),
        "min_margin_percent": clamp_haul_min_detour_margin_percent(min_margin_percent),
        "broker_fee_percent": clamp_acquisition_broker_fee_percent(broker_fee_percent),
        "target_days": clamp_acquisition_target_days(target_days),
        "order_duration_days": clamp_acquisition_order_duration_days(order_duration_days),
        "history_analysis_mode": normalize_acquisition_history_analysis_mode(history_analysis_mode),
        "history_analysis_label": acquisition_history_analysis_label(history_analysis_mode),
        "item_workers": clamp_acquisition_item_workers(item_workers),
        "opportunity_count": len(combined_candidates),
        "possible_trap_count": combined_portfolio.get("possible_trap_excluded_count", 0),
        "portfolio": combined_portfolio,
        "opportunities": combined_opportunity_rows,
    }
    combined_acquisition["learning"] = attach_local_trade_learning_signals(
        learning_store=learning_store,
        character_id=session.character_id,
        item_groups=(
            [item for item in combined_opportunity_rows if isinstance(item, dict)],
            [item for item in combined_portfolio.get("lines") or [] if isinstance(item, dict)],
        ),
    )
    combined_route = {
        "origin": {"name": "Multiple buy hubs"},
        "destination": destination_payload,
        "origin_query": ", ".join(clean_source_hubs),
        "origin_source": "hub-comparison",
        "destination_query": clean_destination_name,
        "route_jumps": None,
        "route_preference": normalize_haul_route_preference(route_preference),
        "route_preference_label": normalize_haul_route_preference(route_preference).replace("_", " ").title(),
        "route_source": "hub-comparison",
        "route_warning": "",
        "systems": [],
    }
    combined_report_rows = build_acquisition_expected_realized_report_rows(
        generated_at=generated_at,
        route=combined_route,
        acquisition=combined_acquisition,
    )
    combined_acquisition["report_rows"] = combined_report_rows
    failed_results = [result for result in results if not result.get("ok")]
    return {
        "ok": True,
        "generated_at": generated_at,
        "character": session.to_public_dict(),
        "comparison": {
            "source_hubs": list(clean_source_hubs),
            "source_hub_count": len(clean_source_hubs),
            "destination_name": destination_payload.get("name") or clean_destination_name,
            "successful_count": len(ranked_results),
            "failed_count": len(failed_results),
            "best": ranked_results[0] if ranked_results else {},
            "results": ranked_results + failed_results,
            "combined_candidate_count": len(combined_opportunities),
            "combined_deduped_candidate_count": len(combined_candidates),
            "combined_plan": {
                "available": bool(combined_portfolio.get("available")),
                "portfolio": combined_portfolio,
                "opportunities": combined_opportunity_rows,
                "report_rows": combined_report_rows,
                "manual_note": (
                    "Hub results are independent full-budget what-if scans. The combined plan uses the one shared "
                    "investment budget across the best source-hub candidates and does not save Trade P&L expectations."
                ),
            },
            "manual_note": (
                "Compare buy hubs with the same item scope, fee, margin, history mode, budget, and downstream demand. "
                "Verify every order in EVE before placing manual buy orders."
            ),
        },
    }


def build_flight_acquisition_payload(
    *,
    config: EveSsoConfig,
    session: FlightEsiSession,
    origin_name: str = "",
    destination_name: str = DEFAULT_HAUL_DESTINATION_SYSTEM,
    budget_isk: float = DEFAULT_ACQUISITION_BUDGET_ISK,
    pickup_jumps: int = DEFAULT_ACQUISITION_PICKUP_JUMPS,
    portfolio_jumps: int = DEFAULT_ACQUISITION_PORTFOLIO_JUMPS,
    min_margin_percent: float = DEFAULT_HAUL_MIN_DETOUR_MARGIN_PERCENT,
    broker_fee_percent: float = DEFAULT_ACQUISITION_BROKER_FEE_PERCENT,
    target_days: int = DEFAULT_ACQUISITION_TARGET_DAYS,
    order_duration_days: int = DEFAULT_ACQUISITION_ORDER_DURATION_DAYS,
    history_analysis_mode: str = DEFAULT_ACQUISITION_HISTORY_ANALYSIS_MODE,
    route_preference: str = DEFAULT_HAUL_ROUTE_PREFERENCE,
    include_common_materials: bool = True,
    market_group_ids: Iterable[int] = (),
    market_type_ids: Iterable[int] = (),
    market_type_names: Iterable[Any] = (),
    item_workers: int = DEFAULT_FLIGHT_ACQUISITION_ITEM_WORKERS,
    expectation_store: MarketStore | None = None,
    learning_store: MarketStore | None = None,
    progress: Callable[[str, dict[str, Any]], None] | None = None,
) -> dict[str, Any]:
    require_flight_scopes(session, (FLIGHT_LOCATION_SCOPE, FLIGHT_SKILLS_SCOPE))
    if progress is not None:
        progress("scan_start", {"message": "Preparing investment portfolio scan.", "percent": 1})
    location = fetch_flight_location(config, session)
    if progress is not None:
        progress("location", {"message": "Loaded current ESI location.", "percent": 5})
    current_solar_system_id = int(location.get("solar_system_id") or 0)
    route_cache = load_route_graph_cache()
    if not route_cache.available:
        raise CorpMarketError(route_cache.error or "Route graph cache is not available.")
    recipe_cache = load_industry_recipe_cache()
    if not recipe_cache.available:
        raise CorpMarketError(recipe_cache.error or "Recipe cache is not available.")
    systems = route_cache.systems or {}
    adjacency = route_cache.adjacency or {}
    clean_origin_name = str(origin_name or "").strip()
    if clean_origin_name:
        origin = resolve_route_system(route_cache, clean_origin_name)
        if origin is None:
            raise CorpMarketError(f"Starting system {clean_origin_name!r} was not found in the route graph cache.")
        origin_source = "manual"
    else:
        origin = systems.get(current_solar_system_id)
        origin_source = "esi-location"
    if origin is None:
        raise CorpMarketError(f"Current system {current_solar_system_id} is not in the route graph cache.")
    destination = resolve_route_system(route_cache, destination_name)
    if destination is None:
        raise CorpMarketError(f"Destination system {destination_name!r} was not found in the route graph cache.")
    route_plan = build_haul_route_plan(
        config=config,
        origin_solar_system_id=origin.solar_system_id,
        destination_solar_system_id=destination.solar_system_id,
        route_preference=route_preference,
        avoid_recent_pod_kills=False,
        adjacency=adjacency,
    )
    if progress is not None:
        progress(
            "route_step",
            {
                "message": (
                    f"Planned {route_plan['preference_label'].lower()} route from {origin.name} "
                    f"to {destination.name}."
                ),
                "percent": 8,
            },
        )
    skills = fetch_flight_skills(config, session)
    sales_tax = build_sales_tax_profile(skills)
    if progress is not None:
        progress("skills", {"message": "Loaded sales tax skill profile.", "percent": 10})
    acquisition = scan_market_acquisition_opportunities(
        config=config,
        recipe_cache=recipe_cache,
        route_cache=route_cache,
        origin=origin,
        destination=destination,
        budget_isk=budget_isk,
        pickup_jumps=pickup_jumps,
        portfolio_jumps=portfolio_jumps,
        min_margin_percent=min_margin_percent,
        broker_fee_percent=broker_fee_percent,
        target_days=target_days,
        history_analysis_mode=history_analysis_mode,
        sales_tax=sales_tax,
        include_common_materials=include_common_materials,
        market_group_ids=market_group_ids,
        market_type_ids=market_type_ids,
        market_type_names=market_type_names,
        item_workers=item_workers,
        progress=progress,
    )
    clean_order_duration_days = clamp_acquisition_order_duration_days(order_duration_days)
    acquisition["order_duration_days"] = clean_order_duration_days
    route_path = route_plan["path"]
    route_systems = [systems[system_id].to_dict(jumps=index) for index, system_id in enumerate(route_path) if system_id in systems]
    generated_at = now_iso()
    expectation_snapshot = {"saved": 0, "snapshot_id": ""}
    if expectation_store is not None:
        expectation_snapshot = expectation_store.save_acquisition_expectations(
            character_id=session.character_id,
            acquisition=acquisition,
            generated_at=generated_at,
        )
        if progress is not None:
            progress(
                "expectations",
                {
                    "message": f"Saved {expectation_snapshot.get('saved', 0)} local expectation row(s).",
                    "percent": 99,
                },
            )
    acquisition["expectation_snapshot"] = {
        **expectation_snapshot,
        "source": "local-corp-market-sqlite",
    }
    route_payload = {
        "origin": origin.to_dict(jumps=0),
        "destination": destination.to_dict(jumps=max(0, len(route_path) - 1)),
        "origin_query": clean_origin_name,
        "origin_source": origin_source,
        "destination_query": destination_name,
        "route_jumps": max(0, len(route_path) - 1),
        "route_preference": route_plan["preference"],
        "route_preference_label": route_plan["preference_label"],
        "route_source": route_plan["source"],
        "route_warning": route_plan["warning"],
        "systems": route_systems,
    }
    portfolio = acquisition.get("portfolio") if isinstance(acquisition.get("portfolio"), Mapping) else {}
    acquisition["learning"] = attach_local_trade_learning_signals(
        learning_store=learning_store or expectation_store,
        character_id=session.character_id,
        item_groups=(
            [item for item in acquisition.get("opportunities") or [] if isinstance(item, dict)],
            [item for item in portfolio.get("lines") or [] if isinstance(item, dict)],
        ),
    )
    acquisition["report_rows"] = build_acquisition_expected_realized_report_rows(
        generated_at=generated_at,
        route=route_payload,
        acquisition=acquisition,
    )
    data_sources = [
        workflow_source_badge(
            key="location-esi",
            label="Current location ESI",
            status="ready",
            posture="read-only ESI",
            freshness=generated_at,
            persistence="response summary only",
            scope=FLIGHT_LOCATION_SCOPE,
            detail="Used to anchor portfolio pickup range when no manual origin override is supplied.",
        ),
        workflow_source_badge(
            key="skills-esi",
            label="Skills ESI",
            status="ready",
            posture="read-only ESI",
            freshness=generated_at,
            persistence="response summary only",
            scope=FLIGHT_SKILLS_SCOPE,
            detail="Trade skills are summarized for tax and fee assumptions.",
        ),
        cache_source_badge(
            key="route-cache",
            label="Route graph cache",
            cache=route_cache,
            detail="Local route graph supports pickup range, jump budget, and route context.",
        ),
        cache_source_badge(
            key="recipe-cache",
            label="Recipe cache",
            cache=recipe_cache,
            detail="Local recipe/material cache supplies common material and type candidates.",
        ),
        market_cache_source_badge(
            key="market-order-cache",
            label="Public market orders",
            cache_status=acquisition.get("market_cache") or {},
            detail="Suggested bids and destination demand use public ESI market orders.",
        ),
        market_cache_source_badge(
            key="market-history-cache",
            label="Public market history",
            cache_status=acquisition.get("history_cache") or {},
            detail="History analysis labels traps, sparse volume, and target-day risk.",
        ),
        workflow_source_badge(
            key="manual-portfolio-settings",
            label="Manual portfolio settings",
            status="manual",
            posture="browser input",
            freshness="current form value",
            persistence="browser localStorage only",
            detail="Budget, target days, broker fee, filters, and pasted item scope are user-controlled.",
        ),
        sqlite_source_badge(
            enabled=bool(expectation_store or learning_store),
            detail="Saves acquisition expectations and reads local Trade P&L learning signals when the local market store is available.",
        ),
    ]
    acquisition["data_sources"] = data_sources
    acquisition["discord_handoff"] = acquisition_discord_handoff(route=route_payload, acquisition=acquisition)
    decision_snapshot = {"saved": 0, "snapshot_id": "", "source": "local-corp-market-sqlite"}
    if expectation_store is not None:
        portfolio_lines = [item for item in portfolio.get("lines") or [] if isinstance(item, Mapping)]
        opportunities = [item for item in acquisition.get("opportunities") or [] if isinstance(item, Mapping)]
        target_item = portfolio_lines[0] if portfolio_lines else (opportunities[0] if opportunities else {})
        target_type_id = clean_optional_int(target_item.get("type_id")) if isinstance(target_item, Mapping) else None
        source_keys = [str(source.get("key") or "") for source in data_sources if isinstance(source, Mapping)]
        comparison_summary = summarize_acquisition_payload_for_comparison(
            str(origin.name or clean_origin_name or "Current location"),
            {"route": route_payload, "acquisition": acquisition},
        )
        snapshot_result = expectation_store.save_decision_snapshot(
            character_id=session.character_id,
            workflow_key="acquisition",
            source_key="manual-portfolio-settings",
            title=f"Acquisition portfolio toward {destination.name}",
            goal="buy_order_portfolio",
            target_item_name=str(target_item.get("item_name") or "") if isinstance(target_item, Mapping) else "",
            target_type_id=target_type_id,
            expected_outcome={
                "budget_isk": float(budget_isk or 0.0),
                "target_days": int(target_days or 0),
                "order_duration_days": int(clean_order_duration_days or 0),
                "portfolio_available": bool(portfolio.get("available")),
                "portfolio_line_count": int(portfolio.get("line_count") or len(portfolio_lines)),
                "opportunity_count": int(acquisition.get("opportunity_count") or len(opportunities)),
                "invested_isk": float(portfolio.get("invested_isk") or 0.0),
                "estimated_net_profit": float(portfolio.get("estimated_net_profit") or 0.0),
                "estimated_margin_percent": portfolio.get("margin_percent"),
                "possible_trap_count": int(acquisition.get("possible_trap_count") or 0),
            },
            redacted_summary={
                **comparison_summary,
                "origin_source": origin_source,
                "history_analysis_mode": acquisition.get("history_analysis_mode"),
                "history_analysis_label": acquisition.get("history_analysis_label"),
                "data_source_keys": source_keys,
            },
            source_keys=source_keys,
            created_at=generated_at,
        )
        decision_snapshot = {
            "saved": int(snapshot_result.get("saved") or 0),
            "snapshot_id": str(snapshot_result.get("snapshot_id") or ""),
            "source": "local-corp-market-sqlite",
        }
    acquisition["decision_snapshot"] = decision_snapshot
    return {
        "ok": True,
        "generated_at": generated_at,
        "character": session.to_public_dict(),
        "data_sources": data_sources,
        "location": location,
        "route": route_payload,
        "acquisition": acquisition,
    }


def scan_buyers_for_owned_blueprints(
    *,
    config: EveSsoConfig,
    blueprints: Iterable[dict[str, Any]],
    recipe_cache: IndustryRecipeCache,
    route_cache: RouteGraphCache,
    current_solar_system_id: int,
    max_jumps: int,
    progress: Callable[[str, dict[str, Any]], None] | None = None,
) -> dict[str, Any]:
    systems = route_cache.systems or {}
    adjacency = route_cache.adjacency or {}
    max_jumps = clamp_flight_max_jumps(max_jumps)
    jump_distances = jump_distances_within(
        start_system_id=current_solar_system_id,
        max_jumps=max_jumps,
        adjacency=adjacency,
    )
    region_ids = sorted(
        {
            system.region_id
            for system_id, system in systems.items()
            if system_id in jump_distances and system.region_id is not None
        }
    )
    region_truncated = len(region_ids) > MAX_FLIGHT_BUYER_SCAN_REGIONS
    scan_region_ids = region_ids[:MAX_FLIGHT_BUYER_SCAN_REGIONS]

    product_targets = owned_blueprint_product_targets(blueprints=blueprints, recipes=recipe_cache.recipes or {})
    product_truncated = len(product_targets) > MAX_FLIGHT_BUYER_SCAN_PRODUCTS
    scan_targets = product_targets[:MAX_FLIGHT_BUYER_SCAN_PRODUCTS]
    region_count = len(scan_region_ids)
    product_count = len(scan_targets)
    total_steps = product_count * max(1, region_count)

    def progress_percent(completed_steps: int) -> int:
        if total_steps <= 0:
            return 100
        return max(10, min(99, round(10 + (completed_steps / total_steps) * 88)))

    if progress is not None:
        progress(
            "scan_scope",
            {
                "message": (
                    f"Scanning {product_count} blueprint products across {region_count} nearby market regions. "
                    f"{len(jump_distances)} systems are inside {max_jumps} jumps."
                ),
                "product_count": product_count,
                "region_count": region_count,
                "reachable_system_count": len(jump_distances),
                "total_steps": total_steps,
                "percent": 10 if total_steps else 100,
            },
        )

    products = []
    total_order_count = 0
    scan_errors = []
    for product_index, target in enumerate(scan_targets, start=1):
        product_orders = []
        if progress is not None:
            progress(
                "product_start",
                {
                    "message": f"Checking buyer orders for {target['product_name']} ({product_index}/{product_count}).",
                    "product_index": product_index,
                    "product_count": product_count,
                    "product_name": target["product_name"],
                    "percent": progress_percent((product_index - 1) * max(1, region_count)),
                },
            )
        for region_index, region_id in enumerate(scan_region_ids, start=1):
            completed_steps = ((product_index - 1) * max(1, region_count)) + region_index
            before_region_order_count = len(product_orders)
            try:
                raw_orders = fetch_market_buy_orders(config, region_id=region_id, type_id=target["product_type_id"])
            except CorpMarketError as exc:
                scan_errors.append(
                    {
                        "product_type_id": target["product_type_id"],
                        "product_name": target["product_name"],
                        "region_id": region_id,
                        "error": str(exc),
                    }
                )
                if progress is not None:
                    progress(
                        "scan_warning",
                        {
                            "message": (
                                f"{target['product_name']}: region {region_index}/{region_count} failed: {exc}"
                            ),
                            "product_index": product_index,
                            "product_count": product_count,
                            "product_name": target["product_name"],
                            "region_index": region_index,
                            "region_count": region_count,
                            "percent": progress_percent(completed_steps),
                        },
                    )
                continue
            for order in raw_orders:
                record = build_buyer_order_record(
                    order,
                    target=target,
                    systems=systems,
                    jump_distances=jump_distances,
                    region_id=region_id,
                )
                if record is not None:
                    product_orders.append(record)
            if progress is not None:
                nearby_order_count = len(product_orders) - before_region_order_count
                progress(
                    "orders",
                    {
                        "message": (
                            f"{target['product_name']}: region {region_index}/{region_count} returned "
                            f"{len(raw_orders)} buy orders; {nearby_order_count} are inside the jump range."
                        ),
                        "product_index": product_index,
                        "product_count": product_count,
                        "product_name": target["product_name"],
                        "region_index": region_index,
                        "region_count": region_count,
                        "raw_order_count": len(raw_orders),
                        "nearby_order_count": nearby_order_count,
                        "step": completed_steps,
                        "total_steps": total_steps,
                        "percent": progress_percent(completed_steps),
                    },
                )
        product_orders.sort(key=lambda item: (-float(item["price"]), int(item["jumps"]), -int(item["volume_remain"])))
        total_order_count += len(product_orders)
        if progress is not None:
            best_order = product_orders[0] if product_orders else None
            if best_order:
                message = (
                    f"{target['product_name']}: best nearby buyer is {best_order['system_name']} "
                    f"at {best_order['price']:.2f} ISK."
                )
            else:
                message = f"{target['product_name']}: no nearby buy orders found."
            progress(
                "product_done",
                {
                    "message": message,
                    "product_index": product_index,
                    "product_count": product_count,
                    "product_name": target["product_name"],
                    "order_count": len(product_orders),
                    "percent": progress_percent(product_index * max(1, region_count)),
                },
            )
        products.append(
            {
                **target,
                "order_count": len(product_orders),
                "best_order": product_orders[0] if product_orders else None,
                "top_orders": product_orders[:3],
            }
        )
    products.sort(
        key=lambda item: (
            0 if item["best_order"] else 1,
            item["product_name"],
        )
    )
    return {
        "max_jumps": max_jumps,
        "reachable_system_count": len(jump_distances),
        "regions_scanned": len(scan_region_ids),
        "total_regions_in_range": len(region_ids),
        "region_truncated": region_truncated,
        "scanned_products": len(scan_targets),
        "total_known_products": len(product_targets),
        "product_truncated": product_truncated,
        "order_count": total_order_count,
        "products_with_buyers": sum(1 for item in products if item["best_order"]),
        "products": products[:20],
        "errors": scan_errors[:10],
        "market_cache": market_order_cache_status(),
        "identity_note": (
            "ESI market orders do not expose buyer character names; these are public buy orders. "
            "Public market orders are cached locally for 5 minutes."
        ),
    }


def rank_profitability_for_owned_blueprints(
    *,
    config: EveSsoConfig,
    blueprints: Iterable[dict[str, Any]],
    assets: Iterable[dict[str, Any]],
    sales_tax: dict[str, Any],
    recipe_cache: IndustryRecipeCache,
    route_cache: RouteGraphCache,
    current_solar_system_id: int,
    max_jumps: int,
) -> dict[str, Any]:
    systems = route_cache.systems or {}
    adjacency = route_cache.adjacency or {}
    jump_distances = jump_distances_within(
        start_system_id=current_solar_system_id,
        max_jumps=clamp_flight_max_jumps(max_jumps),
        adjacency=adjacency,
    )
    region_ids = sorted(
        {
            system.region_id
            for system_id, system in systems.items()
            if system_id in jump_distances and system.region_id is not None
        }
    )
    region_truncated = len(region_ids) > MAX_FLIGHT_BUYER_SCAN_REGIONS
    scan_region_ids = region_ids[:MAX_FLIGHT_BUYER_SCAN_REGIONS]

    recipes = recipe_cache.recipes or {}
    product_targets = owned_blueprint_product_targets(blueprints=blueprints, recipes=recipes)
    product_truncated = len(product_targets) > MAX_FLIGHT_BUYER_SCAN_PRODUCTS
    scan_targets = product_targets[:MAX_FLIGHT_BUYER_SCAN_PRODUCTS]
    asset_quantities = quantity_by_type_id(item for item in assets if isinstance(item, dict))

    material_type_counts: dict[int, int] = {}
    for target in scan_targets:
        recipe = recipes.get(int(target["blueprint_type_id"]))
        if recipe is None:
            continue
        for material in recipe.materials:
            material_type_counts[material.type_id] = material_type_counts.get(material.type_id, 0) + 1
    material_type_ids = sorted(material_type_counts, key=lambda type_id: (-material_type_counts[type_id], type_id))
    material_truncated = len(material_type_ids) > MAX_FLIGHT_PROFIT_MATERIAL_TYPES
    scan_material_type_ids = material_type_ids[:MAX_FLIGHT_PROFIT_MATERIAL_TYPES]

    best_buyers, product_order_count, product_errors = scan_best_reachable_market_orders(
        config=config,
        type_ids=[int(target["product_type_id"]) for target in scan_targets],
        region_ids=scan_region_ids,
        systems=systems,
        jump_distances=jump_distances,
        order_type="buy",
    )
    best_material_sells, material_order_count, material_errors = scan_best_reachable_market_orders(
        config=config,
        type_ids=scan_material_type_ids,
        region_ids=scan_region_ids,
        systems=systems,
        jump_distances=jump_distances,
        order_type="sell",
    )
    jita_system = resolve_jita_market_system(systems)
    jita_material_buys, jita_material_order_count, jita_material_errors = scan_system_market_orders(
        config=config,
        type_ids=scan_material_type_ids,
        system=jita_system,
        order_type="buy",
    )

    products = []
    for target in scan_targets:
        if not target.get("blueprint_usable", True):
            continue
        recipe = recipes.get(int(target["blueprint_type_id"]))
        if recipe is None:
            continue
        buyer = best_buyers.get(int(target["product_type_id"]))
        revenue = float(buyer["price"]) * int(target["product_quantity"]) if buyer else None
        material_rows = []
        missing_materials = []
        priced_material_types = 0
        missing_priced_material_types = 0
        replacement_cost = 0.0
        missing_replacement_cost = 0.0
        jita_raw_partial_value = 0.0
        jita_raw_full_material_types = 0
        jita_raw_partial_material_types = 0
        recipe_materials = adjusted_recipe_materials(
            recipe,
            material_efficiency=int(target.get("blueprint_material_efficiency") or 0),
            runs=1,
        )
        for material in recipe_materials:
            material_type_id = int(material["type_id"])
            available = asset_quantities.get(material_type_id, 0)
            required = int(material["quantity"])
            missing = max(0, required - available)
            sell_order = best_material_sells.get(material_type_id)
            unit_price = float(sell_order["price"]) if sell_order else None
            material_replacement_cost = required * unit_price if unit_price is not None else None
            material_missing_cost = missing * unit_price if unit_price is not None else None
            jita_liquidation = liquidation_value_from_orders(
                jita_material_buys.get(material_type_id, ()),
                quantity=required,
            )
            if jita_liquidation["priced_quantity"] > 0:
                jita_raw_partial_value += float(jita_liquidation["value"])
                jita_raw_partial_material_types += 1
                if jita_liquidation["complete"]:
                    jita_raw_full_material_types += 1
            if unit_price is not None:
                priced_material_types += 1
                replacement_cost += material_replacement_cost or 0.0
                if missing > 0:
                    missing_priced_material_types += 1
                missing_replacement_cost += material_missing_cost or 0.0
            material_row = {
                "type_id": material_type_id,
                "name": material["name"],
                "base_required": material["base_quantity"],
                "required": required,
                "available": available,
                "missing": missing,
                "unit_sell_price": unit_price,
                "replacement_cost": material_replacement_cost,
                "missing_cost": material_missing_cost,
                "sell_order": sell_order,
                "jita_buy_price": (
                    float(jita_material_buys[material_type_id][0]["price"])
                    if jita_material_buys.get(material_type_id)
                    else None
                ),
                "jita_raw_value": jita_liquidation["value"] if jita_liquidation["priced_quantity"] > 0 else None,
                "jita_raw_priced_quantity": jita_liquidation["priced_quantity"],
                "jita_raw_required_quantity": jita_liquidation["required_quantity"],
                "jita_raw_complete": jita_liquidation["complete"],
                "jita_buy_order": jita_material_buys[material_type_id][0] if jita_material_buys.get(material_type_id) else None,
            }
            material_rows.append(material_row)
            if missing > 0:
                missing_materials.append(material_row)

        required_material_types = len(recipe_materials)
        missing_material_types = sum(1 for item in material_rows if int(item["missing"]) > 0)
        can_build = missing_material_types == 0
        all_material_prices_known = priced_material_types == required_material_types
        missing_prices_known = all(
            int(item["missing"]) <= 0 or item["unit_sell_price"] is not None
            for item in material_rows
        )
        jita_raw_value_known = jita_raw_full_material_types == required_material_types
        replacement_profit = revenue - replacement_cost if revenue is not None and all_material_prices_known else None
        cash_profit = revenue - missing_replacement_cost if revenue is not None and missing_prices_known else None
        sales_tax_rate = clean_optional_float(sales_tax.get("rate")) or 0.0
        sales_tax_amount = revenue * sales_tax_rate if revenue is not None else None
        broker_fee_amount = 0.0 if revenue is not None else None
        net_revenue = revenue - sales_tax_amount - broker_fee_amount if revenue is not None else None
        taxed_replacement_profit = (
            net_revenue - replacement_cost if net_revenue is not None and all_material_prices_known else None
        )
        taxed_cash_profit = net_revenue - missing_replacement_cost if net_revenue is not None and missing_prices_known else None
        base_time_seconds = int(target.get("manufacturing_time_seconds") or recipe.manufacturing_time_seconds or 0)
        adjusted_time_seconds = adjusted_job_time_seconds(
            base_time_seconds,
            int(target.get("blueprint_time_efficiency") or 0),
            runs=1,
        )
        decision = profitability_decision(
            has_buyer=buyer is not None,
            can_build=can_build,
            missing_material_types=missing_material_types,
            replacement_profit=taxed_replacement_profit,
            cash_profit=taxed_cash_profit,
            all_material_prices_known=all_material_prices_known,
            missing_prices_known=missing_prices_known,
        )
        products.append(
            {
                **target,
                "decision": decision,
                "best_buyer": buyer,
                "product_revenue": revenue,
                "sales_tax_rate": sales_tax_rate,
                "sales_tax": sales_tax_amount,
                "broker_fee": broker_fee_amount,
                "net_revenue": net_revenue,
                "replacement_cost": replacement_cost if all_material_prices_known else None,
                "missing_replacement_cost": missing_replacement_cost if missing_prices_known else None,
                "replacement_profit": replacement_profit,
                "cash_profit": cash_profit,
                "replacement_margin_percent": profit_margin_percent(replacement_profit, revenue),
                "cash_margin_percent": profit_margin_percent(cash_profit, revenue),
                "taxed_replacement_profit": taxed_replacement_profit,
                "taxed_cash_profit": taxed_cash_profit,
                "taxed_replacement_margin_percent": profit_margin_percent(taxed_replacement_profit, revenue),
                "taxed_cash_margin_percent": profit_margin_percent(taxed_cash_profit, revenue),
                "base_time_seconds": base_time_seconds,
                "adjusted_time_seconds": adjusted_time_seconds,
                "true_profit_per_hour": isk_per_hour(taxed_replacement_profit, adjusted_time_seconds),
                "wallet_gain_per_hour": isk_per_hour(taxed_cash_profit, adjusted_time_seconds),
                "max_production_limit": target.get("max_production_limit", 0),
                "required_skills": target.get("required_skills", []),
                "jita_raw_system_name": jita_system.name,
                "jita_raw_material_value": jita_raw_partial_value if jita_raw_value_known else None,
                "jita_partial_raw_material_value": jita_raw_partial_value if jita_raw_partial_material_types > 0 else None,
                "jita_raw_material_types": jita_raw_full_material_types,
                "jita_partial_raw_material_types": jita_raw_partial_material_types,
                "jita_raw_required_material_types": required_material_types,
                "profitable": taxed_replacement_profit is not None and taxed_replacement_profit > 0,
                "can_build_one_run": can_build,
                "required_material_types": required_material_types,
                "priced_material_types": priced_material_types,
                "missing_material_types": missing_material_types,
                "missing_priced_material_types": missing_priced_material_types,
                "materials": material_rows[:10],
                "missing_materials": sorted(missing_materials, key=lambda item: int(item["missing"]), reverse=True)[:5],
                "confidence": profitability_confidence(
                    has_buyer=buyer is not None,
                    can_build=can_build,
                    all_material_prices_known=all_material_prices_known,
                    missing_prices_known=missing_prices_known,
                ),
            }
        )

    products.sort(
        key=lambda item: (
            int((item.get("decision") or {}).get("rank") or 99),
            0 if item["best_buyer"] else 1,
            0 if item["taxed_replacement_profit"] is not None else 1,
            -profit_sort_value(item),
            0 if item["can_build_one_run"] else 1,
            item["product_name"],
        )
    )
    errors = product_errors + material_errors + jita_material_errors
    decision_counts: dict[str, int] = {}
    for item in products:
        decision_code = str((item.get("decision") or {}).get("code") or "unknown")
        decision_counts[decision_code] = decision_counts.get(decision_code, 0) + 1
    return {
        "max_jumps": clamp_flight_max_jumps(max_jumps),
        "reachable_system_count": len(jump_distances),
        "regions_scanned": len(scan_region_ids),
        "total_regions_in_range": len(region_ids),
        "region_truncated": region_truncated,
        "scanned_products": len(scan_targets),
        "total_known_products": len(product_targets),
        "product_truncated": product_truncated,
        "scanned_material_types": len(scan_material_type_ids),
        "total_material_types": len(material_type_ids),
        "material_truncated": material_truncated,
        "product_order_count": product_order_count,
        "material_order_count": material_order_count,
        "jita_material_order_count": jita_material_order_count,
        "jita_raw_system": jita_system.to_dict(jumps=0),
        "ranked_products": len(products),
        "products_with_buyers": sum(1 for item in products if item["best_buyer"]),
        "profitable_products": sum(1 for item in products if item["profitable"]),
        "buildable_now_products": sum(1 for item in products if item["can_build_one_run"]),
        "replacement_priced_products": sum(1 for item in products if item["replacement_profit"] is not None),
        "cash_priced_products": sum(1 for item in products if item["cash_profit"] is not None),
        "taxed_replacement_priced_products": sum(1 for item in products if item["taxed_replacement_profit"] is not None),
        "taxed_cash_priced_products": sum(1 for item in products if item["taxed_cash_profit"] is not None),
        "decision_counts": decision_counts,
        "products": products[:20],
        "errors": errors[:12],
        "sales_tax": sales_tax,
        "market_cache": market_order_cache_status(),
        "pricing_note": (
            "Visible profit subtracts sales tax from the buyer revenue using your Accounting skill. "
            "Details show the before-tax true profit, wallet gain, TE-adjusted profit per hour, and Jita raw material value. "
            "Public market orders are cached locally for 5 minutes; ESI market orders do not expose buyer character names."
        ),
    }


def scan_route_hauling_opportunities(
    *,
    config: EveSsoConfig,
    recipe_cache: IndustryRecipeCache,
    route_cache: RouteGraphCache,
    origin_solar_system_id: int,
    destination_solar_system_id: int,
    route_path: list[int],
    detour_jumps: int,
    cargo_capacity_m3: float,
    purchase_budget_isk: float,
    min_detour_margin_percent: float,
    sales_tax: dict[str, Any],
    include_common_materials: bool,
    market_group_ids: Iterable[int],
    market_type_ids: Iterable[int],
    market_type_names: Iterable[Any] = (),
    sort_by: str = DEFAULT_HAUL_SORT_BY,
    min_profit_per_m3: float = 0.0,
    min_profit_per_extra_jump: float = 0.0,
    progress: Callable[[str, dict[str, Any]], None] | None = None,
) -> dict[str, Any]:
    scan_timer = StageTimer()
    systems = route_cache.systems or {}
    adjacency = route_cache.adjacency or {}
    clean_detour_jumps = clamp_haul_detour_jumps(detour_jumps)
    clean_cargo_capacity_m3 = clamp_haul_cargo_m3(cargo_capacity_m3)
    clean_purchase_budget_isk = clamp_haul_purchase_budget_isk(purchase_budget_isk)
    clean_min_detour_margin_percent = clamp_haul_min_detour_margin_percent(min_detour_margin_percent)
    clean_sort_by = normalize_haul_sort_by(sort_by)
    clean_min_profit_per_m3 = clamp_haul_efficiency_floor_isk(min_profit_per_m3)
    clean_min_profit_per_extra_jump = clamp_haul_efficiency_floor_isk(min_profit_per_extra_jump)
    pickup_detours = route_corridor_systems(
        route_path=route_path,
        adjacency=adjacency,
        detour_jumps=clean_detour_jumps,
        destination_system_id=destination_solar_system_id,
    )
    route_jumps = max(0, len(route_path) - 1)
    origin_distances = jump_distances_from(
        start_system_id=origin_solar_system_id,
        adjacency=adjacency,
        max_jumps=route_jumps + clean_detour_jumps * 2,
    )
    destination_distances = jump_distances_from(
        start_system_id=destination_solar_system_id,
        adjacency=adjacency,
        max_jumps=route_jumps + clean_detour_jumps * 2,
    )
    pickup_jump_distances = {
        system_id: jumps
        for system_id, jumps in origin_distances.items()
        if system_id in pickup_detours and system_id in systems
    }
    pickup_region_ranks: dict[int, int] = {}
    for system_id, jumps in pickup_jump_distances.items():
        region_id = systems[system_id].region_id
        if region_id is None:
            continue
        current_rank = pickup_region_ranks.get(region_id)
        if current_rank is None or jumps < current_rank:
            pickup_region_ranks[region_id] = jumps
    pickup_region_ids = [
        region_id
        for region_id, _rank in sorted(pickup_region_ranks.items(), key=lambda item: (item[1], item[0]))
    ]
    pickup_region_truncated = len(pickup_region_ids) > MAX_FLIGHT_BUYER_SCAN_REGIONS
    scan_pickup_region_ids = pickup_region_ids[:MAX_FLIGHT_BUYER_SCAN_REGIONS]
    destination = systems.get(destination_solar_system_id)
    if destination is None or destination.region_id is None:
        raise CorpMarketError("Destination system does not have a usable market region in the route graph cache.")
    scan_timer.mark(
        "route_scope",
        "Build route corridor scope",
        pickup_systems=len(pickup_jump_distances),
        pickup_regions=len(scan_pickup_region_ids),
        route_jumps=route_jumps,
    )

    item_targets, item_scope = build_market_item_targets(
        config=config,
        recipe_cache=recipe_cache,
        include_common_materials=include_common_materials,
        market_group_ids=market_group_ids,
        market_type_ids=market_type_ids,
        market_type_names=market_type_names,
    )
    item_truncated = len(item_targets) > MAX_FLIGHT_HAUL_SCAN_TYPES
    scan_targets = item_targets[:MAX_FLIGHT_HAUL_SCAN_TYPES]
    if not scan_targets:
        unresolved_pasted_names = item_scope.get("unresolved_pasted_market_type_names") or []
        if unresolved_pasted_names:
            preview = ", ".join(str(name) for name in unresolved_pasted_names[:5])
            extra = "..." if len(unresolved_pasted_names) > 5 else ""
            raise CorpMarketError(f"No pasted item names matched the static market cache: {preview}{extra}.")
        raise CorpMarketError("Choose Common materials, a market category, or at least one exact item before scanning hauler routes.")
    scan_timer.mark(
        "item_targets",
        "Resolve item scan targets",
        scanned_item_types=len(scan_targets),
        total_item_types=len(item_targets),
        pasted_item_names=item_scope.get("pasted_market_type_count"),
        resolved_pasted_item_names=item_scope.get("resolved_pasted_market_type_count"),
        unresolved_pasted_item_names=len(item_scope.get("unresolved_pasted_market_type_names") or []),
    )
    sales_tax_rate = clean_optional_float(sales_tax.get("rate")) or 0.0

    opportunities = []
    total_sell_order_count = 0
    total_buy_order_count = 0
    raw_destination_buy_order_count = 0
    unreachable_destination_buy_order_count = 0
    history_regions = set()
    trap_signal_count = 0
    caution_signal_count = 0
    detour_margin_rejected_count = 0
    no_destination_buy_order_count = 0
    no_pickup_sell_order_count = 0
    destination_demand_gated_count = 0
    errors = []
    history_candidates: list[dict[str, Any]] = []
    emit_haul_route_progress(
        progress=progress,
        route_path=route_path,
        pickup_detours=pickup_detours,
        systems=systems,
        adjacency=adjacency,
        detour_jumps=clean_detour_jumps,
        destination_system_id=destination_solar_system_id,
        pickup_jump_distances=pickup_jump_distances,
        scanned_materials=len(scan_targets),
        min_detour_margin_percent=clean_min_detour_margin_percent,
    )
    if progress is not None:
        progress(
            "orders",
            {
                "scanned_materials": len(scan_targets),
                "message": f"Fetching destination buy orders for {len(scan_targets)} item types.",
            },
        )
    raw_destination_buys_by_type, batch_errors = fetch_haul_destination_buy_batch(
        config=config,
        targets=scan_targets,
        destination_region_id=destination.region_id,
    )
    raw_destination_buy_order_count = sum(len(orders) for orders in raw_destination_buys_by_type.values())
    errors.extend(batch_errors)
    scan_timer.mark(
        "destination_buy_fetch",
        "Fetch destination buy orders",
        item_types=len(scan_targets),
        batch_errors=len(batch_errors),
    )
    buy_orders_by_type: dict[int, list[dict[str, Any]]] = {}
    destination_demand_type_ids: list[int] = []
    no_destination_buy_order_names: list[str] = []
    for target in scan_targets:
        type_id = int(target["type_id"])
        buy_orders = []
        raw_buy_order_count = len(raw_destination_buys_by_type.get(type_id, []))
        for order in raw_destination_buys_by_type.get(type_id, []):
            record = build_reachable_market_order_record(
                order,
                systems=systems,
                jump_distances={destination_solar_system_id: route_jumps},
                region_id=destination.region_id,
                order_type="buy",
            )
            if record is not None:
                buy_orders.append(record)
        buy_orders.sort(key=lambda item: market_order_sort_key(item, order_type="buy"))
        total_buy_order_count += len(buy_orders)
        buy_orders_by_type[type_id] = buy_orders
        if buy_orders:
            destination_demand_type_ids.append(type_id)
        else:
            no_destination_buy_order_names.append(str(target["name"]))
            unreachable_destination_buy_order_count += raw_buy_order_count
    scan_timer.mark(
        "destination_buy_filter",
        "Filter reachable destination buy orders",
        raw_buy_orders=raw_destination_buy_order_count,
        buy_orders=total_buy_order_count,
        unreachable_buy_orders=unreachable_destination_buy_order_count,
        destination_demand_item_types=len(destination_demand_type_ids),
        no_destination_buy_item_types=len(scan_targets) - len(destination_demand_type_ids),
    )
    if progress is not None:
        if no_destination_buy_order_names:
            if len(no_destination_buy_order_names) == len(scan_targets):
                demand_message = (
                    f"No destination buy demand was reachable for any of the {len(scan_targets)} scanned item types. "
                    f"Skipped pickup sell-order lookups for speed."
                )
            else:
                preview = ", ".join(no_destination_buy_order_names[:5])
                extra = "..." if len(no_destination_buy_order_names) > 5 else ""
                demand_message = (
                    f"Skipped pickup sell-order lookups for {len(no_destination_buy_order_names)} item types "
                    f"with no reachable destination buy demand: {preview}{extra}."
                )
            progress(
                "orders",
                {
                    "scanned_materials": len(scan_targets),
                    "destination_demand_item_types": len(destination_demand_type_ids),
                    "no_destination_buy_order_count": len(no_destination_buy_order_names),
                    "raw_destination_buy_orders": raw_destination_buy_order_count,
                    "reachable_destination_buy_orders": total_buy_order_count,
                    "unreachable_destination_buy_orders": unreachable_destination_buy_order_count,
                    "message": demand_message,
                },
            )
        progress(
            "orders",
            {
                "scanned_materials": len(scan_targets),
                "destination_demand_item_types": len(destination_demand_type_ids),
                "pickup_region_count": len(scan_pickup_region_ids),
                "message": (
                    f"Fetching pickup sell orders for {len(destination_demand_type_ids)} item types "
                    f"across {len(scan_pickup_region_ids)} pickup regions."
                ),
            },
        )
    pickup_sells_by_type_region, batch_errors = fetch_haul_pickup_sell_batch(
        config=config,
        type_ids=destination_demand_type_ids,
        pickup_region_ids=scan_pickup_region_ids,
    )
    errors.extend(batch_errors)
    scan_timer.mark(
        "pickup_sell_fetch",
        "Fetch pickup sell orders",
        item_types=len(destination_demand_type_ids),
        pickup_regions=len(scan_pickup_region_ids),
        batch_errors=len(batch_errors),
    )
    for target_index, target in enumerate(scan_targets, start=1):
        type_id = int(target["type_id"])
        if progress is not None:
            progress(
                "orders",
                {
                    "type_id": type_id,
                    "item_name": target["name"],
                    "material_index": target_index,
                    "scanned_materials": len(scan_targets),
                    "message": f"Pricing {target['name']}",
                },
            )
        buy_orders = buy_orders_by_type.get(type_id, [])
        if not buy_orders:
            no_destination_buy_order_count += 1
            destination_demand_gated_count += max(0, len(scan_pickup_region_ids))
            continue

        sell_orders = []
        for region_id in scan_pickup_region_ids:
            raw_orders = pickup_sells_by_type_region.get((type_id, int(region_id)), [])
            for order in raw_orders:
                record = build_reachable_market_order_record(
                    order,
                    systems=systems,
                    jump_distances=pickup_jump_distances,
                    region_id=region_id,
                    order_type="sell",
                )
                if record is not None:
                    sell_orders.append(record)
        sell_orders.sort(key=lambda item: market_order_sort_key(item, order_type="sell"))
        total_sell_order_count += len(sell_orders)
        if not sell_orders:
            no_pickup_sell_order_count += 1
            continue
        volume_m3 = target.get("volume_m3")
        depth_match = match_haul_order_depth(
            sell_orders=sell_orders,
            buy_orders=buy_orders,
            cargo_capacity_m3=clean_cargo_capacity_m3,
            purchase_budget_isk=clean_purchase_budget_isk,
            volume_m3=clean_optional_float(volume_m3),
            sales_tax_rate=sales_tax_rate,
        )
        if depth_match is None:
            continue
        sell_order = depth_match["pickup_order"]
        buy_order = depth_match["destination_order"]
        total_net_profit = float(depth_match["net_profit"])
        if total_net_profit <= 0:
            continue
        pickup_system_id = int(sell_order["system_id"])
        origin_to_pickup = origin_distances.get(pickup_system_id)
        pickup_to_destination = destination_distances.get(pickup_system_id)
        matched_pickup_system_ids = [
            int(system.get("system_id") or 0)
            for system in depth_match.get("matched_pickup_systems", [])
            if int(system.get("system_id") or 0) > 0
        ]
        matched_pickup_route_jumps = shortest_route_jumps_via_systems(
            start_system_id=origin_solar_system_id,
            destination_system_id=destination_solar_system_id,
            pickup_system_ids=matched_pickup_system_ids,
            adjacency=adjacency,
        )
        extra_route_jumps = None
        if matched_pickup_route_jumps is not None:
            extra_route_jumps = max(0, matched_pickup_route_jumps - route_jumps)
        margin_percent = profit_margin_percent(
            float(depth_match["net_profit_per_unit"]),
            float(depth_match["average_pickup_price"]),
        )
        matched_pickup_detours = [
            pickup_detours.get(int(system.get("system_id") or 0), 0)
            for system in depth_match.get("matched_pickup_systems", [])
        ]
        pickup_detour_jumps = max(matched_pickup_detours or [pickup_detours.get(pickup_system_id, 0)])
        primary_pickup_detour_jumps = pickup_detours.get(pickup_system_id, 0)
        if pickup_detour_jumps > 0 and (margin_percent is None or margin_percent < clean_min_detour_margin_percent):
            detour_margin_rejected_count += 1
            continue
        matched_volume_m3 = None
        net_profit_per_m3 = None
        clean_volume_m3 = clean_optional_float(volume_m3)
        if clean_volume_m3 is not None and clean_volume_m3 > 0:
            matched_volume_m3 = clean_volume_m3 * int(depth_match["units"])
            if matched_volume_m3 > 0:
                net_profit_per_m3 = total_net_profit / matched_volume_m3
        net_profit_per_extra_jump = None
        if extra_route_jumps is not None:
            net_profit_per_extra_jump = total_net_profit / max(1, int(extra_route_jumps))
        matched_pickup_region_ids = sorted(
            {
                int(system.region_id)
                for matched_system in depth_match.get("matched_pickup_systems", [])
                for system_id in [int(matched_system.get("system_id") or 0)]
                for system in [systems.get(system_id)]
                if system is not None and system.region_id is not None
            }
        )
        history_candidates.append(
            {
                "type_id": type_id,
                "item_name": target["name"],
                "recipe_count": int(target.get("recipe_count") or 0),
                "source_labels": target.get("source_labels", []),
                "volume_m3": volume_m3,
                "units": int(depth_match["units"]),
                "cargo_limited": bool(depth_match["cargo_limited"]),
                "cargo_capacity_m3": clean_cargo_capacity_m3,
                "budget_limited": bool(depth_match["budget_limited"]),
                "purchase_budget_isk": clean_purchase_budget_isk,
                "budget_remaining_isk": round_optional_float(depth_match["budget_remaining_isk"]),
                "average_pickup_price": depth_match["average_pickup_price"],
                "average_destination_price": depth_match["average_destination_price"],
                "average_net_destination_price": depth_match["average_net_destination_price"],
                "gross_spread_per_unit": depth_match["gross_spread_per_unit"],
                "net_profit_per_unit": depth_match["net_profit_per_unit"],
                "net_profit": round_optional_float(total_net_profit),
                "net_profit_per_m3": round_optional_float(net_profit_per_m3),
                "net_profit_per_extra_jump": round_optional_float(net_profit_per_extra_jump),
                "matched_volume_m3": round_optional_float(matched_volume_m3),
                "pickup_cost": depth_match["pickup_cost"],
                "gross_destination_revenue": depth_match["gross_destination_revenue"],
                "net_destination_revenue": depth_match["net_destination_revenue"],
                "sales_tax_total": depth_match["sales_tax_total"],
                "margin_percent": margin_percent,
                "sales_tax_rate": sales_tax_rate,
                "pickup_order": sell_order,
                "destination_order": buy_order,
                "pickup_detour_jumps": pickup_detour_jumps,
                "primary_pickup_detour_jumps": primary_pickup_detour_jumps,
                "origin_to_pickup_jumps": origin_to_pickup,
                "pickup_to_destination_jumps": pickup_to_destination,
                "matched_pickup_route_jumps": matched_pickup_route_jumps,
                "extra_route_jumps": extra_route_jumps,
                "matched_sell_order_count": depth_match["matched_sell_order_count"],
                "matched_buy_order_count": depth_match["matched_buy_order_count"],
                "matched_order_pair_count": depth_match["matched_order_pair_count"],
                "matched_pickup_system_count": depth_match["matched_pickup_system_count"],
                "matched_pickup_systems": depth_match["matched_pickup_systems"],
                "order_depth": depth_match["order_depth"],
                "load_plan_depth": depth_match["load_plan_depth"],
                "order_depth_truncated": depth_match["order_depth_truncated"],
                "matched_pickup_region_ids": matched_pickup_region_ids,
            }
        )

    scan_timer.mark(
        "order_matching",
        "Match order depth and candidate profitability",
        sell_orders=total_sell_order_count,
        profitable_candidates=len(history_candidates),
        no_pickup_sell_item_types=no_pickup_sell_order_count,
        detour_rejected=detour_margin_rejected_count,
    )
    history_requests = []
    for candidate in history_candidates:
        type_id = int(candidate["type_id"])
        history_requests.append((type_id, int(destination.region_id)))
        for region_id in candidate.get("matched_pickup_region_ids", []):
            history_requests.append((type_id, int(region_id)))
    if progress is not None and history_candidates:
        progress(
            "orders",
            {
                "history_candidate_count": len(history_candidates),
                "history_request_count": len(set(history_requests)),
                "message": f"Checking market history for {len(history_candidates)} profitable haul candidates.",
            },
        )
    history_by_type_region, batch_errors = fetch_haul_history_batch(config=config, requests=history_requests)
    errors.extend(batch_errors)
    scan_timer.mark(
        "market_history_fetch",
        "Fetch market history for profitable candidates",
        profitable_candidates=len(history_candidates),
        history_requests=len(set(history_requests)),
        batch_errors=len(batch_errors),
    )
    for candidate_index, candidate in enumerate(history_candidates, start=1):
        type_id = int(candidate["type_id"])
        if progress is not None:
            progress(
                "orders",
                {
                    "type_id": type_id,
                    "item_name": candidate["item_name"],
                    "history_candidate_index": candidate_index,
                    "history_candidate_count": len(history_candidates),
                    "message": f"Scoring market history for {candidate['item_name']}",
                },
            )
        pickup_history_rows = []
        for region_id in candidate.get("matched_pickup_region_ids", []):
            history_key = (type_id, int(region_id))
            if history_key in history_by_type_region:
                pickup_history_rows.append(history_by_type_region[history_key])
                history_regions.add(int(region_id))
        destination_history_key = (type_id, int(destination.region_id))
        destination_history_rows = history_by_type_region.get(destination_history_key, [])
        if destination_history_key in history_by_type_region:
            history_regions.add(int(destination.region_id))
        pickup_history = market_history_stats(combine_market_history_rows(pickup_history_rows))
        destination_history = market_history_stats(destination_history_rows)
        history_flags = hauling_history_flags(
            pickup_stats=pickup_history,
            destination_stats=destination_history,
            average_pickup_price=float(candidate["average_pickup_price"]),
            average_destination_price=float(candidate["average_destination_price"]),
            units=int(candidate["units"]),
        )
        risk_level = acquisition_risk_level(history_flags)
        if risk_level == "possible-trap":
            trap_signal_count += 1
        elif risk_level == "caution":
            caution_signal_count += 1
        opportunities.append(
            {
                **candidate,
                "decision": hauling_decision(risk_level=risk_level, margin_percent=candidate["margin_percent"]),
                "risk_level": risk_level,
                "history_flags": history_flags,
                "pickup_history": pickup_history,
                "destination_history": destination_history,
            }
        )

    scan_timer.mark(
        "history_scoring",
        "Score history risk labels",
        scored_opportunities=len(opportunities),
        possible_traps=trap_signal_count,
        cautions=caution_signal_count,
    )
    total_profitable_opportunities = len(opportunities)
    opportunities, efficiency_filter_rejected_count = filter_and_sort_haul_opportunities(
        opportunities=opportunities,
        sort_by=clean_sort_by,
        min_profit_per_m3=clean_min_profit_per_m3,
        min_profit_per_extra_jump=clean_min_profit_per_extra_jump,
    )
    load_plan = build_haul_load_plan(
        opportunities=opportunities,
        cargo_capacity_m3=clean_cargo_capacity_m3,
        purchase_budget_isk=clean_purchase_budget_isk,
    )
    visible_opportunities = [
        {key: value for key, value in opportunity.items() if key != "load_plan_depth"}
        for opportunity in opportunities[:MAX_FLIGHT_HAUL_OPPORTUNITIES]
    ]
    scan_timer.mark(
        "ranking_load_plan",
        "Rank results and build load plan",
        visible_opportunities=len(visible_opportunities),
        filtered_opportunities=len(opportunities),
        load_plan_available=load_plan.get("available"),
    )
    stage_timing = scan_timer.to_public_dict()
    return {
        "route_jumps": route_jumps,
        "detour_jumps": clean_detour_jumps,
        "cargo_capacity_m3": clean_cargo_capacity_m3,
        "purchase_budget_isk": clean_purchase_budget_isk,
        "min_detour_margin_percent": clean_min_detour_margin_percent,
        "sort_by": clean_sort_by,
        "sort_label": haul_sort_label(clean_sort_by),
        "min_profit_per_m3": clean_min_profit_per_m3,
        "min_profit_per_extra_jump": clean_min_profit_per_extra_jump,
        "pickup_system_count": len(pickup_jump_distances),
        "pickup_regions_scanned": len(scan_pickup_region_ids),
        "pickup_regions_total": len(pickup_region_ids),
        "pickup_region_truncated": pickup_region_truncated,
        "destination_region_id": destination.region_id,
        "scanned_materials": len(scan_targets),
        "total_materials": len(item_targets),
        "material_truncated": item_truncated,
        "scanned_item_types": len(scan_targets),
        "total_item_types": len(item_targets),
        "item_truncated": item_truncated,
        "item_scope": {
            **item_scope,
            "scanned_item_types": len(scan_targets),
            "total_item_types": len(item_targets),
            "item_truncated": item_truncated,
        },
        "sell_order_count": total_sell_order_count,
        "buy_order_count": total_buy_order_count,
        "raw_destination_buy_order_count": raw_destination_buy_order_count,
        "unreachable_destination_buy_order_count": unreachable_destination_buy_order_count,
        "history_region_count": len(history_regions),
        "possible_trap_count": trap_signal_count,
        "caution_count": caution_signal_count,
        "detour_margin_rejected_count": detour_margin_rejected_count,
        "no_destination_buy_order_count": no_destination_buy_order_count,
        "no_destination_buy_order_names": no_destination_buy_order_names[:12],
        "no_pickup_sell_order_count": no_pickup_sell_order_count,
        "destination_demand_gated_count": destination_demand_gated_count,
        "efficiency_filter_rejected_count": efficiency_filter_rejected_count,
        "total_profitable_opportunities": total_profitable_opportunities,
        "profitable_opportunities": len(opportunities),
        "load_plan": load_plan,
        "opportunities": visible_opportunities,
        "stage_timing": stage_timing,
        "errors": errors[:12],
        "sales_tax": sales_tax,
        "market_cache": market_order_cache_status(),
        "history_cache": market_history_cache_status(),
        "pricing_note": (
            "This scan checks destination buy demand first, skips pickup regions when no reachable destination buy order exists, "
            "then walks public sell-order depth along the route corridor against public buy-order depth in the "
            "destination system until the profitable depth, cargo capacity, or purchase budget runs out. It then checks public market "
            "history for the matched pickup and destination regions so price spikes, thin volume, and sparse order "
            "activity are labeled before you undock. Profit is after sales tax for selling into destination buy "
            "orders. Public market orders are cached locally for 5 minutes. The page does not place orders or verify "
            "station docking access."
        ),
    }


def filter_and_sort_haul_opportunities(
    *,
    opportunities: Iterable[dict[str, Any]],
    sort_by: str,
    min_profit_per_m3: float,
    min_profit_per_extra_jump: float,
) -> tuple[list[dict[str, Any]], int]:
    clean_sort_by = normalize_haul_sort_by(sort_by)
    clean_min_profit_per_m3 = clamp_haul_efficiency_floor_isk(min_profit_per_m3)
    clean_min_profit_per_extra_jump = clamp_haul_efficiency_floor_isk(min_profit_per_extra_jump)
    filtered = []
    rejected_count = 0
    for opportunity in opportunities:
        if clean_min_profit_per_m3 > 0:
            profit_per_m3 = clean_optional_float(opportunity.get("net_profit_per_m3"))
            if profit_per_m3 is None or profit_per_m3 < clean_min_profit_per_m3:
                rejected_count += 1
                continue
        if clean_min_profit_per_extra_jump > 0:
            profit_per_extra_jump = clean_optional_float(opportunity.get("net_profit_per_extra_jump"))
            if profit_per_extra_jump is None or profit_per_extra_jump < clean_min_profit_per_extra_jump:
                rejected_count += 1
                continue
        filtered.append(opportunity)
    filtered.sort(key=lambda item: haul_opportunity_sort_key(item, clean_sort_by))
    return filtered, rejected_count


def haul_opportunity_sort_key(item: dict[str, Any], sort_by: str) -> tuple[Any, ...]:
    risk_rank = acquisition_risk_sort_rank(str(item.get("risk_level") or ""))
    name = str(item.get("item_name") or "")
    total_profit = clean_optional_float(item.get("net_profit")) or 0.0
    per_unit = clean_optional_float(item.get("net_profit_per_unit")) or 0.0
    margin_percent = clean_optional_float(item.get("margin_percent"))
    profit_per_m3 = clean_optional_float(item.get("net_profit_per_m3"))
    profit_per_extra_jump = clean_optional_float(item.get("net_profit_per_extra_jump"))
    try:
        extra_route_jumps = int(item.get("extra_route_jumps"))
    except (TypeError, ValueError):
        extra_route_jumps = None
    if extra_route_jumps is not None and extra_route_jumps < 0:
        extra_route_jumps = None
    extra_jump_rank = extra_route_jumps if extra_route_jumps is not None else 99
    direct_route_rank = 0 if extra_route_jumps == 0 else 1

    def desc_optional(value: float | None) -> float:
        return -value if value is not None else float("inf")

    if normalize_haul_sort_by(sort_by) == "profit_per_m3":
        return (risk_rank, desc_optional(profit_per_m3), -total_profit, extra_jump_rank, name)
    if normalize_haul_sort_by(sort_by) == "profit_per_extra_jump":
        return (risk_rank, direct_route_rank, desc_optional(profit_per_extra_jump), extra_jump_rank, -total_profit, name)
    if normalize_haul_sort_by(sort_by) == "margin":
        return (risk_rank, desc_optional(margin_percent), -total_profit, extra_jump_rank, name)
    return (risk_rank, -total_profit, extra_jump_rank, desc_optional(profit_per_m3), -per_unit, name)


def build_haul_load_plan(
    *,
    opportunities: Iterable[dict[str, Any]],
    cargo_capacity_m3: float,
    purchase_budget_isk: float,
) -> dict[str, Any]:
    clean_cargo_capacity_m3 = clamp_haul_cargo_m3(cargo_capacity_m3)
    clean_purchase_budget_isk = clamp_haul_purchase_budget_isk(purchase_budget_isk)
    remaining_cargo_m3 = clean_cargo_capacity_m3
    remaining_budget_isk = clean_purchase_budget_isk
    lines: list[dict[str, Any]] = []
    stop_map: dict[int, dict[str, Any]] = {}
    skipped_possible_trap_count = 0
    skipped_unknown_volume_count = 0
    skipped_low_profit_count = 0
    source_depth_truncated = False

    for opportunity in opportunities:
        if len(lines) >= MAX_HAUL_LOAD_PLAN_LINES:
            break
        if str(opportunity.get("risk_level") or "") == "possible-trap":
            skipped_possible_trap_count += 1
            continue
        unit_volume_m3 = clean_optional_float(opportunity.get("volume_m3"))
        if unit_volume_m3 is None or unit_volume_m3 <= 0:
            skipped_unknown_volume_count += 1
            continue
        if remaining_cargo_m3 + 1e-9 < unit_volume_m3 or remaining_budget_isk <= 0:
            break

        line_units = 0
        line_volume_m3 = 0.0
        line_pickup_cost = 0.0
        line_gross_destination_revenue = 0.0
        line_net_destination_revenue = 0.0
        line_sales_tax_total = 0.0
        line_net_profit = 0.0
        line_system_ids: set[int] = set()
        depth_rows = opportunity.get("load_plan_depth") or opportunity.get("order_depth") or []
        source_depth_truncated = source_depth_truncated or bool(opportunity.get("order_depth_truncated"))

        for depth_row in depth_rows:
            pickup_price = clean_optional_float(depth_row.get("pickup_price"))
            destination_price = clean_optional_float(depth_row.get("destination_price"))
            net_destination_price = clean_optional_float(depth_row.get("net_destination_price"))
            available_units = int(depth_row.get("units") or 0)
            if (
                pickup_price is None
                or destination_price is None
                or net_destination_price is None
                or pickup_price <= 0
                or available_units <= 0
            ):
                continue
            cargo_units = int((remaining_cargo_m3 + 1e-9) / unit_volume_m3)
            budget_units = int((remaining_budget_isk + 1e-9) // pickup_price)
            plan_units = min(available_units, cargo_units, budget_units)
            if plan_units <= 0:
                break
            pickup_order = depth_row.get("pickup_order") or {}
            system_id = int(pickup_order.get("system_id") or 0)
            system_name = str(pickup_order.get("system_name") or f"System {system_id}")
            jumps = pickup_order.get("jumps")
            row_pickup_cost = pickup_price * plan_units
            row_gross_destination_revenue = destination_price * plan_units
            row_net_destination_revenue = net_destination_price * plan_units
            row_sales_tax_total = row_gross_destination_revenue - row_net_destination_revenue
            row_net_profit = row_net_destination_revenue - row_pickup_cost
            row_volume_m3 = unit_volume_m3 * plan_units

            line_units += plan_units
            line_volume_m3 += row_volume_m3
            line_pickup_cost += row_pickup_cost
            line_gross_destination_revenue += row_gross_destination_revenue
            line_net_destination_revenue += row_net_destination_revenue
            line_sales_tax_total += row_sales_tax_total
            line_net_profit += row_net_profit
            line_system_ids.add(system_id)
            remaining_cargo_m3 = max(0.0, remaining_cargo_m3 - row_volume_m3)
            remaining_budget_isk = max(0.0, remaining_budget_isk - row_pickup_cost)

            stop = stop_map.setdefault(
                system_id,
                {
                    "system_id": system_id,
                    "system_name": system_name,
                    "jumps": jumps,
                    "units": 0,
                    "item_count": 0,
                    "pickup_cost": 0.0,
                    "volume_m3": 0.0,
                    "items": {},
                },
            )
            stop_items = stop["items"]
            item_key = str(opportunity.get("type_id") or opportunity.get("item_name") or "")
            if item_key not in stop_items:
                stop_items[item_key] = {
                    "type_id": opportunity.get("type_id"),
                    "item_name": opportunity.get("item_name"),
                    "units": 0,
                    "pickup_cost": 0.0,
                    "volume_m3": 0.0,
                }
            stop_item = stop_items[item_key]
            stop_item["units"] = int(stop_item["units"]) + plan_units
            stop_item["pickup_cost"] = float(stop_item["pickup_cost"]) + row_pickup_cost
            stop_item["volume_m3"] = float(stop_item["volume_m3"]) + row_volume_m3
            stop["units"] = int(stop["units"]) + plan_units
            stop["pickup_cost"] = float(stop["pickup_cost"]) + row_pickup_cost
            stop["volume_m3"] = float(stop["volume_m3"]) + row_volume_m3
            stop["item_count"] = len(stop_items)

            if remaining_cargo_m3 + 1e-9 < unit_volume_m3 or remaining_budget_isk <= 0:
                break

        if line_units <= 0:
            continue
        if line_net_profit <= 0:
            skipped_low_profit_count += 1
            continue
        lines.append(
            {
                "type_id": opportunity.get("type_id"),
                "item_name": opportunity.get("item_name"),
                "units": line_units,
                "unit_volume_m3": round_optional_float(unit_volume_m3),
                "volume_m3": round_optional_float(line_volume_m3),
                "pickup_cost": round_optional_float(line_pickup_cost),
                "gross_destination_revenue": round_optional_float(line_gross_destination_revenue),
                "net_destination_revenue": round_optional_float(line_net_destination_revenue),
                "sales_tax_total": round_optional_float(line_sales_tax_total),
                "net_profit": round_optional_float(line_net_profit),
                "average_pickup_price": round_optional_float(line_pickup_cost / line_units),
                "average_destination_price": round_optional_float(line_gross_destination_revenue / line_units),
                "net_profit_per_unit": round_optional_float(line_net_profit / line_units),
                "net_profit_per_m3": round_optional_float(line_net_profit / line_volume_m3) if line_volume_m3 > 0 else None,
                "pickup_system_count": len(line_system_ids),
                "risk_level": opportunity.get("risk_level"),
                "extra_route_jumps": opportunity.get("extra_route_jumps"),
            }
        )

    stops = []
    for stop in stop_map.values():
        stop_items = [
            {
                **item,
                "pickup_cost": round_optional_float(item.get("pickup_cost")) or 0.0,
                "volume_m3": round_optional_float(item.get("volume_m3")) or 0.0,
            }
            for item in sorted(
                stop["items"].values(),
                key=lambda item: (str(item.get("item_name") or ""), int(item.get("type_id") or 0)),
            )
        ]
        stops.append(
            {
                **{key: value for key, value in stop.items() if key != "items"},
                "pickup_cost": round_optional_float(stop.get("pickup_cost")) or 0.0,
                "volume_m3": round_optional_float(stop.get("volume_m3")) or 0.0,
                "items": stop_items,
            }
        )
    stops.sort(key=lambda item: (int(item.get("jumps") if item.get("jumps") is not None else 999), str(item["system_name"])))

    used_cargo_m3 = clean_cargo_capacity_m3 - remaining_cargo_m3
    used_budget_isk = clean_purchase_budget_isk - remaining_budget_isk
    total_net_profit = sum(float(line["net_profit"]) for line in lines)
    total_units = sum(int(line["units"]) for line in lines)
    return {
        "available": bool(lines),
        "strategy": "Best ranked clear/caution opportunities with known volume",
        "manual_note": "Verify live orders, docking access, and the route in EVE before buying. This page does not place orders.",
        "line_count": len(lines),
        "stop_count": len(stops),
        "item_count": len({line.get("type_id") for line in lines}),
        "units": total_units,
        "cargo_capacity_m3": round_optional_float(clean_cargo_capacity_m3),
        "used_cargo_m3": round_optional_float(used_cargo_m3),
        "cargo_remaining_m3": round_optional_float(remaining_cargo_m3),
        "cargo_percent": round_optional_float((used_cargo_m3 / clean_cargo_capacity_m3 * 100.0) if clean_cargo_capacity_m3 > 0 else 0.0),
        "purchase_budget_isk": round_optional_float(clean_purchase_budget_isk),
        "pickup_cost": round_optional_float(used_budget_isk),
        "budget_remaining_isk": round_optional_float(remaining_budget_isk),
        "gross_destination_revenue": round_optional_float(sum(float(line["gross_destination_revenue"]) for line in lines)),
        "net_destination_revenue": round_optional_float(sum(float(line["net_destination_revenue"]) for line in lines)),
        "sales_tax_total": round_optional_float(sum(float(line["sales_tax_total"]) for line in lines)),
        "net_profit": round_optional_float(total_net_profit),
        "net_profit_per_m3": round_optional_float(total_net_profit / used_cargo_m3) if used_cargo_m3 > 0 else None,
        "lines": lines,
        "stops": stops,
        "skipped_possible_trap_count": skipped_possible_trap_count,
        "skipped_unknown_volume_count": skipped_unknown_volume_count,
        "skipped_low_profit_count": skipped_low_profit_count,
        "source_depth_truncated": source_depth_truncated,
    }


def expected_realized_report_number(value: Any) -> float | int | str:
    number = clean_optional_float(value)
    if number is None:
        return ""
    rounded = round(number, 2)
    whole = round(rounded)
    if abs(rounded - whole) < 1e-9:
        return int(whole)
    return rounded


def build_expected_realized_report_row(
    *,
    date_created: str,
    category: str,
    location_to_post_order: str,
    order_type: str,
    item_name: str,
    quantity: Any,
    price_per_item: Any,
    expected_return_per_item: Any,
    buy_hub: str = "",
    realized_return_per_item: Any = None,
    expected_total_cost: Any = None,
    expected_total_return: Any = None,
    expected_total_profit: Any = None,
    planned_order_duration: str = "",
    buy_order_price_to_enter: Any = None,
    estimated_broker_fee_percent: Any = None,
    estimated_broker_fee_isk: Any = None,
    destination_sell_hub: str = "",
    destination_sell_target_price: Any = None,
    destination_sell_target_units: Any = None,
    destination_sell_target_details: str = "",
    actual_sell_price_per_item: Any = None,
    actual_buy_order_total: Any = None,
    actual_broker_fee_paid: Any = None,
    actual_total_cost: Any = None,
    actual_filled_quantity: Any = None,
    buy_directions: str = "",
    container_directions: str = "",
    sell_directions: str = "",
    reason_for_entry: str = "",
    verification_notes: str = "",
    lesson_learned: str = "",
    date_completed: str = "",
    status: str = "Planned",
    notes: str = "",
) -> dict[str, Any]:
    quantity_number = clean_optional_float(quantity)
    price_number = clean_optional_float(price_per_item)
    expected_return_number = clean_optional_float(expected_return_per_item)
    realized_return_number = clean_optional_float(realized_return_per_item)
    expected_total_cost_override = clean_optional_float(expected_total_cost)
    expected_total_return_override = clean_optional_float(expected_total_return)
    expected_total_profit_override = clean_optional_float(expected_total_profit)

    expected_total_cost = (
        expected_total_cost_override
        if expected_total_cost_override is not None
        else (
            quantity_number * price_number
            if quantity_number is not None and price_number is not None
            else None
        )
    )
    expected_total_return = (
        expected_total_return_override
        if expected_total_return_override is not None
        else (
            quantity_number * expected_return_number
            if quantity_number is not None and expected_return_number is not None
            else None
        )
    )
    realized_total_return = (
        quantity_number * realized_return_number
        if quantity_number is not None and realized_return_number is not None
        else None
    )
    expected_total_profit = (
        expected_total_profit_override
        if expected_total_profit_override is not None
        else (
            expected_total_return - expected_total_cost
            if expected_total_return is not None and expected_total_cost is not None
            else None
        )
    )
    expected_profit_per_item = (
        expected_total_profit / quantity_number
        if expected_total_profit is not None and quantity_number is not None and quantity_number > 0
        else None
    )
    realized_total_profit = (
        realized_total_return - expected_total_cost
        if realized_total_return is not None and expected_total_cost is not None
        else None
    )
    profit_difference = (
        realized_total_profit - expected_total_profit
        if realized_total_profit is not None and expected_total_profit is not None
        else None
    )

    row = {column: "" for column in EXPECTED_REALIZED_REPORT_COLUMNS}
    row.update(
        {
            "Date Created": str(date_created or ""),
            "Date Completed": str(date_completed or ""),
            "Status": str(status or "Planned"),
            "Category": str(category or ""),
            "Expected Profit Per Item": expected_realized_report_number(expected_profit_per_item),
            "Location to Post Order": str(location_to_post_order or ""),
            "Buy Hub": str(buy_hub or ""),
            "Order Type": str(order_type or ""),
            "Item Name": str(item_name or ""),
            "Quantity": expected_realized_report_number(quantity_number),
            "Planned Order Duration": str(planned_order_duration or ""),
            "Buy Directions": str(buy_directions or ""),
            "Container Directions": str(container_directions or ""),
            "Sell Directions": str(sell_directions or ""),
            "Price Per Item": expected_realized_report_number(price_number),
            "Buy Order Price To Enter": expected_realized_report_number(buy_order_price_to_enter),
            "Estimated Broker Fee %": expected_realized_report_number(estimated_broker_fee_percent),
            "Estimated Broker Fee ISK": expected_realized_report_number(estimated_broker_fee_isk),
            "Expected Return Per Item": expected_realized_report_number(expected_return_number),
            "Destination Sell Hub": str(destination_sell_hub or ""),
            "Destination Sell Target Price": expected_realized_report_number(destination_sell_target_price),
            "Destination Sell Target Units": expected_realized_report_number(destination_sell_target_units),
            "Destination Sell Target Details": str(destination_sell_target_details or ""),
            "Realized Return Per Item": expected_realized_report_number(realized_return_number),
            "Actual Sell Price Per Item": expected_realized_report_number(actual_sell_price_per_item),
            "Expected Total Cost": expected_realized_report_number(expected_total_cost),
            "Estimated Total ISK Needed": expected_realized_report_number(expected_total_cost),
            "Expected Total Return": expected_realized_report_number(expected_total_return),
            "Realized Total Return": expected_realized_report_number(realized_total_return),
            "Expected Total Profit": expected_realized_report_number(expected_total_profit),
            "Realized Total Profit": expected_realized_report_number(realized_total_profit),
            "Profit Difference": expected_realized_report_number(profit_difference),
            "Actual Buy Order Total": expected_realized_report_number(actual_buy_order_total),
            "Actual Broker Fee Paid": expected_realized_report_number(actual_broker_fee_paid),
            "Actual Total Cost": expected_realized_report_number(actual_total_cost),
            "Actual Filled Quantity": expected_realized_report_number(actual_filled_quantity),
            "Reason For Entry": str(reason_for_entry or ""),
            "Verification Notes": str(verification_notes or ""),
            "Lesson Learned": str(lesson_learned or ""),
            "Notes": str(notes or ""),
        }
    )
    return row


def spreadsheet_report_csv(rows: Iterable[Mapping[str, Any]]) -> str:
    output = io.StringIO()
    writer = csv.DictWriter(
        output,
        fieldnames=list(EXPECTED_REALIZED_REPORT_COLUMNS),
        extrasaction="ignore",
        lineterminator="\n",
    )
    writer.writeheader()
    for row in rows:
        writer.writerow({column: row.get(column, "") for column in EXPECTED_REALIZED_REPORT_COLUMNS})
    return output.getvalue()


def haul_report_pickup_system_label(line: Mapping[str, Any], stops: Iterable[Mapping[str, Any]]) -> str:
    type_id = clean_optional_int(line.get("type_id"))
    item_name_key = str(line.get("item_name") or "").strip().casefold()
    system_names: list[str] = []
    seen: set[str] = set()
    for stop in stops:
        system_name = str(stop.get("system_name") or "").strip()
        if not system_name:
            continue
        for item in stop.get("items") or []:
            item_type_id = clean_optional_int(item.get("type_id"))
            item_name = str(item.get("item_name") or "").strip().casefold()
            if (type_id is not None and item_type_id == type_id) or (item_name_key and item_name == item_name_key):
                key = system_name.casefold()
                if key not in seen:
                    seen.add(key)
                    system_names.append(system_name)
                break
    return "; ".join(system_names) if system_names else "Route pickup corridor"


def haul_report_opportunity_pickup_system_label(opportunity: Mapping[str, Any]) -> str:
    system_names: list[tuple[int, str]] = []
    seen: set[str] = set()
    for system in opportunity.get("matched_pickup_systems") or ():
        system_name = str(system.get("system_name") or "").strip()
        if not system_name:
            continue
        key = system_name.casefold()
        if key not in seen:
            seen.add(key)
            jumps = clean_optional_int(system.get("jumps"))
            system_names.append((jumps if jumps is not None else 999, system_name))
    if system_names:
        return "; ".join(system_name for _jumps, system_name in sorted(system_names, key=lambda item: (item[0], item[1])))
    pickup_order = opportunity.get("pickup_order") if isinstance(opportunity.get("pickup_order"), Mapping) else {}
    pickup_system_name = str(pickup_order.get("system_name") or "").strip()
    return pickup_system_name or "Route pickup corridor"


def asset_ledger_container_tag(value: str, fallback: str) -> str:
    tag = re.sub(r"[^A-Za-z0-9]+", "-", str(value or "").strip()).strip("-")
    return tag[:40] or fallback


def report_quantity_text(value: Any) -> str:
    number = clean_optional_float(value)
    if number is None:
        return ""
    rounded = round(number, 2)
    whole = round(rounded)
    if abs(rounded - whole) < 1e-9:
        return f"{int(whole):,}"
    return f"{rounded:,.2f}".rstrip("0").rstrip(".")


def destination_sell_target_details(
    *,
    destination_name: str,
    price: Any,
    units: Any,
    matched_buy_order_count: Any = None,
    visible_units: Any = None,
    weighted: bool = False,
) -> str:
    clean_destination = str(destination_name or "destination").strip() or "destination"
    price_text = format_isk(clean_optional_float(price)) if clean_optional_float(price) is not None else "unknown price"
    units_number = clean_optional_float(units)
    units_text = f"{report_quantity_text(units_number)} planned unit{'s' if units_number != 1 else ''}" if units_number is not None else "planned units"
    parts = [
        f"Sell into {clean_destination} public buy orders at {'weighted ' if weighted else ''}{price_text} for {units_text}."
    ]
    matched_count = clean_optional_int(matched_buy_order_count)
    if matched_count is not None and matched_count > 0:
        parts.append(
            f"{report_quantity_text(matched_count)} destination buy order{'s' if matched_count != 1 else ''} matched."
        )
    visible = clean_optional_float(visible_units)
    if visible is not None and visible > 0:
        parts.append(f"{report_quantity_text(visible)} visible unit{'s' if visible != 1 else ''} at scan time.")
    return " ".join(parts)


def haul_destination_sell_target_fields(
    item: Mapping[str, Any],
    *,
    destination_name: str,
    units: Any,
) -> dict[str, Any]:
    destination_order = item.get("destination_order") if isinstance(item.get("destination_order"), Mapping) else {}
    destination_hub = str(destination_order.get("system_name") or destination_name or "").strip()
    target_price = clean_optional_float(item.get("average_destination_price"))
    if target_price is None:
        target_price = clean_optional_float(destination_order.get("price"))
    matched_count = clean_optional_int(item.get("matched_buy_order_count"))
    visible_units = clean_optional_float(destination_order.get("volume_remain"))
    return {
        "destination_sell_hub": destination_hub,
        "destination_sell_target_price": target_price,
        "destination_sell_target_units": units,
        "destination_sell_target_details": destination_sell_target_details(
            destination_name=destination_hub or destination_name,
            price=target_price,
            units=units,
            matched_buy_order_count=matched_count,
            visible_units=visible_units,
            weighted=matched_count is not None and matched_count > 1,
        ),
    }


def acquisition_destination_sell_target_fields(
    item: Mapping[str, Any],
    *,
    destination_name: str,
    units: Any,
) -> dict[str, Any]:
    destination_buy = item.get("best_destination_buy") if isinstance(item.get("best_destination_buy"), Mapping) else {}
    destination_hub = str(destination_buy.get("system_name") or destination_name or "").strip()
    target_price = clean_optional_float(destination_buy.get("price"))
    if target_price is None:
        gross_revenue = clean_optional_float(item.get("gross_destination_revenue"))
        clean_units = clean_optional_float(units)
        if gross_revenue is not None and clean_units and clean_units > 0:
            target_price = gross_revenue / clean_units
    visible_units = clean_optional_float(destination_buy.get("volume_remain"))
    return {
        "destination_sell_hub": destination_hub,
        "destination_sell_target_price": target_price,
        "destination_sell_target_units": units,
        "destination_sell_target_details": destination_sell_target_details(
            destination_name=destination_hub or destination_name,
            price=target_price,
            units=units,
            visible_units=visible_units,
        ),
    }


def haul_report_direction_fields(
    *,
    item_name: str,
    pickup_label: str,
    destination_name: str,
    status: str,
) -> dict[str, str]:
    destination_tag = asset_ledger_container_tag(destination_name, "Route")
    planned_note = (
        "This row is in the current manual load plan."
        if str(status or "").casefold() == "planned"
        else "This row is only a candidate until you choose it for the manual load plan."
    )
    return {
        "buy_directions": (
            f"Buy {item_name or 'this item'} from the public sell orders shown in EVE for {pickup_label or 'the pickup system'}; "
            "verify the exact station/structure, price, quantity, min volume, and docking access before purchasing."
        ),
        "container_directions": (
            f"After purchase, keep the stack at the pickup station/structure where the order fills and put the route-ready cargo in "
            f"`CM-READY-HAUL-#{destination_tag}`. If you are only parking inventory for later review, use `CM-ASSET-#{destination_tag}` instead. "
            f"{planned_note}"
        ),
        "sell_directions": (
            f"Haul only after manual route verification, then sell into the destination public buy orders in {destination_name or 'the destination'} "
            "if the buy price and demand are still present."
        ),
    }


def acquisition_report_direction_fields(
    *,
    item_name: str,
    placement_system: str,
    destination_name: str,
    order_duration_label: str,
) -> dict[str, str]:
    destination_tag = asset_ledger_container_tag(destination_name, "Route")
    duration_adjective = re.sub(r"\s+days?\b", "-day", str(order_duration_label or "").strip()) or "manual"
    return {
        "buy_directions": (
            f"Place a manual {duration_adjective} buy order for {item_name or 'this item'} in {placement_system or 'the selected buy-order system'}; "
            "enter the suggested bid, confirm the broker-fee preview, range, and expected quantity in EVE before submitting."
        ),
        "container_directions": (
            f"When the order fills, put the filled stack in `Managed#Trade` at the station where the buy order filled. "
            f"Move it to `CM-READY-HAUL-#{destination_tag}` only after you choose it for a hauling trip toward {destination_name or 'the destination'}."
        ),
        "sell_directions": (
            f"After the fill is staged and reviewed, sell or haul toward {destination_name or 'the downstream demand hub'} only if the destination demand and margin still match the report."
        ),
    }


def haul_report_load_plan_keys(load_plan: Mapping[str, Any]) -> set[str]:
    keys: set[str] = set()
    for line in load_plan.get("lines") or ():
        type_id = clean_optional_int(line.get("type_id"))
        if type_id is not None:
            keys.add(f"type:{type_id}")
        item_name = str(line.get("item_name") or "").strip().casefold()
        if item_name:
            keys.add(f"name:{item_name}")
    return keys


def haul_report_opportunity_key(opportunity: Mapping[str, Any]) -> str:
    type_id = clean_optional_int(opportunity.get("type_id"))
    if type_id is not None:
        return f"type:{type_id}"
    item_name = str(opportunity.get("item_name") or "").strip().casefold()
    return f"name:{item_name}" if item_name else ""


def build_haul_expected_realized_report_rows(
    *,
    generated_at: str,
    route: Mapping[str, Any],
    hauling: Mapping[str, Any],
) -> list[dict[str, Any]]:
    load_plan = hauling.get("load_plan") if isinstance(hauling.get("load_plan"), Mapping) else {}
    opportunities = list(hauling.get("opportunities") or []) if isinstance(hauling.get("opportunities"), list) else []
    fallback_lines = list(load_plan.get("lines") or []) if isinstance(load_plan, Mapping) else []
    if not opportunities and not fallback_lines:
        return []
    origin = route.get("origin") if isinstance(route.get("origin"), Mapping) else {}
    destination = route.get("destination") if isinstance(route.get("destination"), Mapping) else {}
    origin_name = str(origin.get("name") or route.get("origin_query") or "origin")
    destination_name = str(destination.get("name") or route.get("destination_query") or "destination")
    rows: list[dict[str, Any]] = []
    load_plan_keys = haul_report_load_plan_keys(load_plan)
    route_jumps = clean_optional_int(route.get("route_jumps"))
    if opportunities:
        for opportunity in opportunities:
            units = clean_optional_float(opportunity.get("units"))
            if units is None or units <= 0:
                continue
            pickup_cost = clean_optional_float(opportunity.get("pickup_cost"))
            net_destination_revenue = clean_optional_float(opportunity.get("net_destination_revenue"))
            average_pickup_price = clean_optional_float(opportunity.get("average_pickup_price"))
            average_net_destination_price = clean_optional_float(opportunity.get("average_net_destination_price"))
            price_per_item = average_pickup_price if average_pickup_price is not None else (
                pickup_cost / units if pickup_cost is not None else None
            )
            expected_return_per_item = average_net_destination_price if average_net_destination_price is not None else (
                net_destination_revenue / units if net_destination_revenue is not None else None
            )
            risk_level = str(opportunity.get("risk_level") or "clear")
            matched_pickup_count = clean_optional_int(opportunity.get("matched_pickup_system_count")) or 0
            expected_sales_tax = clean_optional_float(opportunity.get("sales_tax_total"))
            extra_route_jumps = clean_optional_int(opportunity.get("extra_route_jumps"))
            expected_route_jumps = clean_optional_int(opportunity.get("matched_pickup_route_jumps"))
            if expected_route_jumps is None and route_jumps is not None and extra_route_jumps is not None:
                expected_route_jumps = route_jumps + extra_route_jumps
            in_load_plan = bool(haul_report_opportunity_key(opportunity) in load_plan_keys)
            status = "Planned" if in_load_plan else "Candidate"
            pickup_label = haul_report_opportunity_pickup_system_label(opportunity)
            directions = haul_report_direction_fields(
                item_name=str(opportunity.get("item_name") or ""),
                pickup_label=pickup_label,
                destination_name=destination_name,
                status=status,
            )
            sell_target = haul_destination_sell_target_fields(
                opportunity,
                destination_name=destination_name,
                units=units,
            )
            notes = (
                f"Hauler visible opportunity from {origin_name} to {destination_name}; "
                f"{matched_pickup_count} pickup system(s); risk {risk_level}; "
                f"{'included in the current manual load plan' if in_load_plan else 'not selected into the current manual load plan'}; "
                f"expected sales tax {format_isk(expected_sales_tax) if expected_sales_tax is not None else 'unknown'}; "
                f"expected route {expected_route_jumps if expected_route_jumps is not None else 'unknown'} jumps; "
                "verify live orders, docking access, and route in EVE before buying."
            )
            row = build_expected_realized_report_row(
                date_created=generated_at,
                category="Haul",
                location_to_post_order=pickup_label,
                order_type="Trade",
                item_name=str(opportunity.get("item_name") or ""),
                quantity=units,
                price_per_item=price_per_item,
                expected_return_per_item=expected_return_per_item,
                expected_total_cost=pickup_cost,
                expected_total_return=net_destination_revenue,
                expected_total_profit=opportunity.get("net_profit"),
                **sell_target,
                status=status,
                reason_for_entry=(
                    f"Manual hauling arbitrage: buy at pickup sell orders, haul from {origin_name} "
                    f"toward {destination_name}, then sell into destination buy orders if still available."
                ),
                verification_notes=(
                    "Before buying, verify pickup price, quantity, min volume, docking access, route safety, "
                    "destination buy price, destination demand quantity, and your sales tax. After the run, fill "
                    "actual buy/order cost, actual filled quantity, realized return, actual route jumps, and lesson learned."
                ),
                buy_directions=directions["buy_directions"],
                container_directions=directions["container_directions"],
                sell_directions=directions["sell_directions"],
                notes=notes,
            )
            row["Expected Sales Tax ISK"] = expected_realized_report_number(expected_sales_tax)
            row["Expected Route Jumps"] = expected_realized_report_number(expected_route_jumps)
            rows.append(row)
        return rows

    stops = list(load_plan.get("stops") or []) if isinstance(load_plan, Mapping) else []
    for line in fallback_lines:
        units = clean_optional_float(line.get("units"))
        if units is None or units <= 0:
            continue
        pickup_cost = clean_optional_float(line.get("pickup_cost"))
        net_destination_revenue = clean_optional_float(line.get("net_destination_revenue"))
        average_pickup_price = clean_optional_float(line.get("average_pickup_price"))
        price_per_item = average_pickup_price if average_pickup_price is not None else (
            pickup_cost / units if pickup_cost is not None else None
        )
        expected_return_per_item = (
            net_destination_revenue / units if net_destination_revenue is not None else None
        )
        risk_level = str(line.get("risk_level") or "clear")
        pickup_system_count = clean_optional_int(line.get("pickup_system_count")) or 0
        expected_sales_tax = clean_optional_float(line.get("sales_tax_total"))
        extra_route_jumps = clean_optional_int(line.get("extra_route_jumps"))
        expected_route_jumps = route_jumps + extra_route_jumps if route_jumps is not None and extra_route_jumps is not None else None
        pickup_label = haul_report_pickup_system_label(line, stops)
        directions = haul_report_direction_fields(
            item_name=str(line.get("item_name") or ""),
            pickup_label=pickup_label,
            destination_name=destination_name,
            status="Planned",
        )
        sell_target = haul_destination_sell_target_fields(
            line,
            destination_name=destination_name,
            units=units,
        )
        notes = (
            f"Hauler load-plan row from {origin_name} to {destination_name}; "
            f"{pickup_system_count} pickup system(s); risk {risk_level}; "
            f"expected sales tax {format_isk(expected_sales_tax) if expected_sales_tax is not None else 'unknown'}; "
            f"expected route {expected_route_jumps if expected_route_jumps is not None else 'unknown'} jumps; "
            "verify live orders, docking access, and route in EVE before buying."
        )
        row = build_expected_realized_report_row(
            date_created=generated_at,
            category="Haul",
            location_to_post_order=pickup_label,
            order_type="Trade",
            item_name=str(line.get("item_name") or ""),
            quantity=units,
            price_per_item=price_per_item,
            expected_return_per_item=expected_return_per_item,
            expected_total_cost=pickup_cost,
            expected_total_return=net_destination_revenue,
            expected_total_profit=line.get("net_profit"),
            **sell_target,
            reason_for_entry=(
                f"Manual hauling load plan: buy at pickup sell orders, haul from {origin_name} "
                f"toward {destination_name}, then sell into destination buy orders if still available."
            ),
            verification_notes=(
                "Before buying, verify pickup price, quantity, min volume, docking access, route safety, "
                "destination buy price, destination demand quantity, and your sales tax. After the run, fill "
                "actual buy/order cost, actual filled quantity, realized return, actual route jumps, and lesson learned."
            ),
            buy_directions=directions["buy_directions"],
            container_directions=directions["container_directions"],
            sell_directions=directions["sell_directions"],
            notes=notes,
        )
        row["Expected Sales Tax ISK"] = expected_realized_report_number(expected_sales_tax)
        row["Expected Route Jumps"] = expected_realized_report_number(expected_route_jumps)
        rows.append(row)
    return rows


def build_acquisition_expected_realized_report_rows(
    *,
    generated_at: str,
    route: Mapping[str, Any],
    acquisition: Mapping[str, Any],
) -> list[dict[str, Any]]:
    portfolio = acquisition.get("portfolio") if isinstance(acquisition.get("portfolio"), Mapping) else {}
    lines = list(portfolio.get("lines") or []) if isinstance(portfolio, Mapping) else []
    if not lines:
        return []
    origin = route.get("origin") if isinstance(route.get("origin"), Mapping) else {}
    destination = route.get("destination") if isinstance(route.get("destination"), Mapping) else {}
    origin_name = str(origin.get("name") or acquisition.get("origin_system", {}).get("name") or "source")
    destination_name = str(destination.get("name") or acquisition.get("destination_system", {}).get("name") or "destination")
    order_duration_days = clamp_acquisition_order_duration_days(
        acquisition.get("order_duration_days", DEFAULT_ACQUISITION_ORDER_DURATION_DAYS)
    )
    order_duration_label = f"{order_duration_days} day{'s' if order_duration_days != 1 else ''}"
    rows: list[dict[str, Any]] = []
    for line in lines:
        units = clean_optional_float(line.get("recommended_units"))
        if units is None or units <= 0:
            continue
        estimated_committed = clean_optional_float(line.get("estimated_isk_committed"))
        estimated_net_revenue = clean_optional_float(line.get("estimated_net_revenue"))
        price_per_item = line.get("suggested_bid")
        expected_return_per_item = (
            estimated_net_revenue / units if estimated_net_revenue is not None else None
        )
        placement_system = str(line.get("placement_system") or origin_name)
        broker_fee_rate = clean_optional_float(line.get("broker_fee_rate"))
        if broker_fee_rate is None:
            broker_fee_percent = clean_optional_float(acquisition.get("broker_fee_percent"))
            if broker_fee_percent is not None:
                broker_fee_rate = broker_fee_percent / 100.0
        estimated_broker_fee = clean_optional_float(line.get("estimated_broker_fee"))
        broker_fee_percent_value = round_optional_float(broker_fee_rate * 100.0) if broker_fee_rate is not None else None
        broker_fee_note = (
            f"{broker_fee_percent_value:g}% estimated broker fee"
            if broker_fee_percent_value is not None
            else "estimated broker fee"
        )
        risk_level = str(line.get("risk_level") or "clear")
        reason_for_entry = (
            f"Suggested buy order in {placement_system} toward {destination_name}; "
            f"risk {risk_level}; target margin {format_isk(clean_optional_float(line.get('net_profit_per_unit')))} per unit."
        )
        verification_notes = (
            "Before placing: verify buy-order duration, broker fee preview, order range, item volume, "
            "market history warning, and current Jita buy order."
        )
        notes = (
            f"Investment portfolio line toward {destination_name}; category {line.get('category') or 'Selected scope'}; "
            f"suggested bid {format_isk(clean_optional_float(line.get('suggested_bid')))}; "
            f"safe ceiling {format_isk(clean_optional_float(line.get('max_safe_bid')))}; "
            f"risk {risk_level}; planned order duration {order_duration_label}; "
            f"Price Per Item is the buy-order price to enter; "
            f"Expected Total Cost includes {broker_fee_note}."
        )
        directions = acquisition_report_direction_fields(
            item_name=str(line.get("item_name") or ""),
            placement_system=placement_system,
            destination_name=destination_name,
            order_duration_label=order_duration_label,
        )
        sell_target = acquisition_destination_sell_target_fields(
            line,
            destination_name=destination_name,
            units=units,
        )
        rows.append(
            build_expected_realized_report_row(
                date_created=generated_at,
                category="Investment",
                location_to_post_order=placement_system,
                order_type="Buy",
                buy_hub=str(line.get("source_hub_name") or line.get("comparison_source_hub") or placement_system),
                item_name=str(line.get("item_name") or ""),
                quantity=units,
                planned_order_duration=order_duration_label,
                price_per_item=price_per_item,
                buy_order_price_to_enter=price_per_item,
                estimated_broker_fee_percent=broker_fee_percent_value,
                estimated_broker_fee_isk=estimated_broker_fee,
                expected_return_per_item=expected_return_per_item,
                **sell_target,
                expected_total_cost=estimated_committed,
                reason_for_entry=reason_for_entry,
                verification_notes=verification_notes,
                buy_directions=directions["buy_directions"],
                container_directions=directions["container_directions"],
                sell_directions=directions["sell_directions"],
                notes=notes,
            )
        )
    return rows


def fetch_haul_destination_buy_batch(
    *,
    config: EveSsoConfig,
    targets: Iterable[Mapping[str, Any]],
    destination_region_id: int,
) -> tuple[dict[int, list[dict[str, Any]]], list[dict[str, Any]]]:
    buys_by_type_id: dict[int, list[dict[str, Any]]] = {}
    errors: list[dict[str, Any]] = []
    type_ids: list[int] = []
    seen_type_ids: set[int] = set()
    for target in targets:
        type_id = clean_optional_int(target.get("type_id"))
        if type_id is None or type_id in seen_type_ids:
            continue
        seen_type_ids.add(type_id)
        type_ids.append(type_id)
    if not type_ids:
        return buys_by_type_id, errors

    clean_destination_region_id = int(destination_region_id)
    worker_count = max(1, min(MAX_FLIGHT_HAUL_FETCH_WORKERS, len(type_ids)))
    with ThreadPoolExecutor(max_workers=worker_count) as executor:
        futures = {
            executor.submit(
                fetch_market_buy_orders,
                config,
                region_id=clean_destination_region_id,
                type_id=type_id,
            ): type_id
            for type_id in type_ids
        }
        for future in as_completed(futures):
            type_id = futures[future]
            try:
                buys_by_type_id[type_id] = future.result()
            except CorpMarketError as exc:
                errors.append(
                    {
                        "order_type": "buy",
                        "type_id": type_id,
                        "region_id": clean_destination_region_id,
                        "error": str(exc),
                    }
                )
                buys_by_type_id[type_id] = []
    return buys_by_type_id, errors


def fetch_haul_pickup_sell_batch(
    *,
    config: EveSsoConfig,
    type_ids: Iterable[int],
    pickup_region_ids: Iterable[int],
) -> tuple[dict[tuple[int, int], list[dict[str, Any]]], list[dict[str, Any]]]:
    sells_by_type_region: dict[tuple[int, int], list[dict[str, Any]]] = {}
    errors: list[dict[str, Any]] = []
    clean_type_ids = tuple(
        sorted({type_id for value in type_ids for type_id in [clean_optional_int(value)] if type_id is not None})
    )
    clean_region_ids = tuple(
        sorted({region_id for value in pickup_region_ids for region_id in [clean_optional_int(value)] if region_id is not None})
    )
    tasks = [(type_id, region_id) for type_id in clean_type_ids for region_id in clean_region_ids]
    if not tasks:
        return sells_by_type_region, errors

    worker_count = max(1, min(MAX_FLIGHT_HAUL_FETCH_WORKERS, len(tasks)))
    with ThreadPoolExecutor(max_workers=worker_count) as executor:
        futures = {
            executor.submit(fetch_market_sell_orders, config, region_id=region_id, type_id=type_id): (type_id, region_id)
            for type_id, region_id in tasks
        }
        for future in as_completed(futures):
            type_id, region_id = futures[future]
            try:
                sells_by_type_region[(type_id, region_id)] = future.result()
            except CorpMarketError as exc:
                errors.append({"order_type": "sell", "type_id": type_id, "region_id": region_id, "error": str(exc)})
                sells_by_type_region[(type_id, region_id)] = []
    return sells_by_type_region, errors


def fetch_haul_history_batch(
    *,
    config: EveSsoConfig,
    requests: Iterable[tuple[int, int]],
) -> tuple[dict[tuple[int, int], list[dict[str, Any]]], list[dict[str, Any]]]:
    history_by_type_region: dict[tuple[int, int], list[dict[str, Any]]] = {}
    errors: list[dict[str, Any]] = []
    clean_request_set: set[tuple[int, int]] = set()
    for raw_type_id, raw_region_id in requests:
        type_id = clean_optional_int(raw_type_id)
        region_id = clean_optional_int(raw_region_id)
        if type_id is not None and region_id is not None:
            clean_request_set.add((type_id, region_id))
    clean_requests = tuple(
        sorted(clean_request_set)
    )
    if not clean_requests:
        return history_by_type_region, errors

    worker_count = max(1, min(MAX_FLIGHT_HAUL_FETCH_WORKERS, len(clean_requests)))
    with ThreadPoolExecutor(max_workers=worker_count) as executor:
        futures = {
            executor.submit(fetch_market_history, config, region_id=region_id, type_id=type_id): (type_id, region_id)
            for type_id, region_id in clean_requests
        }
        for future in as_completed(futures):
            type_id, region_id = futures[future]
            try:
                history_by_type_region[(type_id, region_id)] = future.result()
            except CorpMarketError as exc:
                errors.append({"history": "market", "type_id": type_id, "region_id": region_id, "error": str(exc)})
    return history_by_type_region, errors


def fetch_acquisition_order_batch(
    *,
    config: EveSsoConfig,
    type_id: int,
    pickup_region_ids: Iterable[int],
    destination_region_id: int,
) -> tuple[dict[int, list[dict[str, Any]]], dict[int, list[dict[str, Any]]], list[dict[str, Any]], list[dict[str, Any]]]:
    source_buys_by_region: dict[int, list[dict[str, Any]]] = {}
    source_sells_by_region: dict[int, list[dict[str, Any]]] = {}
    destination_buys: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    tasks: list[tuple[str, int, Callable[..., list[dict[str, Any]]]]] = []
    for region_id in pickup_region_ids:
        clean_region_id = int(region_id)
        tasks.append(("source_buy", clean_region_id, fetch_market_buy_orders))
        tasks.append(("source_sell", clean_region_id, fetch_market_sell_orders))
    tasks.append(("destination_buy", int(destination_region_id), fetch_market_buy_orders))
    if not tasks:
        return source_buys_by_region, source_sells_by_region, destination_buys, errors

    worker_count = max(1, min(MAX_FLIGHT_ACQUISITION_FETCH_WORKERS, len(tasks)))
    with ThreadPoolExecutor(max_workers=worker_count) as executor:
        futures = {
            executor.submit(fetcher, config, region_id=region_id, type_id=type_id): (kind, region_id)
            for kind, region_id, fetcher in tasks
        }
        for future in as_completed(futures):
            kind, region_id = futures[future]
            order_type = "sell" if kind == "source_sell" else "buy"
            try:
                raw_orders = future.result()
            except CorpMarketError as exc:
                errors.append({"order_type": order_type, "type_id": type_id, "region_id": region_id, "error": str(exc)})
                raw_orders = []
            if kind == "source_buy":
                source_buys_by_region[region_id] = raw_orders
            elif kind == "source_sell":
                source_sells_by_region[region_id] = raw_orders
            else:
                destination_buys = raw_orders
    return source_buys_by_region, source_sells_by_region, destination_buys, errors


def fetch_acquisition_history_batch(
    *,
    config: EveSsoConfig,
    type_id: int,
    source_region_id: int,
    destination_region_id: int,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
    source_history: list[dict[str, Any]] = []
    destination_history: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    tasks: list[tuple[str, int]] = [("source", int(source_region_id))]
    if int(destination_region_id) != int(source_region_id):
        tasks.append(("destination", int(destination_region_id)))
    worker_count = max(1, min(MAX_FLIGHT_ACQUISITION_FETCH_WORKERS, len(tasks)))
    with ThreadPoolExecutor(max_workers=worker_count) as executor:
        futures = {
            executor.submit(fetch_market_history, config, region_id=region_id, type_id=type_id): (kind, region_id)
            for kind, region_id in tasks
        }
        for future in as_completed(futures):
            kind, region_id = futures[future]
            try:
                history = future.result()
            except CorpMarketError as exc:
                errors.append({"history": kind, "type_id": type_id, "region_id": region_id, "error": str(exc)})
                history = []
            if kind == "source":
                source_history = history
            else:
                destination_history = history
    if int(destination_region_id) == int(source_region_id):
        destination_history = source_history
    return source_history, destination_history, errors


def scan_acquisition_item_opportunity(
    *,
    config: EveSsoConfig,
    target: Mapping[str, Any],
    item_index: int,
    item_count: int,
    pickup_region_ids: Iterable[int],
    region_count: int,
    origin: RouteSystem,
    destination: RouteSystem,
    systems: Mapping[int, RouteSystem],
    pickup_distances: Mapping[int, int],
    destination_distances: Mapping[int, int],
    budget_isk: float,
    pickup_jumps: int,
    min_margin_percent: float,
    broker_fee_rate: float,
    sales_tax_rate: float,
    target_days: int,
    progress_percent: Callable[[int, float], int],
    history_analysis_mode: str = DEFAULT_ACQUISITION_HISTORY_ANALYSIS_MODE,
    progress: Callable[[str, dict[str, Any]], None] | None = None,
) -> AcquisitionItemScanResult:
    from eve_voice_pilot.corp_market_acquisition import scan_acquisition_item_opportunity as scan_impl

    return scan_impl(
        deps=sys.modules[__name__],
        config=config,
        target=target,
        item_index=item_index,
        item_count=item_count,
        pickup_region_ids=pickup_region_ids,
        region_count=region_count,
        origin=origin,
        destination=destination,
        systems=systems,
        pickup_distances=pickup_distances,
        destination_distances=destination_distances,
        budget_isk=budget_isk,
        pickup_jumps=pickup_jumps,
        min_margin_percent=min_margin_percent,
        broker_fee_rate=broker_fee_rate,
        sales_tax_rate=sales_tax_rate,
        target_days=target_days,
        history_analysis_mode=history_analysis_mode,
        progress_percent=progress_percent,
        progress=progress,
    )


