def build_acquisition_strategy_summary(
    *,
    opportunities: Iterable[dict[str, Any]],
    origin: RouteSystem,
    destination: RouteSystem,
    item_scope: dict[str, Any],
    budget_isk: float,
    pickup_jumps: int,
    min_margin_percent: float,
    broker_fee_percent: float,
    target_days: int,
    scanned_item_types: int,
    total_item_types: int,
    pickup_regions_scanned: int,
    item_truncated: bool,
    portfolio: dict[str, Any],
    history_analysis_mode: str = DEFAULT_ACQUISITION_HISTORY_ANALYSIS_MODE,
) -> dict[str, Any]:
    clean_history_mode = normalize_acquisition_history_analysis_mode(history_analysis_mode)
    history_label = acquisition_history_analysis_label(clean_history_mode)
    ranked = list(opportunities)
    best = ranked[0] if ranked else None
    portfolio_lines = list(portfolio.get("lines") or []) if isinstance(portfolio, dict) else []
    portfolio_category_count = int(portfolio.get("category_count") or 0) if isinstance(portfolio, dict) else 0
    portfolio_category_word = "category" if portfolio_category_count == 1 else "categories"
    common_materials = bool(item_scope.get("include_common_materials"))
    common_limit = int(item_scope.get("common_material_scan_limit") or 0)
    common_available = int(item_scope.get("common_material_available_item_types") or common_limit)
    selected_group_count = int(item_scope.get("selected_market_group_count") or 0)
    if portfolio_lines:
        headline = (
            f"Diversified portfolio uses {format_isk(float(portfolio.get('invested_isk') or 0.0))} across "
            f"{int(portfolio.get('line_count') or 0):,} item line(s) and "
            f"{portfolio_category_count:,} {portfolio_category_word}."
        )
        next_step = (
            "Copy the portfolio items to Quickbar, verify the warnings in EVE, then place small manual buy orders "
            "inside the portfolio budget."
        )
    elif best:
        headline = (
            f"Best shown buy-order plan is {best['item_name']} at {format_isk(best['suggested_bid'])} "
            f"or less, with {format_isk(best['net_profit'])} estimated after-fee profit."
        )
        if str(best.get("risk_level") or "") == "possible-trap":
            next_step = "Treat the top result as a price-check candidate first because history raised a trap signal."
        else:
            next_step = "Verify the current buy/sell orders in EVE, then start with the suggested first-order size."
    else:
        headline = f"No buy-order plan cleared the current filters from {origin.name} toward {destination.name}."
        next_step = "Try a smaller targeted category, lower the target margin, or rerun after market caches refresh."
    if common_materials and selected_group_count:
        scope_note = (
            f"Scanning the top {common_limit:,} of {common_available:,} common industry inputs first, then selected market categories, "
            f"up to {scanned_item_types:,} item types this run."
        )
    elif common_materials:
        scope_note = (
            f"Common materials is a hosted-safe quick scan of the top {common_limit:,} of {common_available:,} "
            "industry inputs by recipe use. "
            "Use a market category when you want to inspect a specific trade family."
        )
    elif selected_group_count:
        scope_note = f"Scanning selected market categories, capped at {scanned_item_types:,} item types this run."
    else:
        scope_note = "No item scope was selected."
    if item_truncated:
        timeout_note = (
            f"The selected scope has {total_item_types:,} item types, so this request checked the first "
            f"{scanned_item_types:,}. This keeps public-hosted scans under timeout limits."
        )
    else:
        timeout_note = f"Checked all {scanned_item_types:,} selected item types across {pickup_regions_scanned:,} pickup region(s)."
    return {
        "headline": headline,
        "plain_language": (
            f"This spreads a manual public buy-order budget around {origin.name} across item families, then assumes "
            f"you haul filled stock and sell into current {destination.name} buy demand. It is an income planning view, "
            "not an order placer."
        ),
        "math_note": (
            f"Safe ceiling starts with the destination buy price after sales tax, then backs out the "
            f"{broker_fee_percent:g}% broker-fee estimate and {min_margin_percent:g}% target margin. "
            f"Units are capped by the {format_isk(budget_isk)} budget, visible destination demand, and "
            + (
                "a conservative one-unit shortlist cap because market-history audit is off. "
                if clean_history_mode == "fast"
                else f"{target_days:g} day(s) of recent source-region completed-trade volume. "
            )
            + "Portfolio rows are then scaled to the total investment and jump budget."
        ),
        "history_note": (
            f"History analysis: {history_label}. "
            + (
                "Fast shortlist skips market-history calls and marks candidates for later audit."
                if clean_history_mode == "fast"
                else "Market history is regional completed-trade statistics; it supports or contradicts the current order book, but it does not guarantee future buyers."
            )
        ),
        "scope_note": scope_note,
        "timeout_note": timeout_note,
        "next_step": next_step,
        "best": acquisition_strategy_best_dict(best),
        "portfolio": {
            "line_count": portfolio.get("line_count") if isinstance(portfolio, dict) else 0,
            "category_count": portfolio.get("category_count") if isinstance(portfolio, dict) else 0,
            "invested_isk": portfolio.get("invested_isk") if isinstance(portfolio, dict) else 0.0,
            "budget_remaining_isk": portfolio.get("budget_remaining_isk") if isinstance(portfolio, dict) else budget_isk,
            "estimated_net_profit": portfolio.get("estimated_net_profit") if isinstance(portfolio, dict) else 0.0,
            "used_jumps": portfolio.get("used_jumps") if isinstance(portfolio, dict) else 0,
            "max_portfolio_jumps": portfolio.get("max_portfolio_jumps") if isinstance(portfolio, dict) else 0,
        },
    }


def acquisition_strategy_best_dict(opportunity: dict[str, Any] | None) -> dict[str, Any] | None:
    if not opportunity:
        return None
    return {
        "type_id": opportunity.get("type_id"),
        "item_name": opportunity.get("item_name"),
        "risk_level": opportunity.get("risk_level"),
        "suggested_bid": opportunity.get("suggested_bid"),
        "recommended_units": opportunity.get("recommended_units"),
        "estimated_isk_committed": opportunity.get("estimated_isk_committed"),
        "net_profit": opportunity.get("net_profit"),
        "margin_percent": opportunity.get("margin_percent"),
    }


def acquisition_portfolio_category(opportunity: Mapping[str, Any]) -> str:
    labels = [
        str(label or "").strip()
        for label in opportunity.get("source_labels") or []
        if str(label or "").strip()
    ]
    market_group_name = str(opportunity.get("market_group_name") or "").strip()
    for label in labels:
        if label and label != "Selected items":
            return label
    if market_group_name:
        return market_group_name
    if labels:
        return labels[0]
    return "Selected scope"


def acquisition_portfolio_jump_cost(opportunity: Mapping[str, Any], *, fallback_pickup_jumps: int) -> int:
    recommendation = opportunity.get("range_recommendation") if isinstance(opportunity.get("range_recommendation"), dict) else {}
    range_text = str(recommendation.get("range") or "").strip().lower()
    match = re.search(r"(\d+)\s*jumps?", range_text)
    if match:
        return max(1, min(MAX_ACQUISITION_PORTFOLIO_JUMPS, int(match.group(1))))
    if range_text in {"station", "solar system", "system"}:
        return 1
    return max(1, min(MAX_ACQUISITION_PORTFOLIO_JUMPS, int(fallback_pickup_jumps or 1)))


def acquisition_portfolio_line(
    opportunity: Mapping[str, Any],
    *,
    units: int,
    category: str,
    estimated_collection_jumps: int,
    total_budget_isk: float,
) -> dict[str, Any]:
    original_units = max(1, int(opportunity.get("recommended_units") or 1))
    clean_units = max(1, min(int(units), original_units))
    scale = clean_units / original_units

    def scaled_value(key: str) -> float:
        return float(opportunity.get(key) or 0.0) * scale

    estimated_isk_committed = scaled_value("estimated_isk_committed")
    return {
        "type_id": opportunity.get("type_id"),
        "item_name": opportunity.get("item_name"),
        "category": category,
        "source_labels": list(opportunity.get("source_labels") or []),
        "market_group_id": opportunity.get("market_group_id"),
        "market_group_name": opportunity.get("market_group_name") or "",
        "risk_level": opportunity.get("risk_level"),
        "decision": opportunity.get("decision"),
        "range_recommendation": opportunity.get("range_recommendation"),
        "placement_system": opportunity.get("placement_system") or "",
        "source_hub_name": opportunity.get("source_hub_name") or opportunity.get("comparison_source_hub") or "",
        "comparison_source_hub": opportunity.get("comparison_source_hub") or opportunity.get("source_hub_name") or "",
        "estimated_collection_jumps": estimated_collection_jumps,
        "recommended_units": clean_units,
        "original_recommended_units": original_units,
        "suggested_bid": opportunity.get("suggested_bid"),
        "max_safe_bid": opportunity.get("max_safe_bid"),
        "broker_fee_rate": opportunity.get("broker_fee_rate"),
        "estimated_bid_total": scaled_value("estimated_bid_total"),
        "estimated_broker_fee": scaled_value("estimated_broker_fee"),
        "estimated_isk_committed": estimated_isk_committed,
        "gross_destination_revenue": scaled_value("gross_destination_revenue"),
        "estimated_sales_tax": scaled_value("estimated_sales_tax"),
        "estimated_net_revenue": scaled_value("estimated_net_revenue"),
        "net_profit": scaled_value("net_profit"),
        "net_profit_per_unit": opportunity.get("net_profit_per_unit"),
        "margin_percent": opportunity.get("margin_percent"),
        "portfolio_weight_percent": round_optional_float(estimated_isk_committed / total_budget_isk * 100.0) if total_budget_isk > 0 else 0.0,
        "best_source_buy": opportunity.get("best_source_buy"),
        "best_source_sell": opportunity.get("best_source_sell"),
        "best_destination_buy": opportunity.get("best_destination_buy"),
        "source_history": opportunity.get("source_history"),
        "destination_history": opportunity.get("destination_history"),
        "source_history_windows": opportunity.get("source_history_windows"),
        "destination_history_windows": opportunity.get("destination_history_windows"),
        "history_analysis_mode": opportunity.get("history_analysis_mode"),
        "history_analysis_label": opportunity.get("history_analysis_label"),
        "liquidity_confidence": opportunity.get("liquidity_confidence"),
        "buyer_concentration": opportunity.get("buyer_concentration"),
        "competition_pressure": opportunity.get("competition_pressure"),
        "why_might_fail": list(opportunity.get("why_might_fail") or []),
        "history_flags": opportunity.get("history_flags"),
    }


def acquisition_portfolio_exclusion_row(
    opportunity: Mapping[str, Any],
    *,
    reason_key: str,
    reason_label: str,
    detail: str,
    category: str | None = None,
    jump_cost: int | None = None,
    unit_commitment: float | None = None,
) -> dict[str, Any]:
    return {
        "type_id": opportunity.get("type_id"),
        "item_name": opportunity.get("item_name"),
        "category": category or acquisition_portfolio_category(opportunity),
        "reason_key": reason_key,
        "reason_label": reason_label,
        "detail": detail,
        "source_hub_name": opportunity.get("source_hub_name") or opportunity.get("comparison_source_hub") or "",
        "comparison_source_hub": opportunity.get("comparison_source_hub") or opportunity.get("source_hub_name") or "",
        "risk_level": opportunity.get("risk_level"),
        "suggested_bid": opportunity.get("suggested_bid"),
        "max_safe_bid": opportunity.get("max_safe_bid"),
        "recommended_units": opportunity.get("recommended_units"),
        "estimated_isk_committed": opportunity.get("estimated_isk_committed"),
        "unit_commitment": unit_commitment,
        "net_profit": opportunity.get("net_profit"),
        "margin_percent": opportunity.get("margin_percent"),
        "estimated_collection_jumps": jump_cost,
        "liquidity_confidence": opportunity.get("liquidity_confidence"),
        "buyer_concentration": opportunity.get("buyer_concentration"),
        "competition_pressure": opportunity.get("competition_pressure"),
        "why_might_fail": list(opportunity.get("why_might_fail") or []),
        "history_flags": opportunity.get("history_flags"),
    }


def build_acquisition_investment_portfolio(
    *,
    opportunities: Iterable[dict[str, Any]],
    budget_isk: float,
    max_portfolio_jumps: int,
    pickup_jumps: int,
) -> dict[str, Any]:
    clean_budget = clamp_acquisition_budget_isk(budget_isk)
    clean_max_jumps = clamp_acquisition_portfolio_jumps(max_portfolio_jumps)
    ranked_opportunities = list(opportunities)
    possible_trap_excluded_count = sum(
        1 for opportunity in ranked_opportunities if str(opportunity.get("risk_level") or "") == "possible-trap"
    )
    candidates = []
    excluded_rows: list[dict[str, Any]] = []
    for index, opportunity in enumerate(ranked_opportunities):
        risk_level = str(opportunity.get("risk_level") or "")
        if risk_level == "possible-trap":
            excluded_rows.append(
                acquisition_portfolio_exclusion_row(
                    opportunity,
                    reason_key="possible_trap",
                    reason_label="Possible trap",
                    detail="Market history or price shape looked trap-like, so this row is not funded until manually verified.",
                )
            )
            continue
        recommended_units = clean_optional_int(opportunity.get("recommended_units")) or 0
        estimated_isk_committed = clean_optional_float(opportunity.get("estimated_isk_committed")) or 0.0
        net_profit = clean_optional_float(opportunity.get("net_profit")) or 0.0
        if recommended_units <= 0:
            excluded_rows.append(
                acquisition_portfolio_exclusion_row(
                    opportunity,
                    reason_key="history_weakness",
                    reason_label="History weakness",
                    detail="Recent market history did not support a first-order size.",
                )
            )
            continue
        if estimated_isk_committed <= 0:
            excluded_rows.append(
                acquisition_portfolio_exclusion_row(
                    opportunity,
                    reason_key="budget_cap",
                    reason_label="Budget cap",
                    detail="The planner could not calculate a positive committed cost for this order.",
                )
            )
            continue
        if net_profit <= 0:
            excluded_rows.append(
                acquisition_portfolio_exclusion_row(
                    opportunity,
                    reason_key="margin_too_low",
                    reason_label="Margin too low",
                    detail="After broker fee and sales tax, expected profit did not clear the required margin.",
                )
            )
            continue
        unit_commitment = estimated_isk_committed / recommended_units
        if unit_commitment <= 0 or unit_commitment > clean_budget:
            excluded_rows.append(
                acquisition_portfolio_exclusion_row(
                    opportunity,
                    reason_key="budget_cap",
                    reason_label="Budget cap",
                    detail="Even one filled unit would exceed the total investment budget.",
                    unit_commitment=unit_commitment,
                )
            )
            continue
        category = acquisition_portfolio_category(opportunity)
        jump_cost = acquisition_portfolio_jump_cost(opportunity, fallback_pickup_jumps=pickup_jumps)
        if jump_cost > clean_max_jumps:
            excluded_rows.append(
                acquisition_portfolio_exclusion_row(
                    opportunity,
                    reason_key="jump_cap",
                    reason_label="Jump cap",
                    detail="The recommended collection range would exceed the total portfolio jump budget.",
                    category=category,
                    jump_cost=jump_cost,
                    unit_commitment=unit_commitment,
                )
            )
            continue
        candidates.append(
            {
                "index": index,
                "opportunity": opportunity,
                "category": category,
                "jump_cost": jump_cost,
                "unit_commitment": unit_commitment,
                "recommended_units": recommended_units,
            }
        )

    if not candidates:
        return {
            "available": False,
            "strategy": "Diversified investment portfolio",
            "investment_budget_isk": clean_budget,
            "max_portfolio_jumps": clean_max_jumps,
            "invested_isk": 0.0,
            "budget_remaining_isk": clean_budget,
            "estimated_net_profit": 0.0,
            "margin_percent": None,
            "line_count": 0,
            "category_count": 0,
            "used_jumps": 0,
            "jumps_remaining": clean_max_jumps,
            "possible_trap_excluded_count": possible_trap_excluded_count,
            "caution_line_count": 0,
            "category_allocations": [],
            "excluded_rows": excluded_rows,
            "excluded_reason_counts": acquisition_exclusion_reason_counts(excluded_rows),
            "lines": [],
            "manual_note": (
                "No clear or caution opportunities fit the portfolio budget and jump budget. Possible trap rows are "
                "left out of funded plans until manually verified."
            ),
        }

    candidates.sort(
        key=lambda item: (
            acquisition_risk_sort_rank(str(item["opportunity"].get("risk_level") or "")),
            -float(item["opportunity"].get("net_profit") or 0.0),
            -float(item["opportunity"].get("margin_percent") or 0.0),
            str(item["opportunity"].get("item_name") or ""),
        )
    )
    candidates_by_category: dict[str, list[dict[str, Any]]] = {}
    for candidate in candidates:
        candidates_by_category.setdefault(str(candidate["category"]), []).append(candidate)
    category_names = sorted(
        candidates_by_category,
        key=lambda category: (
            acquisition_risk_sort_rank(str(candidates_by_category[category][0]["opportunity"].get("risk_level") or "")),
            -float(candidates_by_category[category][0]["opportunity"].get("net_profit") or 0.0),
            category,
        ),
    )
    target_category_count = max(1, min(len(category_names), MAX_ACQUISITION_PORTFOLIO_LINES))
    category_budget_target = clean_budget / target_category_count
    category_budget_cap = clean_budget if target_category_count == 1 else max(category_budget_target * 1.5, clean_budget * 0.35)

    selected_indexes: set[int] = set()
    category_spend: dict[str, float] = {category: 0.0 for category in category_names}
    lines: list[dict[str, Any]] = []
    remaining_budget = clean_budget
    used_jumps = 0

    def try_add_candidate(candidate: dict[str, Any], *, line_budget: float) -> bool:
        nonlocal remaining_budget, used_jumps
        if len(lines) >= MAX_ACQUISITION_PORTFOLIO_LINES or int(candidate["index"]) in selected_indexes:
            return False
        jump_cost = int(candidate["jump_cost"])
        if used_jumps + jump_cost > clean_max_jumps:
            return False
        allowed_budget = min(float(line_budget), remaining_budget)
        if allowed_budget <= 0:
            return False
        unit_commitment = float(candidate["unit_commitment"])
        units = min(int(candidate["recommended_units"]), int(allowed_budget // unit_commitment))
        if units <= 0:
            return False
        line = acquisition_portfolio_line(
            candidate["opportunity"],
            units=units,
            category=str(candidate["category"]),
            estimated_collection_jumps=jump_cost,
            total_budget_isk=clean_budget,
        )
        line_commitment = float(line["estimated_isk_committed"])
        if line_commitment <= 0 or line_commitment > remaining_budget + 0.01:
            return False
        selected_indexes.add(int(candidate["index"]))
        lines.append(line)
        remaining_budget -= line_commitment
        used_jumps += jump_cost
        category_spend[str(candidate["category"])] = category_spend.get(str(candidate["category"]), 0.0) + line_commitment
        return True

    for category in category_names:
        if len(lines) >= MAX_ACQUISITION_PORTFOLIO_LINES:
            break
        candidate = candidates_by_category[category][0]
        try_add_candidate(candidate, line_budget=category_budget_target)

    added = True
    while added and len(lines) < MAX_ACQUISITION_PORTFOLIO_LINES:
        added = False
        for candidate in candidates:
            category = str(candidate["category"])
            if target_category_count > 1 and category_spend.get(category, 0.0) >= category_budget_cap:
                continue
            line_budget = category_budget_cap - category_spend.get(category, 0.0)
            if target_category_count == 1:
                line_budget = remaining_budget
            if try_add_candidate(candidate, line_budget=line_budget):
                added = True
            if len(lines) >= MAX_ACQUISITION_PORTFOLIO_LINES:
                break

    for candidate in candidates:
        if int(candidate["index"]) in selected_indexes:
            continue
        opportunity = candidate["opportunity"]
        category = str(candidate["category"])
        jump_cost = int(candidate["jump_cost"])
        unit_commitment = float(candidate["unit_commitment"])
        if len(lines) >= MAX_ACQUISITION_PORTFOLIO_LINES:
            reason_key = "line_cap"
            reason_label = "Line cap"
            detail = "The diversified portfolio hit the maximum number of funded lines."
        elif used_jumps + jump_cost > clean_max_jumps:
            reason_key = "jump_cap"
            reason_label = "Jump cap"
            detail = "Adding this row would exceed the remaining portfolio jump budget."
        elif unit_commitment > remaining_budget:
            reason_key = "budget_cap"
            reason_label = "Budget cap"
            detail = "The remaining investment budget could not fund even one more unit."
        elif target_category_count > 1 and category_spend.get(category, 0.0) >= category_budget_cap:
            reason_key = "budget_cap"
            reason_label = "Budget cap"
            detail = "This category already reached its diversification budget cap."
        elif str(opportunity.get("risk_level") or "") == "caution":
            reason_key = "history_weakness"
            reason_label = "History weakness"
            detail = "A caution-level history signal made this lower priority than clearer funded rows."
        else:
            reason_key = "margin_too_low"
            reason_label = "Margin too low"
            detail = "This row ranked below funded alternatives on expected profit, margin, or risk."
        excluded_rows.append(
            acquisition_portfolio_exclusion_row(
                opportunity,
                reason_key=reason_key,
                reason_label=reason_label,
                detail=detail,
                category=category,
                jump_cost=jump_cost,
                unit_commitment=unit_commitment,
            )
        )

    invested_isk = sum(float(line["estimated_isk_committed"]) for line in lines)
    estimated_net_profit = sum(float(line["net_profit"]) for line in lines)
    category_allocations = []
    for category in sorted({str(line["category"]) for line in lines}):
        category_lines = [line for line in lines if str(line["category"]) == category]
        category_invested = sum(float(line["estimated_isk_committed"]) for line in category_lines)
        category_profit = sum(float(line["net_profit"]) for line in category_lines)
        category_jumps = sum(int(line["estimated_collection_jumps"]) for line in category_lines)
        category_allocations.append(
            {
                "category": category,
                "line_count": len(category_lines),
                "invested_isk": category_invested,
                "estimated_net_profit": category_profit,
                "used_jumps": category_jumps,
                "weight_percent": round_optional_float(category_invested / invested_isk * 100.0) if invested_isk > 0 else 0.0,
            }
        )
    category_allocations.sort(key=lambda item: (-float(item["invested_isk"]), str(item["category"])))
    return {
        "available": bool(lines),
        "strategy": "Diversified investment portfolio",
        "investment_budget_isk": clean_budget,
        "max_portfolio_jumps": clean_max_jumps,
        "invested_isk": invested_isk,
        "budget_remaining_isk": max(0.0, clean_budget - invested_isk),
        "estimated_net_profit": estimated_net_profit,
        "margin_percent": profit_margin_percent(estimated_net_profit, invested_isk) if invested_isk > 0 else None,
        "line_count": len(lines),
        "category_count": len(category_allocations),
        "used_jumps": used_jumps,
        "jumps_remaining": max(0, clean_max_jumps - used_jumps),
        "possible_trap_excluded_count": possible_trap_excluded_count,
        "caution_line_count": sum(1 for line in lines if str(line.get("risk_level") or "") == "caution"),
        "category_allocations": category_allocations,
        "excluded_rows": excluded_rows,
        "excluded_reason_counts": acquisition_exclusion_reason_counts(excluded_rows),
        "lines": lines,
        "manual_note": (
            "Portfolio lines spread the total ISK budget across item families and exclude Possible trap rows from "
            "funded recommendations. The jump budget is a planning cap for collection effort; actual pickup routes "
            "depend on where future buy-order fills land."
        ),
    }


def acquisition_exclusion_reason_counts(rows: Iterable[Mapping[str, Any]]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        key = str(row.get("reason_key") or "other")
        counts[key] = counts.get(key, 0) + 1
    return counts


def market_history_stats(history: Iterable[dict[str, Any]], *, days: int = 30) -> dict[str, Any]:
    rows = sorted((item for item in history if isinstance(item, dict)), key=lambda item: str(item.get("date") or ""))
    recent = rows[-max(1, int(days)) :]
    volumes = [float(item.get("volume") or 0.0) for item in recent]
    positive_volumes = [volume for volume in volumes if volume > 0]
    order_counts = [float(item.get("order_count") or 0.0) for item in recent]
    averages = [float(item.get("average") or 0.0) for item in recent if clean_optional_float(item.get("average"))]
    lows = [float(item.get("lowest") or 0.0) for item in recent if clean_optional_float(item.get("lowest"))]
    highs = [float(item.get("highest") or 0.0) for item in recent if clean_optional_float(item.get("highest"))]
    latest = recent[-1] if recent else {}
    return {
        "days": len(recent),
        "latest_date": str(latest.get("date") or ""),
        "latest_volume": clean_optional_int(latest.get("volume")) or 0,
        "latest_order_count": clean_optional_int(latest.get("order_count")) or 0,
        "latest_average": clean_optional_float(latest.get("average")),
        "avg_daily_volume": (sum(volumes) / len(volumes)) if volumes else 0.0,
        "median_daily_volume": median_number(positive_volumes) or 0.0,
        "days_with_volume": len(positive_volumes),
        "zero_volume_days": max(0, len(recent) - len(positive_volumes)),
        "avg_daily_order_count": (sum(order_counts) / len(order_counts)) if order_counts else 0.0,
        "median_average": median_number(averages),
        "median_low": median_number(lows),
        "median_high": median_number(highs),
    }


def market_history_window_comparison(history: Iterable[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    rows = list(history or [])
    return {
        "7_day": market_history_stats(rows, days=7),
        "30_day": market_history_stats(rows, days=30),
        "90_day": market_history_stats(rows, days=90),
    }


def combine_market_history_rows(histories: Iterable[Iterable[dict[str, Any]]]) -> list[dict[str, Any]]:
    by_date: dict[str, dict[str, Any]] = {}
    for history in histories:
        for row in history:
            if not isinstance(row, dict):
                continue
            date = str(row.get("date") or "").strip()
            if not date:
                continue
            volume = max(0.0, clean_optional_float(row.get("volume")) or 0.0)
            order_count = max(0.0, clean_optional_float(row.get("order_count")) or 0.0)
            average = clean_optional_float(row.get("average"))
            lowest = clean_optional_float(row.get("lowest"))
            highest = clean_optional_float(row.get("highest"))
            aggregate = by_date.setdefault(
                date,
                {
                    "date": date,
                    "volume": 0.0,
                    "order_count": 0.0,
                    "_average_value": 0.0,
                    "_average_weight": 0.0,
                    "lowest": None,
                    "highest": None,
                },
            )
            aggregate["volume"] = float(aggregate["volume"]) + volume
            aggregate["order_count"] = float(aggregate["order_count"]) + order_count
            if average is not None and average > 0:
                weight = volume if volume > 0 else 1.0
                aggregate["_average_value"] = float(aggregate["_average_value"]) + average * weight
                aggregate["_average_weight"] = float(aggregate["_average_weight"]) + weight
            if lowest is not None and lowest > 0:
                current_low = clean_optional_float(aggregate.get("lowest"))
                aggregate["lowest"] = lowest if current_low is None else min(current_low, lowest)
            if highest is not None and highest > 0:
                current_high = clean_optional_float(aggregate.get("highest"))
                aggregate["highest"] = highest if current_high is None else max(current_high, highest)

    combined = []
    for aggregate in by_date.values():
        average_weight = float(aggregate.pop("_average_weight", 0.0))
        average_value = float(aggregate.pop("_average_value", 0.0))
        aggregate["average"] = average_value / average_weight if average_weight > 0 else None
        aggregate["volume"] = int(round(float(aggregate["volume"])))
        aggregate["order_count"] = int(round(float(aggregate["order_count"])))
        combined.append(aggregate)
    return sorted(combined, key=lambda item: str(item.get("date") or ""))


def median_number(values: Iterable[float]) -> float | None:
    clean_values = sorted(float(value) for value in values if value is not None and float(value) > 0)
    count = len(clean_values)
    if not count:
        return None
    middle = count // 2
    if count % 2:
        return clean_values[middle]
    return (clean_values[middle - 1] + clean_values[middle]) / 2.0


def acquisition_liquidity_confidence(
    source_stats: dict[str, Any],
    *,
    units: int,
    target_days: int,
    history_analysis_mode: str,
) -> dict[str, Any]:
    clean_mode = normalize_acquisition_history_analysis_mode(history_analysis_mode)
    days = int(source_stats.get("days") or 0)
    avg_daily_volume = clean_optional_float(source_stats.get("avg_daily_volume")) or 0.0
    median_daily_volume = clean_optional_float(source_stats.get("median_daily_volume")) or 0.0
    avg_daily_orders = clean_optional_float(source_stats.get("avg_daily_order_count")) or 0.0
    baseline_volume = min(value for value in (avg_daily_volume, median_daily_volume) if value > 0) if any(
        value > 0 for value in (avg_daily_volume, median_daily_volume)
    ) else 0.0
    clean_units = max(1, int(units or 1))
    volume_window = baseline_volume * max(1, clamp_acquisition_target_days(target_days))
    coverage_ratio = volume_window / clean_units if clean_units > 0 else 0.0
    if clean_mode == "fast":
        level = "needs-audit"
        label = "Needs history audit"
        detail = "Fast shortlist skipped market-history checks, so liquidity is not verified yet."
    elif days < 7 or avg_daily_orders < 0.5 or coverage_ratio < 0.75:
        level = "sparse"
        label = "Sparse / unreliable history"
        detail = "Recent completed-trade history is too thin to treat the first order as reliable."
    elif avg_daily_orders < 1.5 or coverage_ratio < 1.25:
        level = "thin"
        label = "Thin market"
        detail = "History supports only a cautious test size; fills may be slow or uneven."
    elif avg_daily_orders >= 5 and coverage_ratio >= 3:
        level = "strong"
        label = "Strong liquidity"
        detail = "Recent source-region volume and order count comfortably cover the suggested test size."
    else:
        level = "moderate"
        label = "Moderate liquidity"
        detail = "Recent source-region history supports the size, but this is still a small manual candidate."
    return {
        "level": level,
        "label": label,
        "detail": detail,
        "coverage_ratio": coverage_ratio,
        "avg_daily_volume": avg_daily_volume,
        "median_daily_volume": median_daily_volume,
        "avg_daily_order_count": avg_daily_orders,
        "history_days": days,
    }


def acquisition_competition_pressure(
    best_source_buy: dict[str, Any] | None,
    *,
    max_safe_bid: float,
    suggested_bid: float,
) -> dict[str, Any]:
    highest_source_buy = clean_optional_float((best_source_buy or {}).get("price"))
    safe_bid = max(0.0, float(max_safe_bid or 0.0))
    suggested = max(0.0, float(suggested_bid or 0.0))
    suggested_headroom = max(0.0, safe_bid - suggested)
    if highest_source_buy is None or highest_source_buy <= 0:
        return {
            "level": "none-visible",
            "label": "No visible source buy competition",
            "detail": "No reachable competing source buy order was visible in the scanned pickup area.",
            "highest_source_buy": None,
            "safe_bid_ceiling": round_optional_float(safe_bid),
            "suggested_bid": round_optional_float(suggested),
            "bid_headroom": round_optional_float(suggested_headroom),
            "bid_headroom_percent": None,
            "suggested_bid_headroom": round_optional_float(suggested_headroom),
        }
    bid_headroom = safe_bid - highest_source_buy
    bid_headroom_percent = round_optional_float(bid_headroom / safe_bid * 100.0) if safe_bid > 0 else None
    if bid_headroom <= 0:
        level = "no-headroom"
        label = "No bid headroom"
        detail = "The highest visible source buy order is already at or above the safe bid ceiling."
    elif bid_headroom_percent is not None and bid_headroom_percent < 3:
        level = "tight"
        label = "Tight competition"
        detail = "Visible source buy competition leaves very little room below the safe bid ceiling."
    elif bid_headroom_percent is not None and bid_headroom_percent < 10:
        level = "moderate"
        label = "Moderate competition"
        detail = "There is some bid headroom, but verify the current order stack before posting."
    else:
        level = "room"
        label = "Bid headroom"
        detail = "The current source buy side leaves room below the safe bid ceiling."
    return {
        "level": level,
        "label": label,
        "detail": detail,
        "highest_source_buy": round_optional_float(highest_source_buy),
        "safe_bid_ceiling": round_optional_float(safe_bid),
        "suggested_bid": round_optional_float(suggested),
        "bid_headroom": round_optional_float(bid_headroom),
        "bid_headroom_percent": bid_headroom_percent,
        "suggested_bid_headroom": round_optional_float(suggested_headroom),
    }


def acquisition_buyer_concentration(
    destination_buy_orders: Iterable[dict[str, Any]],
    *,
    min_profitable_destination_price: float,
    units: int,
) -> dict[str, Any]:
    clean_units = max(1, int(units or 1))
    supporting_orders = [
        order
        for order in destination_buy_orders
        if (clean_optional_float(order.get("price")) or 0.0) >= float(min_profitable_destination_price or 0.0)
    ]
    supporting_volume = sum(max(0, clean_optional_int(order.get("volume_remain")) or 0) for order in supporting_orders)
    largest_order_units = max([max(0, clean_optional_int(order.get("volume_remain")) or 0) for order in supporting_orders] or [0])
    units_from_largest = min(clean_units, largest_order_units)
    largest_order_share_percent = round_optional_float(units_from_largest / clean_units * 100.0) if clean_units > 0 else 0.0
    if not supporting_orders:
        level = "unsupported"
        label = "No supporting buyer depth"
        detail = "No visible destination buy order remained above the profitable sale price after fees."
    elif len(supporting_orders) == 1 or largest_order_share_percent >= 80:
        level = "single-order"
        label = "Single-buyer dependency"
        detail = "Most expected resale depends on one destination buy order; verify it in EVE before posting."
    elif largest_order_share_percent >= 50:
        level = "concentrated"
        label = "Concentrated buyer depth"
        detail = "A large share of the expected resale depends on one visible destination buyer."
    else:
        level = "distributed"
        label = "Distributed buyer depth"
        detail = "Expected resale is spread across more than one visible destination buy order."
    return {
        "level": level,
        "label": label,
        "detail": detail,
        "supporting_order_count": len(supporting_orders),
        "supporting_volume": supporting_volume,
        "largest_order_units": largest_order_units,
        "largest_order_share_percent": largest_order_share_percent,
        "min_profitable_destination_price": round_optional_float(min_profitable_destination_price) or 0.0,
    }


def acquisition_failure_reasons(
    *,
    history_analysis_mode: str,
    flags: Iterable[dict[str, str]],
    liquidity: Mapping[str, Any],
    buyer_concentration: Mapping[str, Any],
    competition_pressure: Mapping[str, Any],
    best_source_sell: Mapping[str, Any] | None,
    best_destination_buy: Mapping[str, Any] | None,
) -> list[str]:
    reasons: list[str] = []
    clean_mode = normalize_acquisition_history_analysis_mode(history_analysis_mode)
    if clean_mode == "fast":
        reasons.append("Fast shortlist skipped market-history analysis; run Basic or Advanced before committing ISK.")
    for flag in flags:
        severity = str(flag.get("severity") or "")
        if severity in {"trap", "caution"}:
            detail = str(flag.get("detail") or flag.get("label") or "").strip()
            if detail and detail not in reasons:
                reasons.append(detail)
    if str(liquidity.get("level") or "") in {"needs-audit", "thin", "sparse"}:
        detail = str(liquidity.get("detail") or "").strip()
        if detail and detail not in reasons:
            reasons.append(detail)
    if str(buyer_concentration.get("level") or "") in {"single-order", "concentrated", "unsupported"}:
        detail = str(buyer_concentration.get("detail") or "").strip()
        if detail and detail not in reasons:
            reasons.append(detail)
    if str(competition_pressure.get("level") or "") in {"no-headroom", "tight"}:
        detail = str(competition_pressure.get("detail") or "").strip()
        if detail and detail not in reasons:
            reasons.append(detail)
    for label, order in (("Source sell", best_source_sell), ("Destination buy", best_destination_buy)):
        kind = str((order or {}).get("location_kind") or "")
        note = str((order or {}).get("location_access_note") or "")
        if kind in {"player-structure", "unknown"} and note:
            reasons.append(f"{label} access risk: {note}")
    reasons.append("Current orders can be changed, filled, or canceled before your manual order fills.")
    return reasons[:8]


def acquisition_suggested_bid(
    *,
    max_safe_bid: float,
    best_source_buy: dict[str, Any] | None,
    best_source_sell: dict[str, Any] | None,
    source_history: dict[str, Any],
) -> float:
    candidates = []
    if best_source_buy is not None:
        candidates.append(float(best_source_buy.get("price") or 0.0) * 1.01)
    median_average = clean_optional_float(source_history.get("median_average"))
    if median_average:
        candidates.append(median_average * 0.85)
    if best_source_sell is not None:
        candidates.append(float(best_source_sell.get("price") or 0.0) * 0.85)
    if not candidates:
        candidates.append(max_safe_bid * 0.75)
    positive_candidates = [value for value in candidates if value > 0]
    if not positive_candidates:
        return 0.0
    return min(max_safe_bid, max(positive_candidates))


def acquisition_history_unit_cap(source_stats: dict[str, Any], *, target_days: int) -> int:
    avg_daily_volume = clean_optional_float(source_stats.get("avg_daily_volume")) or 0.0
    if avg_daily_volume <= 0:
        return 1
    return max(1, int(avg_daily_volume * clamp_acquisition_target_days(target_days)))


def acquisition_history_flags(
    *,
    source_stats: dict[str, Any],
    destination_stats: dict[str, Any],
    best_source_buy: dict[str, Any] | None,
    best_source_sell: dict[str, Any] | None,
    best_destination_buy: dict[str, Any],
    max_safe_bid: float,
    suggested_bid: float,
    units: int,
    target_days: int,
    history_analysis_mode: str = DEFAULT_ACQUISITION_HISTORY_ANALYSIS_MODE,
    liquidity_confidence: Mapping[str, Any] | None = None,
    buyer_concentration: Mapping[str, Any] | None = None,
    competition_pressure: Mapping[str, Any] | None = None,
) -> list[dict[str, str]]:
    flags: list[dict[str, str]] = []
    clean_mode = normalize_acquisition_history_analysis_mode(history_analysis_mode)
    if clean_mode == "fast":
        flags.append(
            {
                "severity": "caution",
                "label": "Needs history audit",
                "detail": "Fast shortlist skipped market-history checks; run Basic guardrails or Advanced trap audit before committing ISK.",
            }
        )
    source_days = int(source_stats.get("days") or 0)
    destination_days = int(destination_stats.get("days") or 0)
    if clean_mode != "fast" and source_days < 7:
        flags.append(
            {
                "severity": "caution",
                "label": "Limited source history",
                "detail": "This item has less than a week of source-region history, so fill speed is uncertain.",
            }
        )
    source_daily_volume = clean_optional_float(source_stats.get("avg_daily_volume")) or 0.0
    if source_daily_volume > 0 and units > source_daily_volume * max(1, int(target_days)):
        flags.append(
            {
                "severity": "caution",
                "label": "Thin fill volume",
                "detail": "Recommended units are above the recent source-region volume window.",
            }
        )
    source_daily_orders = clean_optional_float(source_stats.get("avg_daily_order_count")) or 0.0
    if source_days and source_daily_orders < 1.5:
        flags.append(
            {
                "severity": "caution",
                "label": "Sparse source orders",
                "detail": "Recent history shows few daily market orders, so a buy order may sit for a long time.",
            }
        )
    destination_median = clean_optional_float(destination_stats.get("median_average"))
    destination_price = float(best_destination_buy.get("price") or 0.0)
    if destination_days >= 7 and destination_median and destination_price > destination_median * 1.75:
        flags.append(
            {
                "severity": "trap",
                "label": "Possible trap: price spike",
                "detail": "The best destination buy order is far above the recent market-history average; verify this is real demand before posting.",
            }
        )
    if best_source_buy is not None and float(best_source_buy.get("price") or 0.0) >= max_safe_bid:
        flags.append(
            {
                "severity": "trap",
                "label": "Possible trap: competition too high",
                "detail": "The current competing buy order is already at or above the safe bid ceiling.",
            }
        )
    if best_source_sell is not None and suggested_bid >= float(best_source_sell.get("price") or 0.0):
        flags.append(
            {
                "severity": "caution",
                "label": "Near instant-buy price",
                "detail": "The suggested bid is close to the lowest sell order; a buy order may not add much advantage.",
            }
        )
    if int(best_destination_buy.get("volume_remain") or 0) <= max(1, units // 3):
        flags.append(
            {
                "severity": "caution",
                "label": "Low destination depth",
                "detail": "The downstream buy order has limited remaining volume; recheck it before committing ISK.",
            }
        )
    if buyer_concentration is not None and str(buyer_concentration.get("level") or "") in {"single-order", "unsupported"}:
        flags.append(
            {
                "severity": "caution",
                "label": str(buyer_concentration.get("label") or "Buyer concentration"),
                "detail": str(buyer_concentration.get("detail") or "Expected resale depends on thin destination buyer depth."),
            }
        )
    if clean_mode == "advanced":
        if liquidity_confidence is not None and str(liquidity_confidence.get("level") or "") in {"thin", "sparse"}:
            flags.append(
                {
                    "severity": "caution",
                    "label": str(liquidity_confidence.get("label") or "Liquidity caution"),
                    "detail": str(liquidity_confidence.get("detail") or "Recent completed-trade history is thin."),
                }
            )
        if competition_pressure is not None and str(competition_pressure.get("level") or "") == "tight":
            flags.append(
                {
                    "severity": "caution",
                    "label": "Tight competition pressure",
                    "detail": str(competition_pressure.get("detail") or "Source buy competition leaves little bid headroom."),
                }
            )
    if not flags:
        flags.append(
            {
                "severity": "clear",
                "label": "No obvious contradiction",
                "detail": "Current orders and completed-trade history do not show an obvious trap signal.",
            }
        )
    return flags


def acquisition_risk_level(flags: Iterable[dict[str, str]]) -> str:
    severities = {str(flag.get("severity") or "") for flag in flags}
    if "trap" in severities:
        return "possible-trap"
    if "caution" in severities:
        return "caution"
    return "clear"


def acquisition_risk_sort_rank(risk_level: str) -> int:
    return {"clear": 0, "caution": 1, "possible-trap": 2}.get(risk_level, 3)


def acquisition_decision(*, risk_level: str, margin_percent: float | None) -> dict[str, str]:
    if risk_level == "possible-trap":
        return {
            "code": "verify",
            "tone": "price",
            "label": "Verify before posting",
            "reason": "Market history shows a possible trap signal. Treat this as a lead, not a trade.",
        }
    if margin_percent is not None and margin_percent >= 25:
        return {
            "code": "place-small",
            "tone": "build",
            "label": "Place a small order",
            "reason": "The spread survives fees and the history does not show a major warning.",
        }
    if margin_percent is not None and margin_percent > 0:
        return {
            "code": "test",
            "tone": "source",
            "label": "Test with low volume",
            "reason": "The margin is positive, but keep the first order small until fills prove demand.",
        }
    return {
        "code": "watch",
        "tone": "watch",
        "label": "Watch only",
        "reason": "The current spread is not strong enough after estimated fees.",
    }


def hauling_history_flags(
    *,
    pickup_stats: dict[str, Any],
    destination_stats: dict[str, Any],
    average_pickup_price: float,
    average_destination_price: float,
    units: int,
) -> list[dict[str, str]]:
    flags: list[dict[str, str]] = []
    pickup_days = int(pickup_stats.get("days") or 0)
    destination_days = int(destination_stats.get("days") or 0)
    if pickup_days < 7:
        flags.append(
            {
                "severity": "caution",
                "label": "Limited pickup history",
                "detail": "The matched pickup region has less than a week of public history for this item.",
            }
        )
    if destination_days < 7:
        flags.append(
            {
                "severity": "caution",
                "label": "Limited destination history",
                "detail": "The destination region has less than a week of public history, so demand is hard to trust.",
            }
        )

    destination_daily_volume = clean_optional_float(destination_stats.get("avg_daily_volume")) or 0.0
    if destination_daily_volume > 0 and units > max(10.0, destination_daily_volume * 3.0):
        flags.append(
            {
                "severity": "trap",
                "label": "Possible trap: demand exceeds history",
                "detail": "The matched buy-order depth is much larger than recent destination-region daily volume.",
            }
        )
    elif destination_daily_volume > 0 and units > max(5.0, destination_daily_volume):
        flags.append(
            {
                "severity": "caution",
                "label": "Thin destination volume",
                "detail": "The haul size is larger than recent destination-region daily volume.",
            }
        )

    destination_daily_orders = clean_optional_float(destination_stats.get("avg_daily_order_count")) or 0.0
    if destination_days and destination_daily_orders < 1.5:
        flags.append(
            {
                "severity": "caution",
                "label": "Sparse destination orders",
                "detail": "Recent destination history has few daily market orders, so the buy side may be fragile.",
            }
        )

    destination_median = clean_optional_float(destination_stats.get("median_average"))
    if destination_days >= 7 and destination_median and average_destination_price > destination_median * 1.75:
        flags.append(
            {
                "severity": "trap",
                "label": "Possible trap: price spike",
                "detail": "The matched destination buy price is far above recent market-history average; verify the order in EVE before hauling.",
            }
        )

    pickup_median = clean_optional_float(pickup_stats.get("median_average"))
    if pickup_days >= 7 and pickup_median and average_pickup_price < pickup_median * 0.5:
        flags.append(
            {
                "severity": "caution",
                "label": "Unusually cheap pickup",
                "detail": "The matched pickup price is far below recent market history; verify docking access, location, and minimum volume.",
            }
        )

    if not flags:
        flags.append(
            {
                "severity": "clear",
                "label": "History supports a cautious haul",
                "detail": "Recent history and current orders do not show an obvious trap signal.",
            }
        )
    return flags


def hauling_decision(*, risk_level: str, margin_percent: float | None) -> dict[str, str]:
    if risk_level == "possible-trap":
        return {
            "code": "verify",
            "tone": "price",
            "label": "Verify in EVE first",
            "reason": "Market history shows a possible trap signal. Treat this as a price-check candidate before hauling.",
        }
    if risk_level == "caution":
        return {
            "code": "test",
            "tone": "watch",
            "label": "Small manual haul",
            "reason": "The spread is positive, but history is thin or unusual enough to recheck before filling the hold.",
        }
    if margin_percent is not None and margin_percent >= 25:
        return {
            "code": "haul",
            "tone": "build",
            "label": "Manual haul candidate",
            "reason": "The spread survives tax and recent history does not show a major warning.",
        }
    return {
        "code": "watch",
        "tone": "watch",
        "label": "Low-margin watch",
        "reason": "The opportunity is profitable, but the margin is modest. Verify current orders before undocking.",
    }


def acquisition_range_recommendation(
    *,
    risk_level: str,
    source_stats: dict[str, Any],
    units: int,
    pickup_jumps: int,
    margin_percent: float | None,
) -> dict[str, str]:
    avg_daily_volume = clean_optional_float(source_stats.get("avg_daily_volume")) or 0.0
    if risk_level == "possible-trap" or pickup_jumps <= 0:
        return {
            "range": "station",
            "reason": "Keep the order narrow until the history signal is verified.",
        }
    if avg_daily_volume >= max(units * 2, 10) and pickup_jumps >= 5 and (margin_percent or 0.0) >= 20:
        return {
            "range": "5 jumps",
            "reason": "History shows enough volume to justify a wider collection range, but plan for scattered deliveries.",
        }
    if avg_daily_volume >= max(units, 5) and pickup_jumps >= 1:
        return {
            "range": "solar system",
            "reason": "Use a system range first so fills stay easy to collect.",
        }
    return {
        "range": "station",
        "reason": "Thin history favors a narrow order that is easy to monitor.",
    }


def emit_haul_route_progress(
    *,
    progress: Callable[[str, dict[str, Any]], None] | None,
    route_path: list[int],
    pickup_detours: dict[int, int],
    systems: dict[int, RouteSystem],
    adjacency: dict[int, tuple[int, ...]],
    detour_jumps: int,
    destination_system_id: int,
    pickup_jump_distances: dict[int, int],
    scanned_materials: int,
    min_detour_margin_percent: float,
) -> None:
    if progress is None:
        return
    route_systems = [systems[system_id] for system_id in route_path if system_id in systems]
    progress(
        "scan_start",
        {
            "route_stop_count": len(route_systems),
            "route_jumps": max(0, len(route_path) - 1),
            "detour_jumps": detour_jumps,
            "pickup_system_count": len(pickup_jump_distances),
            "scanned_materials": scanned_materials,
            "min_detour_margin_percent": min_detour_margin_percent,
            "message": (
                f"Walking {len(route_systems)} route stops and {len(pickup_jump_distances)} pickup systems "
                f"before pricing {scanned_materials} item types."
            ),
        },
    )
    route_stop_count = len(route_systems)
    for route_index, route_system in enumerate(route_systems, start=1):
        nearby_distances = jump_distances_within(
            start_system_id=route_system.solar_system_id,
            max_jumps=detour_jumps,
            adjacency=adjacency,
        )
        nearby = []
        for system_id, jumps_from_route in sorted(
            nearby_distances.items(),
            key=lambda item: (item[1], systems.get(item[0], route_system).name),
        ):
            if system_id == destination_system_id:
                continue
            system = systems.get(system_id)
            if system is None or system_id not in pickup_detours:
                continue
            nearby.append(
                {
                    **system.to_dict(jumps=pickup_jump_distances.get(system_id, 0)),
                    "jumps_from_route": jumps_from_route,
                }
            )
        progress(
            "route_step",
            {
                "route_index": route_index,
                "route_stop_count": route_stop_count,
                "system": route_system.to_dict(jumps=route_index - 1),
                "nearby_system_count": len(nearby),
                "nearby_systems": nearby[:12],
                "nearby_truncated": len(nearby) > 12,
                "message": f"Scanning route stop {route_index}/{route_stop_count}: {route_system.name}",
            },
        )
        for nearby_system in nearby[:12]:
            if int(nearby_system.get("solar_system_id") or 0) == route_system.solar_system_id:
                continue
            progress(
                "nearby_system",
                {
                    "route_index": route_index,
                    "route_stop_count": route_stop_count,
                    "route_system_name": route_system.name,
                    "system": nearby_system,
                    "message": (
                        f"Checking nearby {nearby_system['name']} "
                        f"({nearby_system['jumps_from_route']}j from {route_system.name})"
                    ),
                },
            )


def scan_best_reachable_market_orders(
    *,
    config: EveSsoConfig,
    type_ids: Iterable[int],
    region_ids: Iterable[int],
    systems: dict[int, RouteSystem],
    jump_distances: dict[int, int],
    order_type: str,
) -> tuple[dict[int, dict[str, Any]], int, list[dict[str, Any]]]:
    best_orders: dict[int, dict[str, Any]] = {}
    total_order_count = 0
    errors = []
    clean_type_ids = [int(type_id) for type_id in type_ids if int(type_id) > 0]
    fetcher = fetch_market_buy_orders if order_type == "buy" else fetch_market_sell_orders
    for type_id in clean_type_ids:
        reachable_orders = []
        for region_id in region_ids:
            try:
                raw_orders = fetcher(config, region_id=region_id, type_id=type_id)
            except CorpMarketError as exc:
                errors.append({"order_type": order_type, "type_id": type_id, "region_id": region_id, "error": str(exc)})
                continue
            for order in raw_orders:
                record = build_reachable_market_order_record(
                    order,
                    systems=systems,
                    jump_distances=jump_distances,
                    region_id=region_id,
                    order_type=order_type,
                )
                if record is not None:
                    reachable_orders.append(record)
        reachable_orders.sort(key=lambda item: market_order_sort_key(item, order_type=order_type))
        total_order_count += len(reachable_orders)
        if reachable_orders:
            best_orders[type_id] = reachable_orders[0]
    return best_orders, total_order_count, errors


def resolve_jita_market_system(systems: dict[int, RouteSystem]) -> RouteSystem:
    for system in systems.values():
        if normalize_system_name(system.name) == normalize_system_name(JITA_SYSTEM_NAME) and system.region_id is not None:
            return system
    return RouteSystem(
        solar_system_id=JITA_SOLAR_SYSTEM_ID,
        name=JITA_SYSTEM_NAME,
        region_id=JITA_REGION_ID,
        security_status=0.9,
    )


def scan_system_market_orders(
    *,
    config: EveSsoConfig,
    type_ids: Iterable[int],
    system: RouteSystem,
    order_type: str,
) -> tuple[dict[int, list[dict[str, Any]]], int, list[dict[str, Any]]]:
    if system.region_id is None:
        return {}, 0, [{"order_type": order_type, "system_id": system.solar_system_id, "error": "System region is unknown."}]
    orders_by_type: dict[int, list[dict[str, Any]]] = {}
    total_order_count = 0
    errors = []
    fetcher = fetch_market_buy_orders if order_type == "buy" else fetch_market_sell_orders
    market_systems = {system.solar_system_id: system}
    jump_distances = {system.solar_system_id: 0}
    for type_id in [int(type_id) for type_id in type_ids if int(type_id) > 0]:
        system_orders = []
        try:
            raw_orders = fetcher(config, region_id=system.region_id, type_id=type_id)
        except CorpMarketError as exc:
            errors.append({"order_type": order_type, "type_id": type_id, "region_id": system.region_id, "error": str(exc)})
            continue
        for order in raw_orders:
            record = build_reachable_market_order_record(
                order,
                systems=market_systems,
                jump_distances=jump_distances,
                region_id=system.region_id,
                order_type=order_type,
            )
            if record is not None:
                system_orders.append(record)
        system_orders.sort(key=lambda item: market_order_sort_key(item, order_type=order_type))
        total_order_count += len(system_orders)
        if system_orders:
            orders_by_type[type_id] = system_orders
    return orders_by_type, total_order_count, errors


def liquidation_value_from_orders(orders: Iterable[dict[str, Any]], *, quantity: int) -> dict[str, Any]:
    required_quantity = max(0, int(quantity))
    remaining = required_quantity
    value = 0.0
    priced_quantity = 0
    used_orders = 0
    for order in orders:
        if remaining <= 0:
            break
        try:
            price = float(order.get("price") or 0.0)
            volume = int(order.get("volume_remain") or 0)
            min_volume = int(order.get("min_volume") or 1)
        except (TypeError, ValueError):
            continue
        if price <= 0 or volume <= 0 or required_quantity < max(1, min_volume):
            continue
        filled = min(remaining, volume)
        value += filled * price
        priced_quantity += filled
        remaining -= filled
        used_orders += 1
    return {
        "value": round(value, 2),
        "priced_quantity": priced_quantity,
        "required_quantity": required_quantity,
        "complete": required_quantity == 0 or priced_quantity >= required_quantity,
        "order_count": used_orders,
    }


def clean_plex_deal_quantity(value: Any, *, default: int) -> int:
    quantity = clean_optional_int(value)
    if quantity is None:
        quantity = default
    return max(PLEX_DEAL_MIN_QUANTITY, min(PLEX_DEAL_MAX_QUANTITY, quantity))


def plex_deal_quantity_targets(min_quantity: Any, max_quantity: Any) -> list[int]:
    clean_min = clean_plex_deal_quantity(min_quantity, default=DEFAULT_PLEX_DEAL_MIN_QUANTITY)
    clean_max = clean_plex_deal_quantity(max_quantity, default=DEFAULT_PLEX_DEAL_MAX_QUANTITY)
    if clean_min > clean_max:
        raise CorpMarketError("PLEX minimum quantity cannot be greater than maximum quantity.")
    targets = {clean_min, clean_max}
    first_step = ((clean_min + PLEX_DEAL_QUANTITY_STEP - 1) // PLEX_DEAL_QUANTITY_STEP) * PLEX_DEAL_QUANTITY_STEP
    for quantity in range(first_step, clean_max + 1, PLEX_DEAL_QUANTITY_STEP):
        if clean_min <= quantity <= clean_max:
            targets.add(quantity)
    return sorted(targets)


def plex_order_depth_quote(orders: Iterable[dict[str, Any]], *, quantity: int) -> dict[str, Any]:
    required_quantity = clean_plex_deal_quantity(quantity, default=DEFAULT_PLEX_DEAL_MIN_QUANTITY)
    remaining = required_quantity
    total_isk = 0.0
    priced_quantity = 0
    used_orders = 0
    used_prices: list[float] = []
    used_location_ids: list[int] = []
    visible_units = 0
    min_volume_blocked_orders = 0
    for order in orders:
        price = clean_optional_float(order.get("price"))
        volume = clean_optional_int(order.get("volume_remain")) or 0
        min_volume = max(1, clean_optional_int(order.get("min_volume")) or 1)
        if price is None or price <= 0 or volume <= 0:
            continue
        visible_units += volume
        if remaining <= 0:
            continue
        if remaining < min_volume:
            min_volume_blocked_orders += 1
            continue
        fill = min(remaining, volume)
        if fill < min_volume:
            min_volume_blocked_orders += 1
            continue
        total_isk += fill * price
        priced_quantity += fill
        remaining -= fill
        used_orders += 1
        used_prices.append(price)
        location_id = clean_optional_int(order.get("location_id"))
        if location_id is not None and location_id not in used_location_ids:
            used_location_ids.append(location_id)
    average_unit_price = total_isk / priced_quantity if priced_quantity > 0 else None
    return {
        "required_quantity": required_quantity,
        "priced_quantity": priced_quantity,
        "remaining_quantity": max(0, remaining),
        "complete": priced_quantity >= required_quantity,
        "total_isk": round(total_isk, 2),
        "average_unit_price": round(average_unit_price, 2) if average_unit_price is not None else None,
        "first_unit_price": round(used_prices[0], 2) if used_prices else None,
        "last_unit_price": round(used_prices[-1], 2) if used_prices else None,
        "order_count": used_orders,
        "visible_units": visible_units,
        "location_count": len(used_location_ids),
        "location_ids": used_location_ids[:5],
        "min_volume_blocked_orders": min_volume_blocked_orders,
    }


def plex_fuzzwork_aggregate_quote(
    aggregate: Mapping[str, Any] | None,
    *,
    side: str,
    quantity: int,
) -> dict[str, Any]:
    required_quantity = clean_plex_deal_quantity(quantity, default=DEFAULT_PLEX_DEAL_MIN_QUANTITY)
    clean_side = "buy" if side == "buy" else "sell"
    if not aggregate:
        return {
            "required_quantity": required_quantity,
            "priced_quantity": 0,
            "remaining_quantity": required_quantity,
            "complete": False,
            "total_isk": 0.0,
            "average_unit_price": None,
            "first_unit_price": None,
            "last_unit_price": None,
            "order_count": 0,
            "visible_units": 0,
            "location_count": 0,
            "location_ids": [],
            "min_volume_blocked_orders": 0,
        }
    if clean_side == "sell":
        unit_price = clean_optional_float(aggregate.get("top_buy_unit_price")) or clean_optional_float(
            aggregate.get("liquidation_unit_price")
        )
        visible_units = clean_optional_int(aggregate.get("buy_volume")) or 0
        order_count = clean_optional_int(aggregate.get("buy_order_count")) or 0
    else:
        unit_price = clean_optional_float(aggregate.get("sell_min_unit_price")) or clean_optional_float(
            aggregate.get("sell_percentile_unit_price")
        )
        visible_units = clean_optional_int(aggregate.get("sell_volume")) or 0
        order_count = clean_optional_int(aggregate.get("sell_order_count")) or 0
    if unit_price is None or unit_price <= 0:
        priced_quantity = 0
        total_isk = 0.0
    else:
        priced_quantity = min(required_quantity, max(0, visible_units))
        total_isk = priced_quantity * unit_price
    location_id = clean_optional_int(aggregate.get("location_id"))
    return {
        "required_quantity": required_quantity,
        "priced_quantity": priced_quantity,
        "remaining_quantity": max(0, required_quantity - priced_quantity),
        "complete": priced_quantity >= required_quantity,
        "total_isk": round(total_isk, 2),
        "average_unit_price": round(unit_price, 2) if unit_price is not None and unit_price > 0 else None,
        "first_unit_price": round(unit_price, 2) if unit_price is not None and unit_price > 0 else None,
        "last_unit_price": round(unit_price, 2) if unit_price is not None and unit_price > 0 else None,
        "order_count": order_count,
        "visible_units": max(0, visible_units),
        "location_count": 1 if location_id is not None else 0,
        "location_ids": [location_id] if location_id is not None else [],
        "min_volume_blocked_orders": 0,
        "source": "fuzzwork_aggregate",
        "source_label": str(aggregate.get("source_label") or "Fuzzwork aggregate"),
        "aggregate_estimate": True,
    }


def plex_deal_row(*, side: str, hub_name: str, quote: Mapping[str, Any]) -> dict[str, Any]:
    clean_side = "buy" if side == "buy" else "sell"
    aggregate_estimate = bool(quote.get("aggregate_estimate"))
    complete = bool(quote.get("complete"))
    required_quantity = clean_optional_int(quote.get("required_quantity")) or 0
    priced_quantity = clean_optional_int(quote.get("priced_quantity")) or 0
    average_unit_price = clean_optional_float(quote.get("average_unit_price"))
    total_isk = clean_optional_float(quote.get("total_isk"))
    if clean_side == "sell":
        label = f"Sell {required_quantity:,} PLEX now"
        direction = f"Sell into {hub_name} public buy orders."
        score = average_unit_price if average_unit_price is not None else -1.0
    else:
        label = f"Buy {required_quantity:,} PLEX now"
        direction = f"Buy from {hub_name} public sell orders."
        score = -average_unit_price if average_unit_price is not None else -1_000_000_000_000.0
    status = "complete" if complete else "partial"
    if priced_quantity <= 0:
        status = "unpriced"
    elif aggregate_estimate:
        status = "aggregate_estimate"
    return {
        "side": clean_side,
        "label": label,
        "status": status,
        "complete": complete,
        "quantity": required_quantity,
        "priced_quantity": priced_quantity,
        "remaining_quantity": clean_optional_int(quote.get("remaining_quantity")) or 0,
        "total_isk": total_isk,
        "average_unit_price": average_unit_price,
        "first_unit_price": clean_optional_float(quote.get("first_unit_price")),
        "last_unit_price": clean_optional_float(quote.get("last_unit_price")),
        "order_count": clean_optional_int(quote.get("order_count")) or 0,
        "visible_units": clean_optional_int(quote.get("visible_units")) or 0,
        "location_count": clean_optional_int(quote.get("location_count")) or 0,
        "location_ids": list(quote.get("location_ids") or [])[:5],
        "min_volume_blocked_orders": clean_optional_int(quote.get("min_volume_blocked_orders")) or 0,
        "source": str(quote.get("source") or "public_esi_orders"),
        "source_label": str(quote.get("source_label") or "Public ESI market orders"),
        "aggregate_estimate": aggregate_estimate,
        "hub": hub_name,
        "direction": direction,
        "manual_note": (
            "Fuzzwork aggregate estimate only; ESI returned no order-depth rows for this side, so verify the live "
            "market in EVE before acting."
            if aggregate_estimate
            else (
                "Gross public-order math only; verify taxes, fees, order min volume, station/structure access, "
                "and remaining order depth in EVE before acting."
            )
        ),
        "_score": score,
    }


def rank_plex_deal_rows(rows: Iterable[dict[str, Any]], *, side: str) -> list[dict[str, Any]]:
    def sort_key(row: dict[str, Any]) -> tuple[Any, ...]:
        complete_rank = 0 if row.get("complete") else 1
        average_price = clean_optional_float(row.get("average_unit_price"))
        quantity = clean_optional_int(row.get("quantity")) or 0
        total = clean_optional_float(row.get("total_isk")) or 0.0
        if side == "buy":
            price_rank = average_price if average_price is not None else float("inf")
            return (complete_rank, price_rank, total, quantity)
        price_rank = -(average_price if average_price is not None else -1.0)
        return (complete_rank, price_rank, -total, quantity)

    cleaned_rows = []
    for row in sorted(rows, key=sort_key)[:PLEX_DEAL_ROW_LIMIT]:
        cleaned = dict(row)
        cleaned.pop("_score", None)
        cleaned_rows.append(cleaned)
    return cleaned_rows


def build_plex_deal_payload(
    *,
    config: EveSsoConfig,
    hub_name: Any = "jita",
    min_quantity: Any = DEFAULT_PLEX_DEAL_MIN_QUANTITY,
    max_quantity: Any = DEFAULT_PLEX_DEAL_MAX_QUANTITY,
) -> dict[str, Any]:
    hub_key = normalize_bulk_appraisal_hub(hub_name)
    hub_system = bulk_appraisal_hub_system(hub_key)
    quantity_targets = plex_deal_quantity_targets(min_quantity, max_quantity)
    buy_orders_by_type, buy_order_count, buy_errors = scan_system_market_orders(
        config=config,
        type_ids=[PLEX_TYPE_ID],
        system=hub_system,
        order_type="buy",
    )
    sell_orders_by_type, sell_order_count, sell_errors = scan_system_market_orders(
        config=config,
        type_ids=[PLEX_TYPE_ID],
        system=hub_system,
        order_type="sell",
    )
    buy_orders = buy_orders_by_type.get(PLEX_TYPE_ID, [])
    sell_orders = sell_orders_by_type.get(PLEX_TYPE_ID, [])
    aggregate_errors: list[str] = []
    aggregate: dict[str, Any] | None = None
    station_detail = PUBLIC_MARKET_HUB_STATIONS.get(hub_key)
    if station_detail and (not buy_orders or not sell_orders):
        station_id, station_label = station_detail
        try:
            aggregate = fetch_fuzzwork_market_aggregates([PLEX_TYPE_ID], station_id=station_id).get(PLEX_TYPE_ID)
        except CorpMarketError as exc:
            aggregate_errors.append(f"Fuzzwork {station_label} aggregate fallback failed: {exc}")
    sell_visible_units = sum(max(0, clean_optional_int(order.get("volume_remain")) or 0) for order in buy_orders)
    buy_visible_units = sum(max(0, clean_optional_int(order.get("volume_remain")) or 0) for order in sell_orders)
    if not buy_orders and aggregate:
        sell_visible_units = clean_optional_int(aggregate.get("buy_volume")) or 0
        buy_order_count = clean_optional_int(aggregate.get("buy_order_count")) or buy_order_count
    if not sell_orders and aggregate:
        buy_visible_units = clean_optional_int(aggregate.get("sell_volume")) or 0
        sell_order_count = clean_optional_int(aggregate.get("sell_order_count")) or sell_order_count
    sell_rows = rank_plex_deal_rows(
        (
            plex_deal_row(
                side="sell",
                hub_name=hub_system.name,
                quote=(
                    plex_fuzzwork_aggregate_quote(aggregate, side="sell", quantity=quantity)
                    if not buy_orders and aggregate
                    else plex_order_depth_quote(buy_orders, quantity=quantity)
                ),
            )
            for quantity in quantity_targets
        ),
        side="sell",
    )
    buy_rows = rank_plex_deal_rows(
        (
            plex_deal_row(
                side="buy",
                hub_name=hub_system.name,
                quote=(
                    plex_fuzzwork_aggregate_quote(aggregate, side="buy", quantity=quantity)
                    if not sell_orders and aggregate
                    else plex_order_depth_quote(sell_orders, quantity=quantity)
                ),
            )
            for quantity in quantity_targets
        ),
        side="buy",
    )
    best_sell = next((row for row in sell_rows if row.get("complete")), sell_rows[0] if sell_rows else None)
    best_buy = next((row for row in buy_rows if row.get("complete")), buy_rows[0] if buy_rows else None)
    best_sell_price = clean_optional_float((best_sell or {}).get("average_unit_price"))
    best_buy_price = clean_optional_float((best_buy or {}).get("average_unit_price"))
    spread = best_buy_price - best_sell_price if best_buy_price is not None and best_sell_price is not None else None
    spread_percent = round_optional_float(spread / best_sell_price * 100.0) if spread is not None and best_sell_price and best_sell_price > 0 else None
    return {
        "ok": True,
        "generated_at": now_iso(),
        "item": {
            "type_id": PLEX_TYPE_ID,
            "name": PLEX_TYPE_NAME,
        },
        "hub": {
            "key": hub_key,
            "label": hub_system.name,
            "system_id": hub_system.solar_system_id,
            "region_id": hub_system.region_id,
        },
        "quantity_targets": quantity_targets,
        "min_quantity": quantity_targets[0],
        "max_quantity": quantity_targets[-1],
        "mode": "public_orders_gross",
        "fallback_source": {
            "source": aggregate.get("source") if aggregate else "",
            "source_label": aggregate.get("source_label") if aggregate else "",
            "location_id": aggregate.get("location_id") if aggregate else None,
            "location_name": aggregate.get("location_name") if aggregate else "",
            "used_for_sell": bool(aggregate and not buy_orders),
            "used_for_buy": bool(aggregate and not sell_orders),
        },
        "sell": {
            "label": "Sell PLEX into public buy orders",
            "order_count": buy_order_count,
            "visible_units": sell_visible_units,
            "best": best_sell,
            "deals": sell_rows,
        },
        "buy": {
            "label": "Buy PLEX from public sell orders",
            "order_count": sell_order_count,
            "visible_units": buy_visible_units,
            "best": best_buy,
            "deals": buy_rows,
        },
        "spread": {
            "gross_per_unit": spread,
            "gross_percent": spread_percent,
        },
        "errors": [*buy_errors, *sell_errors, *aggregate_errors],
        "market_cache": market_order_cache_status(),
        "fuzzwork_cache": fuzzwork_market_aggregate_cache_status(),
        "warnings": [
            "Public order depth can change quickly. Verify the exact order, min volume, station/structure access, taxes, and fees in EVE before acting.",
            "When ESI returns no PLEX order-depth rows, this finder uses a Fuzzwork station aggregate estimate and labels those rows as estimates.",
            "The app does not place market orders, buy PLEX, sell PLEX, create contracts, or read your wallet for this finder.",
        ],
    }


def format_plex_share_isk(value: Any) -> str:
    amount = clean_optional_float(value)
    if amount is None:
        return "unknown"
    return f"{amount:,.0f} ISK"


def build_plex_sell_share_line(*, hub_label: str, best_sell: Mapping[str, Any] | None) -> str:
    if not best_sell:
        return f"PLEX sell check: no sell-side price found in {hub_label}. Verify in EVE."
    quantity = clean_optional_int(best_sell.get("quantity")) or 0
    average_unit_price = clean_optional_float(best_sell.get("average_unit_price"))
    source_label = str(best_sell.get("source_label") or "Public market data")
    if quantity <= 0 or average_unit_price is None:
        return f"PLEX sell check: no sell-side price found in {hub_label}. Verify in EVE."
    source_prefix = "estimate source" if best_sell.get("aggregate_estimate") else "source"
    return (
        f"PLEX sell check: {quantity:,} PLEX in {hub_label} @ {format_plex_share_isk(average_unit_price)} "
        f"avg gross, {source_prefix}: {source_label}. Verify in EVE."
    )


def build_plex_hub_comparison_row(payload: Mapping[str, Any]) -> dict[str, Any]:
    hub = dict(payload.get("hub") or {})
    hub_label = str(hub.get("label") or hub.get("key") or "selected hub")
    best_sell = dict((payload.get("sell") or {}).get("best") or {})
    best_buy = dict((payload.get("buy") or {}).get("best") or {})
    spread = dict(payload.get("spread") or {})
    sell_average = clean_optional_float(best_sell.get("average_unit_price"))
    buy_average = clean_optional_float(best_buy.get("average_unit_price"))
    sell_total = clean_optional_float(best_sell.get("total_isk"))
    buy_total = clean_optional_float(best_buy.get("total_isk"))
    aggregate_warning = bool(best_sell.get("aggregate_estimate") or best_buy.get("aggregate_estimate"))
    return {
        "hub": hub,
        "best_sell": best_sell,
        "best_buy": best_buy,
        "sell_average_unit_price": sell_average,
        "buyback_average_unit_price": buy_average,
        "sell_gross_isk": sell_total,
        "buyback_gross_isk": buy_total,
        "buyback_comparison": {
            "buyback_quantity": clean_optional_int(best_buy.get("quantity")) or 0,
            "buyback_average_unit_price": buy_average,
            "buyback_gross_isk": buy_total,
            "spread_per_unit": clean_optional_float(spread.get("gross_per_unit")),
            "spread_percent": clean_optional_float(spread.get("gross_percent")),
        },
        "spread": spread,
        "source_label": str(best_sell.get("source_label") or ""),
        "aggregate_warning": aggregate_warning,
        "warning": (
            "Fuzzwork aggregate estimate; ESI returned no PLEX order-depth rows for at least one side."
            if aggregate_warning
            else ""
        ),
        "share_line": build_plex_sell_share_line(hub_label=hub_label, best_sell=best_sell),
        "errors": list(payload.get("errors") or []),
        "_sort_average": sell_average if sell_average is not None else -1.0,
        "_sort_total": sell_total if sell_total is not None else -1.0,
        "_sort_complete": 0 if best_sell.get("complete") else 1,
        "_sort_hub": ROUTE_SYSTEM_HUB_PRIORITY.get(str(hub.get("key") or "").lower(), 999),
    }


def build_plex_hub_comparison_payload(
    *,
    config: EveSsoConfig,
    min_quantity: Any = DEFAULT_PLEX_DEAL_MIN_QUANTITY,
    max_quantity: Any = DEFAULT_PLEX_DEAL_MAX_QUANTITY,
) -> dict[str, Any]:
    quantity_targets = plex_deal_quantity_targets(min_quantity, max_quantity)
    rows: list[dict[str, Any]] = []
    errors: list[str] = []
    for hub_key in PLEX_COMPARISON_HUBS:
        try:
            payload = build_plex_deal_payload(
                config=config,
                hub_name=hub_key,
                min_quantity=quantity_targets[0],
                max_quantity=quantity_targets[-1],
            )
        except CorpMarketError as exc:
            errors.append(f"{hub_key}: {exc}")
            continue
        rows.append(build_plex_hub_comparison_row(payload))

    rows.sort(
        key=lambda row: (
            row.get("_sort_complete", 1),
            -(clean_optional_float(row.get("_sort_average")) or -1.0),
            -(clean_optional_float(row.get("_sort_total")) or -1.0),
            int(row.get("_sort_hub", 999)),
        )
    )
    cleaned_rows: list[dict[str, Any]] = []
    for row in rows:
        cleaned = dict(row)
        for key in ("_sort_average", "_sort_total", "_sort_complete", "_sort_hub"):
            cleaned.pop(key, None)
        cleaned_rows.append(cleaned)
    recommendation = cleaned_rows[0] if cleaned_rows else None
    share_line = str((recommendation or {}).get("share_line") or "PLEX sell check: no hub result available. Verify in EVE.")
    return {
        "ok": True,
        "generated_at": now_iso(),
        "item": {
            "type_id": PLEX_TYPE_ID,
            "name": PLEX_TYPE_NAME,
        },
        "quantity_targets": quantity_targets,
        "min_quantity": quantity_targets[0],
        "max_quantity": quantity_targets[-1],
        "hubs": list(PLEX_COMPARISON_HUBS),
        "mode": "multi_hub_best_sell",
        "recommendation": recommendation,
        "rows": cleaned_rows,
        "share_line": share_line,
        "errors": errors,
        "warnings": [
            "Default recommendation is the best sell outcome. Buying back PLEX is shown only as a comparison.",
            "Rows marked as Fuzzwork aggregate estimates are not verified order-depth quotes; verify the live market in EVE.",
            "The app does not place market orders, buy PLEX, sell PLEX, create contracts, or read your wallet for this comparison.",
        ],
        "market_cache": market_order_cache_status(),
        "fuzzwork_cache": fuzzwork_market_aggregate_cache_status(),
    }


def market_order_sort_key(order: dict[str, Any], *, order_type: str) -> tuple[float, int, int]:
    price = float(order.get("price") or 0.0)
    price_rank = -price if order_type == "buy" else price
    return (price_rank, int(order.get("jumps") or 0), -int(order.get("volume_remain") or 0))


def build_haul_match_depth(
    orders: Iterable[dict[str, Any]],
    *,
    depth_prefix: str,
    excluded_depth_keys: set[str],
) -> list[dict[str, Any]]:
    depth: list[dict[str, Any]] = []
    for index, order in enumerate(orders):
        try:
            volume_remain = int(order.get("volume_remain") or 0)
            price = float(order.get("price") or 0.0)
        except (TypeError, ValueError):
            continue
        min_volume = max(1, clean_optional_int(order.get("min_volume")) or 1)
        depth_key = f"{depth_prefix}:{index}:{clean_optional_int(order.get('order_id')) or 0}"
        if depth_key in excluded_depth_keys:
            continue
        if volume_remain <= 0 or price <= 0 or min_volume > volume_remain:
            continue
        depth.append(
            {
                **order,
                "min_volume": min_volume,
                "_remaining": volume_remain,
                "_depth_key": depth_key,
            }
        )
    return depth


def haul_min_volume_blocked_depth_keys(matches: Iterable[dict[str, Any]], *, order_key: str) -> set[str]:
    units_by_key: dict[str, int] = {}
    min_volume_by_key: dict[str, int] = {}
    for match in matches:
        order = match.get(order_key) or {}
        depth_key = str(order.get("_depth_key") or "")
        if not depth_key:
            continue
        units_by_key[depth_key] = units_by_key.get(depth_key, 0) + int(match.get("units") or 0)
        min_volume_by_key[depth_key] = max(1, clean_optional_int(order.get("min_volume")) or 1)
    return {
        depth_key
        for depth_key, units in units_by_key.items()
        if units > 0 and units < min_volume_by_key.get(depth_key, 1)
    }


def public_haul_order_depth_match(match: dict[str, Any]) -> dict[str, Any]:
    public_match = dict(match)
    public_match["pickup_order"] = {
        key: value for key, value in (match.get("pickup_order") or {}).items() if not str(key).startswith("_")
    }
    public_match["destination_order"] = {
        key: value for key, value in (match.get("destination_order") or {}).items() if not str(key).startswith("_")
    }
    return public_match


def round_public_haul_order_depth_match(match: dict[str, Any]) -> dict[str, Any]:
    public_match = public_haul_order_depth_match(match)
    for key in ("pickup_price", "destination_price", "net_destination_price", "net_profit"):
        rounded = round_optional_float(public_match.get(key))
        if rounded is not None:
            public_match[key] = rounded
    for order_key in ("pickup_order", "destination_order"):
        order = public_match.get(order_key)
        if isinstance(order, dict):
            rounded_price = round_optional_float(order.get("price"))
            if rounded_price is not None:
                order["price"] = rounded_price
    return public_match


def match_haul_order_depth(
    *,
    sell_orders: list[dict[str, Any]],
    buy_orders: list[dict[str, Any]],
    cargo_capacity_m3: float,
    purchase_budget_isk: float,
    volume_m3: float | None,
    sales_tax_rate: float,
) -> dict[str, Any] | None:
    clean_tax_rate = max(0.0, min(1.0, float(sales_tax_rate or 0.0)))
    clean_cargo_capacity_m3 = clamp_haul_cargo_m3(cargo_capacity_m3)
    clean_purchase_budget_isk = clamp_haul_purchase_budget_isk(purchase_budget_isk)
    unit_volume = clean_optional_float(volume_m3)
    cargo_units = None
    if unit_volume is not None and unit_volume > 0:
        cargo_units = max(0, int((clean_cargo_capacity_m3 + 1e-9) / unit_volume))
        if cargo_units <= 0:
            return None

    excluded_sell_depth_keys: set[str] = set()
    excluded_buy_depth_keys: set[str] = set()
    while True:
        sell_depth = build_haul_match_depth(
            sell_orders,
            depth_prefix="sell",
            excluded_depth_keys=excluded_sell_depth_keys,
        )
        buy_depth = build_haul_match_depth(
            buy_orders,
            depth_prefix="buy",
            excluded_depth_keys=excluded_buy_depth_keys,
        )
        sell_index = 0
        buy_index = 0
        remaining_cargo_units = cargo_units
        matched_units = 0
        pickup_cost = 0.0
        gross_destination_revenue = 0.0
        net_destination_revenue = 0.0
        remaining_budget_isk = clean_purchase_budget_isk
        budget_limited = False
        matches: list[dict[str, Any]] = []

        while sell_index < len(sell_depth) and buy_index < len(buy_depth):
            sell_order = sell_depth[sell_index]
            buy_order = buy_depth[buy_index]
            sell_price = float(sell_order["price"])
            buy_price = float(buy_order["price"])
            net_buy_price = buy_price * (1.0 - clean_tax_rate)
            if net_buy_price <= sell_price:
                break

            available_units = min(int(sell_order["_remaining"]), int(buy_order["_remaining"]))
            if remaining_cargo_units is not None:
                available_units = min(available_units, remaining_cargo_units)
            affordable_units = int((remaining_budget_isk + 1e-9) // sell_price)
            if affordable_units <= 0:
                budget_limited = True
                break
            if affordable_units < available_units:
                budget_limited = True
                available_units = affordable_units
            if available_units <= 0:
                break

            line_pickup_cost = sell_price * available_units
            line_gross_destination_revenue = buy_price * available_units
            line_net_destination_revenue = net_buy_price * available_units
            pickup_cost += line_pickup_cost
            gross_destination_revenue += line_gross_destination_revenue
            net_destination_revenue += line_net_destination_revenue
            matched_units += available_units
            remaining_budget_isk = max(0.0, remaining_budget_isk - line_pickup_cost)
            matches.append(
                {
                    "units": available_units,
                    "pickup_order": {key: value for key, value in sell_order.items() if key != "_remaining"},
                    "destination_order": {key: value for key, value in buy_order.items() if key != "_remaining"},
                    "pickup_price": sell_price,
                    "destination_price": buy_price,
                    "net_destination_price": net_buy_price,
                    "net_profit": line_net_destination_revenue - line_pickup_cost,
                }
            )

            sell_order["_remaining"] = int(sell_order["_remaining"]) - available_units
            buy_order["_remaining"] = int(buy_order["_remaining"]) - available_units
            if remaining_cargo_units is not None:
                remaining_cargo_units -= available_units
                if remaining_cargo_units <= 0:
                    break
            if int(sell_order["_remaining"]) <= 0:
                sell_index += 1
            if int(buy_order["_remaining"]) <= 0:
                buy_index += 1

        if matched_units <= 0 or pickup_cost <= 0:
            return None
        blocked_sell_keys = haul_min_volume_blocked_depth_keys(matches, order_key="pickup_order")
        blocked_buy_keys = haul_min_volume_blocked_depth_keys(matches, order_key="destination_order")
        if not blocked_sell_keys and not blocked_buy_keys:
            break
        excluded_sell_depth_keys.update(blocked_sell_keys)
        excluded_buy_depth_keys.update(blocked_buy_keys)

    if matched_units <= 0 or pickup_cost <= 0:
        return None

    raw_public_matches = [public_haul_order_depth_match(match) for match in matches]
    display_public_matches = [round_public_haul_order_depth_match(match) for match in matches]
    pickup_systems: dict[int, dict[str, Any]] = {}
    pickup_system_order_ids: dict[int, set[int]] = {}
    pickup_order_ids: set[int] = set()
    destination_order_ids: set[int] = set()
    for match in raw_public_matches:
        pickup_order = match["pickup_order"]
        destination_order = match["destination_order"]
        pickup_order_id = int(pickup_order.get("order_id") or 0)
        pickup_order_ids.add(pickup_order_id)
        destination_order_ids.add(int(destination_order.get("order_id") or 0))
        system_id = int(pickup_order.get("system_id") or 0)
        pickup_system_order_ids.setdefault(system_id, set()).add(pickup_order_id)
        system_row = pickup_systems.setdefault(
            system_id,
            {
                "system_id": system_id,
                "system_name": pickup_order.get("system_name") or f"System {system_id}",
                "units": 0,
                "order_count": 0,
                "pickup_cost": 0.0,
            },
        )
        system_row["units"] = int(system_row["units"]) + int(match["units"])
        system_row["pickup_cost"] = float(system_row["pickup_cost"]) + float(match["pickup_price"]) * int(match["units"])
        system_row["order_count"] = len(pickup_system_order_ids[system_id])

    net_profit = net_destination_revenue - pickup_cost
    return {
        "units": matched_units,
        "pickup_order": display_public_matches[0]["pickup_order"],
        "destination_order": display_public_matches[0]["destination_order"],
        "average_pickup_price": round_optional_float(pickup_cost / matched_units),
        "average_destination_price": round_optional_float(gross_destination_revenue / matched_units),
        "average_net_destination_price": round_optional_float(net_destination_revenue / matched_units),
        "gross_spread_per_unit": round_optional_float((gross_destination_revenue - pickup_cost) / matched_units),
        "net_profit_per_unit": round_optional_float(net_profit / matched_units),
        "net_profit": round_optional_float(net_profit),
        "pickup_cost": round_optional_float(pickup_cost),
        "gross_destination_revenue": round_optional_float(gross_destination_revenue),
        "net_destination_revenue": round_optional_float(net_destination_revenue),
        "sales_tax_total": round_optional_float(gross_destination_revenue - net_destination_revenue),
        "budget_remaining_isk": round_optional_float(remaining_budget_isk),
        "matched_sell_order_count": len(pickup_order_ids),
        "matched_buy_order_count": len(destination_order_ids),
        "matched_order_pair_count": len(matches),
        "matched_pickup_system_count": len(pickup_systems),
        "matched_pickup_systems": sorted(
            pickup_systems.values(),
            key=lambda item: (-int(item["units"]), str(item["system_name"]), int(item["system_id"])),
        ),
        "order_depth": display_public_matches[:12],
        "load_plan_depth": raw_public_matches,
        "order_depth_truncated": len(raw_public_matches) > 12,
        "cargo_limited": cargo_units is not None and matched_units >= cargo_units,
        "budget_limited": budget_limited,
    }


def profit_sort_value(item: dict[str, Any]) -> float:
    taxed_replacement_profit = item.get("taxed_replacement_profit")
    if taxed_replacement_profit is not None:
        return float(taxed_replacement_profit)
    taxed_cash_profit = item.get("taxed_cash_profit")
    if taxed_cash_profit is not None:
        return float(taxed_cash_profit)
    replacement_profit = item.get("replacement_profit")
    if replacement_profit is not None:
        return float(replacement_profit)
    cash_profit = item.get("cash_profit")
    if cash_profit is not None:
        return float(cash_profit)
    return float("-inf")


def profitability_confidence(
    *,
    has_buyer: bool,
    can_build: bool,
    all_material_prices_known: bool,
    missing_prices_known: bool,
) -> str:
    if not has_buyer:
        return "no-buyer"
    if all_material_prices_known:
        return "strong"
    if can_build:
        return "owned-materials"
    if missing_prices_known:
        return "partial-replacement"
    return "incomplete"


def profitability_decision(
    *,
    has_buyer: bool,
    can_build: bool,
    missing_material_types: int,
    replacement_profit: float | None,
    cash_profit: float | None,
    all_material_prices_known: bool,
    missing_prices_known: bool,
) -> dict[str, Any]:
    if not has_buyer:
        return {
            "code": "skip",
            "label": "Skip",
            "rank": 60,
            "tone": "skip",
            "reason": "No nearby public buyer was found inside the jump range.",
        }
    if replacement_profit is not None and replacement_profit > 0 and can_build:
        return {
            "code": "build-now",
            "label": "Build Now",
            "rank": 10,
            "tone": "build",
            "reason": "Nearby buyer and current materials support an after-tax profitable one-run build.",
        }
    if replacement_profit is not None and replacement_profit > 0 and missing_material_types > 0 and missing_prices_known:
        return {
            "code": "source-missing",
            "label": "Buy Missing",
            "rank": 20,
            "tone": "source",
            "reason": "Still after-tax profitable after pricing the missing materials nearby.",
        }
    if cash_profit is not None and cash_profit > 0 and can_build:
        return {
            "code": "use-stock",
            "label": "Use Stock",
            "rank": 30,
            "tone": "stock",
            "reason": "Wallet-positive after tax with materials already on hand, but true profit is not positive.",
        }
    if has_buyer and not all_material_prices_known:
        return {
            "code": "price-check",
            "label": "Price Check",
            "rank": 40,
            "tone": "price",
            "reason": "A buyer exists, but one or more material prices were not found nearby.",
        }
    return {
        "code": "watch",
        "label": "Watch",
        "rank": 50,
        "tone": "watch",
        "reason": "A buyer exists, but current nearby pricing does not clear the profit threshold.",
    }


def profit_margin_percent(profit: float | None, revenue: float | None) -> float | None:
    if profit is None or revenue is None or revenue <= 0:
        return None
    return round((float(profit) / float(revenue)) * 100.0, 2)


def adjusted_job_time_seconds(base_seconds: int, time_efficiency: int, runs: int = 1) -> int:
    clean_base = max(0, int(base_seconds))
    clean_runs = max(1, int(runs))
    if clean_base <= 0:
        return 0
    efficiency = clean_blueprint_efficiency(time_efficiency)
    numerator = clean_base * clean_runs * (100 - efficiency)
    return max(1, -(-numerator // 100))


def isk_per_hour(profit: float | None, job_time_seconds: int) -> float | None:
    if profit is None or job_time_seconds <= 0:
        return None
    return round((float(profit) / float(job_time_seconds)) * 3600.0, 2)


def owned_blueprint_product_targets(
    *,
    blueprints: Iterable[dict[str, Any]],
    recipes: dict[int, IndustryRecipe],
) -> list[dict[str, Any]]:
    owned_blueprints = [
        blueprint
        for item in blueprints
        if isinstance(item, dict)
        for blueprint in [owned_blueprint_from_esi(item)]
        if blueprint is not None
    ]
    targets_by_product_id: dict[int, dict[str, Any]] = {}
    for blueprint in sorted(
        owned_blueprints,
        key=lambda item: (-blueprint_quality_rank(item)[0], -item.material_efficiency, -item.time_efficiency, item.type_id),
    ):
        recipe = recipes.get(blueprint.type_id)
        if recipe is None:
            continue
        target = targets_by_product_id.setdefault(
            recipe.product_type_id,
            {
                "product_type_id": recipe.product_type_id,
                "product_name": recipe.product_name,
                "product_quantity": recipe.product_quantity,
                "manufacturing_time_seconds": recipe.manufacturing_time_seconds,
                "max_production_limit": recipe.max_production_limit,
                "required_skills": [skill.to_dict() for skill in recipe.skills],
                "blueprint_type_id": recipe.blueprint_type_id,
                "blueprint_name": recipe.blueprint_name,
                "owned_blueprints": 0,
                "owned_originals": 0,
                "owned_copies": 0,
                "blueprint_material_efficiency": 0,
                "blueprint_time_efficiency": 0,
                "blueprint_runs": None,
                "blueprint_kind": "Blueprint",
                "blueprint_usable": False,
            },
        )
        target["owned_blueprints"] = int(target["owned_blueprints"]) + 1
        if blueprint.is_original:
            target["owned_originals"] = int(target["owned_originals"]) + 1
        if blueprint.is_copy:
            target["owned_copies"] = int(target["owned_copies"]) + 1
        current_rank = target.get("_quality_rank")
        candidate_rank = blueprint_quality_rank(blueprint)
        if current_rank is None or candidate_rank > current_rank:
            target.update(
                {
                    "blueprint_type_id": recipe.blueprint_type_id,
                    "blueprint_name": recipe.blueprint_name,
                    "product_quantity": recipe.product_quantity,
                    "manufacturing_time_seconds": recipe.manufacturing_time_seconds,
                    "max_production_limit": recipe.max_production_limit,
                    "required_skills": [skill.to_dict() for skill in recipe.skills],
                    "blueprint_material_efficiency": blueprint.material_efficiency,
                    "blueprint_time_efficiency": blueprint.time_efficiency,
                    "blueprint_runs": blueprint.limited_runs,
                    "blueprint_kind": blueprint.kind,
                    "blueprint_usable": blueprint.usable_for_one_run,
                    "_quality_rank": candidate_rank,
                }
            )
    for target in targets_by_product_id.values():
        target.pop("_quality_rank", None)
    return sorted(targets_by_product_id.values(), key=lambda item: (-int(item["owned_blueprints"]), item["product_name"]))


def build_buyer_order_record(
    order: dict[str, Any],
    *,
    target: dict[str, Any],
    systems: dict[int, RouteSystem],
    jump_distances: dict[int, int],
    region_id: int,
) -> dict[str, Any] | None:
    record = build_reachable_market_order_record(
        order,
        systems=systems,
        jump_distances=jump_distances,
        region_id=region_id,
        order_type="buy",
    )
    if record is None:
        return None
    return {
        **record,
        "product_type_id": target["product_type_id"],
        "product_name": target["product_name"],
        "blueprint_type_id": target["blueprint_type_id"],
        "blueprint_name": target["blueprint_name"],
    }


def market_order_location_guardrail(location_id: Any) -> dict[str, Any]:
    clean_location_id = clean_optional_int(location_id) or 0
    if clean_location_id >= PLAYER_STRUCTURE_LOCATION_ID_MIN:
        return {
            "location_kind": "player-structure",
            "location_kind_label": "Player structure",
            "docking_access_verified": False,
            "location_access_note": (
                "Player-structure market order; verify docking, market access, and service state in EVE before buying or hauling."
            ),
        }
    if clean_location_id > 0:
        return {
            "location_kind": "npc-station",
            "location_kind_label": "NPC station",
            "docking_access_verified": False,
            "location_access_note": (
                "NPC station market order; docking is usually public, but this app has not verified your in-game access."
            ),
        }
    return {
        "location_kind": "unknown",
        "location_kind_label": "Unknown location",
        "docking_access_verified": False,
        "location_access_note": "Market order location was not identified; verify docking and market access in EVE.",
    }


def build_reachable_market_order_record(
    order: dict[str, Any],
    *,
    systems: dict[int, RouteSystem],
    jump_distances: dict[int, int],
    region_id: int,
    order_type: str,
) -> dict[str, Any] | None:
    try:
        system_id = int(order.get("system_id") or 0)
        price = float(order.get("price") or 0)
        volume_remain = int(order.get("volume_remain") or 0)
    except (TypeError, ValueError):
        return None
    if order_type == "buy" and order.get("is_buy_order") is False:
        return None
    if order_type == "sell" and order.get("is_buy_order") is True:
        return None
    if system_id not in jump_distances or price <= 0 or volume_remain <= 0:
        return None
    system = systems.get(system_id)
    if system is None:
        return None
    location_id = clean_optional_int(order.get("location_id")) or 0
    return {
        "order_id": clean_optional_int(order.get("order_id")) or 0,
        "region_id": region_id,
        "system_id": system_id,
        "system_name": system.name,
        "jumps": jump_distances[system_id],
        "location_id": location_id,
        **market_order_location_guardrail(location_id),
        "price": price,
        "volume_remain": volume_remain,
        "min_volume": clean_optional_int(order.get("min_volume")) or 1,
        "range": str(order.get("range") or ""),
        "issued": str(order.get("issued") or ""),
        "duration": clean_optional_int(order.get("duration")) or 0,
    }


def industry_material_trade_targets(recipes: dict[int, IndustryRecipe]) -> list[dict[str, Any]]:
    material_counts: dict[int, int] = {}
    material_names: dict[int, str] = {}
    material_volumes: dict[int, float | None] = {}
    for recipe in recipes.values():
        for material in recipe.materials:
            material_counts[material.type_id] = material_counts.get(material.type_id, 0) + 1
            material_names[material.type_id] = material.name
            if material.volume_m3 is not None:
                material_volumes[material.type_id] = material.volume_m3
    targets = [
        {
            "type_id": type_id,
            "name": material_names.get(type_id) or f"Type {type_id}",
            "recipe_count": count,
            "volume_m3": material_volumes.get(type_id),
        }
        for type_id, count in material_counts.items()
    ]
    return sorted(targets, key=lambda item: (-int(item["recipe_count"]), str(item["name"]), int(item["type_id"])))


def build_market_item_targets(
    *,
    config: EveSsoConfig,
    recipe_cache: IndustryRecipeCache,
    include_common_materials: bool,
    market_group_ids: Iterable[int],
    market_type_ids: Iterable[int] = (),
    market_type_names: Iterable[Any] = (),
    common_material_limit: int = MAX_FLIGHT_HAUL_MATERIAL_TYPES,
    scan_type_limit: int = MAX_FLIGHT_HAUL_SCAN_TYPES,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    selected_market_group_ids = clean_haul_market_group_ids(market_group_ids)
    explicit_market_type_ids = clean_haul_market_type_ids(market_type_ids)
    pasted_type_limit = max(0, MAX_HAUL_MARKET_TYPE_IDS - len(explicit_market_type_ids))
    pasted_market_type_ids, pasted_market_type_meta = resolve_haul_market_type_names(
        market_type_names,
        limit=pasted_type_limit,
    )
    selected_market_type_ids = clean_haul_market_type_ids(
        (*explicit_market_type_ids, *pasted_market_type_ids),
        limit=MAX_HAUL_MARKET_TYPE_IDS,
    )
    pasted_market_type_id_set = set(pasted_market_type_ids)
    explicit_market_type_id_set = set(explicit_market_type_ids)
    common_targets = []
    common_candidate_count = 0
    clean_common_material_limit = max(0, int(common_material_limit))
    clean_scan_type_limit = max(1, int(scan_type_limit))
    if include_common_materials:
        common_candidates = industry_material_trade_targets(recipe_cache.recipes or {})
        common_candidate_count = len(common_candidates)
        common_targets = common_candidates[:clean_common_material_limit]
        for target in common_targets:
            target["source"] = "common_material"
            target["source_label"] = "Common materials"
    market_group_targets: list[dict[str, Any]] = []
    market_group_meta: dict[str, Any] = {
        "source": "",
        "selected_market_groups": [],
        "selected_market_group_ids": list(selected_market_group_ids),
        "selected_market_group_count": len(selected_market_group_ids),
        "market_group_item_types": 0,
    }
    if selected_market_group_ids:
        market_group_targets, market_group_meta = build_market_group_targets(config, selected_market_group_ids)
    market_type_targets: list[dict[str, Any]] = []
    market_type_meta: dict[str, Any] = {
        "source": "",
        "selected_market_types": [],
        "selected_market_type_ids": list(selected_market_type_ids),
        "selected_market_type_count": len(selected_market_type_ids),
        "market_type_item_types": 0,
    }
    if selected_market_type_ids:
        market_type_targets, market_type_meta = build_market_type_targets(config, selected_market_type_ids)

    targets_by_type_id: dict[int, dict[str, Any]] = {}
    for target in common_targets:
        type_id = int(target["type_id"])
        targets_by_type_id[type_id] = {
            **target,
            "recipe_count": int(target.get("recipe_count") or 0),
            "source_rank": 0,
            "source_labels": ["Common materials"],
        }
    for target in market_type_targets:
        type_id = int(target["type_id"])
        exact_source_labels = []
        if type_id in explicit_market_type_id_set:
            exact_source_labels.append("Selected items")
        if type_id in pasted_market_type_id_set:
            exact_source_labels.append("Pasted items")
        if not exact_source_labels:
            exact_source_labels.append("Selected items")
        existing = targets_by_type_id.get(type_id)
        if existing is None:
            targets_by_type_id[type_id] = {
                **target,
                "recipe_count": int(target.get("recipe_count") or 0),
                "source_rank": 1,
                "source_labels": exact_source_labels,
            }
            continue
        for source_label in exact_source_labels:
            if source_label not in existing["source_labels"]:
                existing["source_labels"].append(source_label)
        if not existing.get("volume_m3") and target.get("volume_m3"):
            existing["volume_m3"] = target.get("volume_m3")
        existing["market_group_id"] = target.get("market_group_id")
        existing["market_group_name"] = target.get("market_group_name")
    for target in market_group_targets:
        type_id = int(target["type_id"])
        existing = targets_by_type_id.get(type_id)
        if existing is None:
            targets_by_type_id[type_id] = {
                **target,
                "recipe_count": int(target.get("recipe_count") or 0),
                "source_rank": 2,
                "source_labels": [str(target.get("source_label") or "Market category")],
            }
            continue
        source_label = str(target.get("source_label") or "Market category")
        if source_label not in existing["source_labels"]:
            existing["source_labels"].append(source_label)
        if not existing.get("volume_m3") and target.get("volume_m3"):
            existing["volume_m3"] = target.get("volume_m3")
        existing["market_group_id"] = target.get("market_group_id")
        existing["market_group_name"] = target.get("market_group_name")

    targets = sorted(
        targets_by_type_id.values(),
        key=lambda item: (
            int(item["source_rank"]) if item.get("source_rank") is not None else 9,
            str(item.get("name") or ""),
            int(item.get("type_id") or 0),
        ),
    )
    return targets, {
        "include_common_materials": bool(include_common_materials),
        "common_material_scan_limit": clean_common_material_limit,
        "common_material_item_types": len(common_targets),
        "common_material_available_item_types": common_candidate_count,
        "selected_market_group_ids": market_group_meta.get("selected_market_group_ids", list(selected_market_group_ids)),
        "selected_market_groups": market_group_meta.get("selected_market_groups", []),
        "selected_market_group_count": int(market_group_meta.get("selected_market_group_count") or 0),
        "market_group_source": market_group_meta.get("source") or "",
        "market_group_item_types": int(market_group_meta.get("market_group_item_types") or 0),
        "selected_market_type_ids": market_type_meta.get("selected_market_type_ids", list(selected_market_type_ids)),
        "selected_market_types": market_type_meta.get("selected_market_types", []),
        "selected_market_type_count": int(market_type_meta.get("selected_market_type_count") or 0),
        "market_type_source": market_type_meta.get("source") or "",
        "market_type_item_types": int(market_type_meta.get("market_type_item_types") or 0),
        "explicit_market_type_ids": list(explicit_market_type_ids),
        **pasted_market_type_meta,
        "total_item_types": len(targets),
        "scan_type_limit": clean_scan_type_limit,
    }


def build_haul_item_targets(
    *,
    config: EveSsoConfig,
    recipe_cache: IndustryRecipeCache,
    include_common_materials: bool,
    market_group_ids: Iterable[int],
    market_type_ids: Iterable[int] = (),
    market_type_names: Iterable[Any] = (),
    common_material_limit: int = MAX_FLIGHT_HAUL_MATERIAL_TYPES,
    scan_type_limit: int = MAX_FLIGHT_HAUL_SCAN_TYPES,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    return build_market_item_targets(
        config=config,
        recipe_cache=recipe_cache,
        include_common_materials=include_common_materials,
        market_group_ids=market_group_ids,
        market_type_ids=market_type_ids,
        market_type_names=market_type_names,
        common_material_limit=common_material_limit,
        scan_type_limit=scan_type_limit,
    )


def resolve_route_system(route_cache: RouteGraphCache, name: str) -> RouteSystem | None:
    systems = route_cache.systems or {}
    normalized = normalize_system_name(name)
    if not normalized:
        normalized = normalize_system_name(DEFAULT_HAUL_DESTINATION_SYSTEM)
    normalized = ROUTE_SYSTEM_ALIASES.get(normalized, normalized)
    for system in systems.values():
        if normalize_system_name(system.name) == normalized:
            return system
    return None


def normalize_system_name(value: Any) -> str:
    return re.sub(r"[^a-z0-9]+", "", str(value or "").strip().lower())


def route_system_aliases_by_canonical() -> dict[str, tuple[str, ...]]:
    aliases: dict[str, list[str]] = {}
    for alias, canonical in {**ROUTE_SYSTEM_ALIASES, **ROUTE_SYSTEM_SUGGEST_ALIAS_PREFIXES}.items():
        aliases.setdefault(canonical, []).append(alias)
    return {canonical: tuple(sorted(set(values))) for canonical, values in aliases.items()}


def route_system_suggestion_score(
    system: RouteSystem,
    normalized_query: str,
    aliases_by_canonical: Mapping[str, tuple[str, ...]],
) -> tuple[int, int, int, str] | None:
    normalized_name = normalize_system_name(system.name)
    aliases = aliases_by_canonical.get(normalized_name, ())
    name_parts = tuple(
        normalize_system_name(part)
        for part in re.split(r"[^a-z0-9]+", system.name.lower())
        if normalize_system_name(part)
    )
    if normalized_name == normalized_query:
        match_rank = 0
    elif normalized_name.startswith(normalized_query):
        match_rank = 1
    elif any(alias.startswith(normalized_query) for alias in aliases):
        match_rank = 1
    elif any(part.startswith(normalized_query) for part in name_parts):
        match_rank = 2
    elif normalized_query in normalized_name or any(normalized_query in alias for alias in aliases):
        match_rank = 3
    else:
        return None
    hub_rank = ROUTE_SYSTEM_HUB_PRIORITY.get(normalized_name, 99)
    return (match_rank, hub_rank, len(normalized_name), system.name.lower())


def clamp_route_system_suggestion_limit(value: Any) -> int:
    try:
        limit = int(value)
    except (TypeError, ValueError):
        limit = MAX_ROUTE_SYSTEM_SUGGESTIONS
    return max(1, min(MAX_ROUTE_SYSTEM_SUGGESTIONS, limit))


def search_route_system_names(
    query: str,
    *,
    route_cache: RouteGraphCache | None = None,
    limit: int = MAX_ROUTE_SYSTEM_SUGGESTIONS,
) -> list[dict[str, Any]]:
    normalized_query = normalize_system_name(query)
    if len(normalized_query) < MIN_ROUTE_SYSTEM_SUGGESTION_CHARS:
        return []
    normalized_query = ROUTE_SYSTEM_SUGGEST_ALIAS_PREFIXES.get(
        normalized_query,
        ROUTE_SYSTEM_ALIASES.get(normalized_query, normalized_query),
    )
    cache = route_cache or load_route_graph_cache()
    if not cache.available:
        return []
    aliases_by_canonical = route_system_aliases_by_canonical()
    ranked: list[tuple[tuple[int, int, int, str], RouteSystem]] = []
    for system in (cache.systems or {}).values():
        score = route_system_suggestion_score(system, normalized_query, aliases_by_canonical)
        if score is not None:
            ranked.append((score, system))
    clean_limit = clamp_route_system_suggestion_limit(limit)
    return [system.to_dict() for _score, system in sorted(ranked, key=lambda item: item[0])[:clean_limit]]


def build_route_system_suggestions_payload(
    query: str,
    *,
    route_cache: RouteGraphCache | None = None,
    limit: int = MAX_ROUTE_SYSTEM_SUGGESTIONS,
) -> dict[str, Any]:
    cache = route_cache or load_route_graph_cache()
    systems = search_route_system_names(query, route_cache=cache, limit=limit)
    return {
        "ok": True,
        "available": cache.available,
        "error": cache.error,
        "query": str(query or ""),
        "min_query_length": MIN_ROUTE_SYSTEM_SUGGESTION_CHARS,
        "limit": clamp_route_system_suggestion_limit(limit),
        "system_count": cache.system_count,
        "systems": systems,
    }


def normalize_market_type_search(value: Any) -> str:
    return re.sub(r"[^a-z0-9]+", "", str(value or "").strip().lower())


def market_type_suggestion_score(type_info: Mapping[str, Any], normalized_query: str) -> tuple[int, int, str, int] | None:
    type_name = str(type_info.get("name") or "")
    normalized_name = normalize_market_type_search(type_name)
    if not normalized_name:
        return None
    name_parts = tuple(
        normalize_market_type_search(part)
        for part in re.split(r"[^a-z0-9]+", type_name.lower())
        if normalize_market_type_search(part)
    )
    if normalized_name == normalized_query:
        match_rank = 0
    elif normalized_name.startswith(normalized_query):
        match_rank = 1
    elif any(part.startswith(normalized_query) for part in name_parts):
        match_rank = 2
    elif normalized_query in normalized_name:
        match_rank = 3
    else:
        return None
    try:
        type_id = int(type_info.get("type_id") or 0)
    except (TypeError, ValueError):
        type_id = 0
    return (match_rank, len(normalized_name), type_name.casefold(), type_id)


def clamp_market_type_suggestion_limit(value: Any) -> int:
    try:
        limit = int(value)
    except (TypeError, ValueError):
        limit = MAX_MARKET_TYPE_SUGGESTIONS
    return max(1, min(MAX_MARKET_TYPE_SUGGESTIONS, limit))


def search_market_type_names(
    query: str,
    *,
    static_data: StaticMarketData | None = None,
    limit: int = MAX_MARKET_TYPE_SUGGESTIONS,
) -> list[dict[str, Any]]:
    normalized_query = normalize_market_type_search(query)
    if len(normalized_query) < MIN_MARKET_TYPE_SUGGESTION_CHARS:
        return []
    data = static_data if static_data is not None else load_static_market_data()
    if data is None:
        return []
    ranked: list[tuple[tuple[int, int, str, int], dict[str, Any]]] = []
    for type_infos in data.types_by_group.values():
        for type_info in type_infos:
            score = market_type_suggestion_score(type_info, normalized_query)
            if score is None:
                continue
            try:
                type_id = int(type_info.get("type_id") or 0)
                group_id = int(type_info.get("market_group_id") or 0)
            except (TypeError, ValueError):
                continue
            if type_id <= 0:
                continue
            ranked.append(
                (
                    score,
                    {
                        "type_id": type_id,
                        "name": str(type_info.get("name") or f"Type {type_id}"),
                        "market_group_id": group_id,
                        "market_group_name": str(
                            type_info.get("market_group_name")
                            or data.groups.get(group_id, {}).get("name")
                            or f"Market Group {group_id}"
                        ),
                    },
                )
            )
    clean_limit = clamp_market_type_suggestion_limit(limit)
    return [item for _score, item in sorted(ranked, key=lambda row: row[0])[:clean_limit]]


def build_market_type_suggestions_payload(
    query: str,
    *,
    static_data: StaticMarketData | None = None,
    limit: int = MAX_MARKET_TYPE_SUGGESTIONS,
) -> dict[str, Any]:
    data = static_data if static_data is not None else load_static_market_data()
    suggestions = search_market_type_names(query, static_data=data, limit=limit) if data is not None else []
    return {
        "ok": True,
        "available": data is not None,
        "query": str(query or ""),
        "min_query_length": MIN_MARKET_TYPE_SUGGESTION_CHARS,
        "limit": clamp_market_type_suggestion_limit(limit),
        "suggestions": suggestions,
    }


def build_haul_route_plan(
    *,
    config: EveSsoConfig,
    origin_solar_system_id: int,
    destination_solar_system_id: int,
    route_preference: str,
    avoid_recent_pod_kills: bool,
    adjacency: dict[int, tuple[int, ...]],
) -> dict[str, Any]:
    clean_preference = normalize_haul_route_preference(route_preference)
    recent_pod_kill_system_ids: tuple[int, ...] = ()
    warning = ""
    pod_kill_lookup_error = ""
    if avoid_recent_pod_kills:
        try:
            recent_pod_kill_system_ids = fetch_recent_pod_kill_system_ids(config)
        except CorpMarketError as exc:
            pod_kill_lookup_error = str(exc)
            warning = pod_kill_lookup_error
    recent_pod_kill_set = set(recent_pod_kill_system_ids)
    avoided_system_ids: set[int] = set()
    route_path: list[int] = []
    source = "esi-route"
    route_error = ""
    esi_attempt_count = 0
    for _attempt in range(4):
        try:
            esi_attempt_count += 1
            candidate_path = fetch_esi_route_path(
                config,
                origin_solar_system_id=origin_solar_system_id,
                destination_solar_system_id=destination_solar_system_id,
                route_preference=clean_preference,
                avoid_system_ids=avoided_system_ids,
            )
        except CorpMarketError as exc:
            route_error = str(exc)
            break
        route_path = candidate_path
        if not avoid_recent_pod_kills or not recent_pod_kill_set:
            break
        route_pod_kill_ids = [
            system_id
            for system_id in route_path
            if system_id in recent_pod_kill_set
            and system_id not in {origin_solar_system_id, destination_solar_system_id}
        ]
        new_avoids = [system_id for system_id in route_pod_kill_ids if system_id not in avoided_system_ids]
        if not new_avoids:
            break
        remaining_slots = MAX_HAUL_ROUTE_AVOID_SYSTEMS - len(avoided_system_ids)
        if remaining_slots <= 0:
            warning = warning or f"Route avoid list reached {MAX_HAUL_ROUTE_AVOID_SYSTEMS} systems."
            break
        avoided_system_ids.update(new_avoids[:remaining_slots])
        if len(new_avoids) > remaining_slots:
            warning = warning or f"Route avoid list reached {MAX_HAUL_ROUTE_AVOID_SYSTEMS} systems."
            break
    if not route_path:
        route_path = shortest_route_path(
            start_system_id=origin_solar_system_id,
            destination_system_id=destination_solar_system_id,
            adjacency=adjacency,
        )
        source = "local-shortest-fallback"
        warning = warning or route_error or "ESI route planner was unavailable; using local shortest route."
    route_pod_kill_ids = [
        system_id
        for system_id in route_path
        if system_id in recent_pod_kill_set and system_id not in {origin_solar_system_id, destination_solar_system_id}
    ]
    if avoid_recent_pod_kills and route_pod_kill_ids and not warning:
        warning = "Some recent pod-kill systems could not be avoided without losing the route."
    return {
        "path": route_path,
        "source": source,
        "preference": clean_preference,
        "preference_label": HAUL_ROUTE_ESI_PREFERENCES[clean_preference],
        "avoid_recent_pod_kills": bool(avoid_recent_pod_kills),
        "recent_pod_kill_system_count": len(recent_pod_kill_system_ids),
        "avoided_pod_kill_system_ids": sorted(avoided_system_ids),
        "route_pod_kill_system_ids": route_pod_kill_ids,
        "esi_attempt_count": esi_attempt_count,
        "route_error": route_error,
        "pod_kill_lookup_error": pod_kill_lookup_error,
        "warning": warning,
    }


def build_haul_route_diagnostics(route_plan: Mapping[str, Any], *, route_jumps: int) -> dict[str, Any]:
    source = str(route_plan.get("source") or "")
    preference_label = str(route_plan.get("preference_label") or "Safer")
    avoid_requested = bool(route_plan.get("avoid_recent_pod_kills"))
    fallback_used = source == "local-shortest-fallback"
    pod_kill_error = str(route_plan.get("pod_kill_lookup_error") or "")
    route_error = str(route_plan.get("route_error") or "")
    esi_attempt_count = clean_optional_int(route_plan.get("esi_attempt_count")) or 0
    recent_count = clean_optional_int(route_plan.get("recent_pod_kill_system_count")) or 0
    avoided_ids = list(route_plan.get("avoided_pod_kill_system_ids") or [])
    route_pod_ids = list(route_plan.get("route_pod_kill_system_ids") or [])
    avoided_count = len(avoided_ids)
    remaining_count = len(route_pod_ids)
    if not avoid_requested:
        pod_status = "not-requested"
        pod_status_label = "Not requested"
    elif pod_kill_error:
        pod_status = "unavailable"
        pod_status_label = "Pod-kill lookup unavailable"
    else:
        pod_status = "checked"
        pod_status_label = "Checked"
    if fallback_used:
        source_label = "Local shortest fallback"
        summary = (
            "ESI route planning did not return a path, so the scan used the local shortest-route graph. "
            "Verify this route in EVE before undocking."
        )
    elif avoid_requested and remaining_count > 0:
        source_label = "ESI route planner"
        summary = (
            f"ESI applied {preference_label} and attempted recent pod-kill avoidance, but "
            f"{remaining_count} recent pod-kill system{'s' if remaining_count != 1 else ''} remained on the route."
        )
    elif avoid_requested:
        source_label = "ESI route planner"
        summary = (
            f"ESI applied {preference_label} and recent pod-kill avoidance; no recent pod-kill systems "
            "remain on this path."
        )
    else:
        source_label = "ESI route planner"
        summary = f"ESI applied {preference_label}; recent pod-kill avoidance was not requested."
    steps = [
        f"Requested rule: {preference_label}",
        f"Route source: {source_label}",
        f"Route length: {max(0, int(route_jumps))} jumps",
        f"ESI route attempts: {esi_attempt_count}",
        f"Recent pod-kill check: {pod_status_label}",
    ]
    if avoid_requested:
        steps.append(f"Recent pod-kill systems known: {recent_count}")
        steps.append(f"Avoided on route: {avoided_count}")
        steps.append(f"Remaining on route: {remaining_count}")
    if route_error:
        steps.append(f"ESI route error: {route_error}")
    return {
        "summary": summary,
        "source": source,
        "source_label": source_label,
        "fallback_used": fallback_used,
        "route_rule_label": preference_label,
        "route_jumps": max(0, int(route_jumps)),
        "esi_attempt_count": esi_attempt_count,
        "avoid_recent_pod_kills": avoid_requested,
        "pod_kill_status": pod_status,
        "pod_kill_status_label": pod_status_label,
        "recent_pod_kill_system_count": recent_count,
        "avoided_pod_kill_system_count": avoided_count,
        "route_pod_kill_system_count": remaining_count,
        "warning": str(route_plan.get("warning") or ""),
        "steps": steps,
    }


def shortest_route_path(
    *,
    start_system_id: int,
    destination_system_id: int,
    adjacency: dict[int, tuple[int, ...]],
) -> list[int]:
    if start_system_id <= 0 or destination_system_id <= 0:
        return []
    if start_system_id == destination_system_id:
        return [start_system_id]
    parents: dict[int, int | None] = {start_system_id: None}
    frontier = [start_system_id]
    cursor = 0
    while cursor < len(frontier):
        system_id = frontier[cursor]
        cursor += 1
        for neighbor_id in adjacency.get(system_id, ()):
            if neighbor_id in parents:
                continue
            parents[neighbor_id] = system_id
            if neighbor_id == destination_system_id:
                path = [destination_system_id]
                parent = system_id
                while parent is not None:
                    path.append(parent)
                    parent = parents[parent]
                return list(reversed(path))
            frontier.append(neighbor_id)
    return []


def shortest_route_jumps_via_systems(
    *,
    start_system_id: int,
    destination_system_id: int,
    pickup_system_ids: Iterable[int],
    adjacency: dict[int, tuple[int, ...]],
) -> int | None:
    if start_system_id <= 0 or destination_system_id <= 0:
        return None
    required_system_ids: list[int] = []
    seen: set[int] = set()
    for raw_system_id in pickup_system_ids:
        system_id = int(raw_system_id or 0)
        if system_id <= 0 or system_id in {start_system_id, destination_system_id} or system_id in seen:
            continue
        seen.add(system_id)
        required_system_ids.append(system_id)
    if not required_system_ids:
        path = shortest_route_path(
            start_system_id=start_system_id,
            destination_system_id=destination_system_id,
            adjacency=adjacency,
        )
        return max(0, len(path) - 1) if path else None

    nodes = [start_system_id, destination_system_id, *required_system_ids]
    distances_by_node = {
        node: jump_distances_from(start_system_id=node, adjacency=adjacency)
        for node in nodes
    }

    if len(required_system_ids) > 10:
        unvisited = set(required_system_ids)
        current_system_id = start_system_id
        route_jumps = 0
        while unvisited:
            distances = distances_by_node.get(current_system_id) or {}
            reachable = [
                (int(distances[system_id]), system_id)
                for system_id in unvisited
                if system_id in distances
            ]
            if not reachable:
                return None
            next_distance, next_system_id = min(reachable, key=lambda item: (item[0], item[1]))
            route_jumps += next_distance
            current_system_id = next_system_id
            unvisited.remove(next_system_id)
        destination_distance = distances_by_node.get(current_system_id, {}).get(destination_system_id)
        if destination_distance is None:
            return None
        return route_jumps + int(destination_distance)

    best_by_state: dict[tuple[int, int], int] = {}
    for index, system_id in enumerate(required_system_ids):
        distance = distances_by_node[start_system_id].get(system_id)
        if distance is not None:
            best_by_state[(1 << index, index)] = int(distance)

    full_mask = (1 << len(required_system_ids)) - 1
    for mask in range(1, full_mask + 1):
        for last_index, last_system_id in enumerate(required_system_ids):
            current_distance = best_by_state.get((mask, last_index))
            if current_distance is None:
                continue
            distances = distances_by_node[last_system_id]
            for next_index, next_system_id in enumerate(required_system_ids):
                next_bit = 1 << next_index
                if mask & next_bit:
                    continue
                leg_distance = distances.get(next_system_id)
                if leg_distance is None:
                    continue
                next_state = (mask | next_bit, next_index)
                next_distance = current_distance + int(leg_distance)
                previous = best_by_state.get(next_state)
                if previous is None or next_distance < previous:
                    best_by_state[next_state] = next_distance

    best_total: int | None = None
    for last_index, last_system_id in enumerate(required_system_ids):
        current_distance = best_by_state.get((full_mask, last_index))
        if current_distance is None:
            continue
        destination_distance = distances_by_node[last_system_id].get(destination_system_id)
        if destination_distance is None:
            continue
        total_distance = current_distance + int(destination_distance)
        if best_total is None or total_distance < best_total:
            best_total = total_distance
    return best_total


def route_corridor_systems(
    *,
    route_path: list[int],
    adjacency: dict[int, tuple[int, ...]],
    detour_jumps: int,
    destination_system_id: int,
) -> dict[int, int]:
    clean_detour_jumps = clamp_haul_detour_jumps(detour_jumps)
    corridor: dict[int, int] = {}
    for route_system_id in route_path:
        nearby = jump_distances_within(
            start_system_id=route_system_id,
            max_jumps=clean_detour_jumps,
            adjacency=adjacency,
        )
        for system_id, jumps_from_route in nearby.items():
            if system_id == destination_system_id:
                continue
            previous = corridor.get(system_id)
            if previous is None or jumps_from_route < previous:
                corridor[system_id] = jumps_from_route
    return corridor


def jump_distances_from(
    *,
    start_system_id: int,
    adjacency: dict[int, tuple[int, ...]],
    max_jumps: int | None = None,
) -> dict[int, int]:
    if start_system_id <= 0:
        return {}
    distances = {start_system_id: 0}
    frontier = [start_system_id]
    cursor = 0
    while cursor < len(frontier):
        system_id = frontier[cursor]
        cursor += 1
        next_distance = distances[system_id] + 1
        if max_jumps is not None and next_distance > max_jumps:
            continue
        for neighbor_id in adjacency.get(system_id, ()):
            if neighbor_id in distances:
                continue
            distances[neighbor_id] = next_distance
            frontier.append(neighbor_id)
    return distances


def jump_distances_within(
    *,
    start_system_id: int,
    max_jumps: int,
    adjacency: dict[int, tuple[int, ...]],
) -> dict[int, int]:
    distances = {start_system_id: 0}
    frontier = [start_system_id]
    while frontier:
        system_id = frontier.pop(0)
        next_distance = distances[system_id] + 1
        if next_distance > max_jumps:
            continue
        for neighbor_id in adjacency.get(system_id, ()):
            if neighbor_id in distances:
                continue
            distances[neighbor_id] = next_distance
            frontier.append(neighbor_id)
    return distances


def clamp_flight_max_jumps(value: Any) -> int:
    try:
        jumps = int(value)
    except (TypeError, ValueError):
        jumps = DEFAULT_FLIGHT_MAX_JUMPS
    return max(0, min(MAX_FLIGHT_MAX_JUMPS, jumps))


