        def _handle_discord_alert_test(self) -> None:
            try:
                payload = self._read_json_body()
            except (ValueError, json.JSONDecodeError) as exc:
                self._send_json({"ok": False, "error": f"Invalid JSON: {exc}"}, status=400)
                return
            if not isinstance(payload, Mapping):
                self._send_json({"ok": False, "error": "Discord alert test payload must be a JSON object."}, status=400)
                return
            try:
                raw_settings = payload.get("settings")
                settings = (
                    clean_discord_alert_settings_payload(raw_settings)
                    if isinstance(raw_settings, Mapping)
                    else load_discord_alert_settings(discord_alert_settings_path)
                )
                raw_event = payload.get("event")
                event_payload = raw_event if isinstance(raw_event, Mapping) else {}
                route_name = clean_text(payload.get("route_name") or "", "Discord alert route name", max_length=100)
                rule_name = clean_text(payload.get("rule_name") or "", "Discord alert rule name", max_length=100)
                preview_payload = build_discord_alert_preview_payload(
                    settings,
                    route_name=route_name,
                    rule_name=rule_name,
                    event_payload=event_payload,
                )
                send = query_bool(payload.get("send"), default=False)
                result = None
                if send:
                    if not discord_webhook_url:
                        raise CorpMarketError("Discord webhook is not configured for this server.")
                    result = post_discord_webhook(
                        discord_webhook_url,
                        preview_payload,
                        timeout_seconds=discord_timeout_seconds,
                    )
            except (ValueError, CorpMarketError) as exc:
                self._send_json({"ok": False, "error": str(exc)}, status=400)
                return
            self._send_json(
                {
                    "ok": True,
                    "generated_at": now_iso(),
                    "webhook_configured": bool(discord_webhook_url),
                    "sent_to_discord": bool(result),
                    "discord_message": result.to_dict() if result else None,
                    "preview_payload": preview_payload,
                }
            )

        def _handle_direct_discord_post(self) -> None:
            try:
                payload = self._read_json_body()
            except (ValueError, json.JSONDecodeError) as exc:
                self._send_json({"ok": False, "error": f"Invalid JSON: {exc}"}, status=400)
                return
            if not isinstance(payload, Mapping):
                self._send_json({"ok": False, "error": "Direct Discord post payload must be a JSON object."}, status=400)
                return
            try:
                existing_settings, effective_settings = self._load_effective_discord_post_settings()
                raw_settings = payload.get("settings")
                send = query_bool(payload.get("send"), default=False)
                if send and not self._require_write_access():
                    return
                if (
                    send
                    and public_hosting_mode
                    and isinstance(raw_settings, Mapping)
                    and not self._request_has_admin_token()
                    and discord_settings_payload_has_webhook_override(raw_settings)
                ):
                    raise CorpMarketError(
                        "Public hosting mode requires the market admin token for per-request Discord webhook overrides."
                    )
                if isinstance(raw_settings, Mapping):
                    effective_settings = clean_discord_post_settings_payload(raw_settings, existing=effective_settings)
                raw_post = payload.get("post", payload)
                if not isinstance(raw_post, Mapping):
                    raise ValueError("Direct Discord post must be a JSON object.")
                post = clean_direct_discord_post_payload(raw_post)
                preview_payload = build_direct_discord_post_payload(post, effective_settings)
                result = None
                if send:
                    if not effective_settings.webhook_url:
                        raise CorpMarketError("Discord webhook is not configured for direct posts.")
                    result = post_discord_webhook(
                        effective_settings.webhook_url,
                        preview_payload,
                        timeout_seconds=discord_timeout_seconds,
                    )
            except (ValueError, CorpMarketError) as exc:
                self._send_json({"ok": False, "error": str(exc)}, status=400)
                return
            self._send_json(
                {
                    "ok": True,
                    "generated_at": now_iso(),
                    "webhook_configured": bool(effective_settings.webhook_url),
                    "webhook_url_preview": redacted_discord_webhook_url(effective_settings.webhook_url),
                    "sent_to_discord": bool(result),
                    "discord_message": result.to_dict() if result else None,
                    "post": post.to_dict(),
                    "settings": existing_settings.to_dict(),
                    "preview_payload": preview_payload,
                }
            )

        def _handle_fitting_list(self) -> None:
            params = parse_qs(urlparse(self.path).query)
            status = first_query_value(params, "status") or None
            include_archived = first_query_value(params, "include_archived").lower() in {"1", "true", "yes"}
            query = first_query_value(params, "q") or first_query_value(params, "query")
            try:
                fittings = store.list_shared_fittings(
                    status=status,
                    include_archived=include_archived,
                    query=query,
                )
            except (ValueError, CorpMarketError) as exc:
                self._send_json({"ok": False, "error": str(exc)}, status=400)
                return
            self._send_json(
                {
                    "ok": True,
                    "generated_at": now_iso(),
                    "fittings": [fitting.to_dict() for fitting in fittings],
                }
            )

